// SkateNet.js — Client-side WebSocket communication for Skatepark FFA Rooms.
//
// Speaks JSON text frames tagged `skate`:
//   out: { skate: 'join', room?, name?, dweebType?, color? }
//        { skate: 'pos', x, y, z, vx, vy, vz, yaw, pitch, mode }
//        { skate: 'shoot', origin, dir, id }
//        { skate: 'hit', targetId, damage }
//        { skate: 'trick', text, score }
//   in:  { skate: 'joined', room, slot, seed, matchTime }
//        { skate: 'snapshot', players, timeRemaining }
//        { skate: 'shot', senderId, origin, dir, id }
//        { skate: 'kill', killerName, victimName, weapon }
//        { skate: 'trick', playerName, text, score }

export class SkateNet {
  constructor({ serverUrl, onJoined, onSnapshot, onShot, onKill, onTrick } = {}) {
    this.serverUrl = serverUrl || null;
    this.onJoined = onJoined;
    this.onSnapshot = onSnapshot;
    this.onShot = onShot;
    this.onKill = onKill;
    this.onTrick = onTrick;

    this.socket = null;
    this.connected = false;
    this.roomCode = null;
    this.slot = null;
    this.lastSendTime = 0;
  }

  connect({ roomCode = '', playerName = 'Dweeb', dweebType = 'cube', color = '#ffea00' } = {}) {
    const defaultWs = (location.protocol === 'https:' ? 'wss://' : 'ws://') +
      (location.hostname || 'localhost') + (location.port ? `:${location.port}` : '');
    const url = this.serverUrl || defaultWs;

    try {
      this.socket = new WebSocket(url);
      this.socket.onopen = () => {
        this.connected = true;
        this.socket.send(JSON.stringify({
          skate: 'join',
          room: roomCode,
          name: playerName,
          dweebType,
          color,
        }));
      };

      this.socket.onmessage = (event) => {
        let msg = null;
        try {
          msg = JSON.parse(event.data);
        } catch {
          return;
        }
        if (!msg || typeof msg.skate !== 'string') return;

        switch (msg.skate) {
          case 'joined':
            this.roomCode = msg.room;
            this.slot = msg.slot;
            this.onJoined?.(msg);
            break;
          case 'snapshot':
            this.onSnapshot?.(msg);
            break;
          case 'shot':
            this.onShot?.(msg);
            break;
          case 'kill':
            this.onKill?.(msg);
            break;
          case 'trick':
            this.onTrick?.(msg);
            break;
        }
      };

      this.socket.onclose = () => {
        this.connected = false;
      };

      this.socket.onerror = () => {
        this.connected = false;
      };
    } catch {
      this.connected = false;
    }
  }

  sendPos(pos, vel, yaw, pitch, mode) {
    if (!this.connected || !this.socket || this.socket.readyState !== 1) return;
    const now = performance.now();
    if (now - this.lastSendTime < 45) return; // ~20 Hz
    this.lastSendTime = now;

    this.socket.send(JSON.stringify({
      skate: 'pos',
      x: pos.x,
      y: pos.y,
      z: pos.z,
      vx: vel.x,
      vy: vel.y,
      vz: vel.z,
      yaw,
      pitch,
      mode,
    }));
  }

  sendShoot(origin, dir, id) {
    if (!this.connected || !this.socket || this.socket.readyState !== 1) return;
    this.socket.send(JSON.stringify({
      skate: 'shoot',
      origin: [origin.x, origin.y, origin.z],
      dir: [dir.x, dir.y, dir.z],
      id,
    }));
  }

  sendHit(targetId, damage) {
    if (!this.connected || !this.socket || this.socket.readyState !== 1) return;
    this.socket.send(JSON.stringify({
      skate: 'hit',
      targetId,
      damage,
    }));
  }

  sendTrick(text, score) {
    if (!this.connected || !this.socket || this.socket.readyState !== 1) return;
    this.socket.send(JSON.stringify({
      skate: 'trick',
      text,
      score,
    }));
  }

  dispose() {
    if (this.socket) {
      try {
        if (this.connected && this.socket.readyState === 1) {
          this.socket.send(JSON.stringify({ skate: 'leave' }));
        }
        this.socket.close();
      } catch {}
      this.socket = null;
      this.connected = false;
    }
  }
}
