// focus-nav.js — keyboard + gamepad focus for the Mall and game switcher.
//
// Arrow keys (and a standard-mapping d-pad) move focus to the nearest control in
// that direction. The module is inert during a match: it only acts when an app
// screen or the game-switcher modal is actually visible.

/* global document, navigator, setInterval, clearInterval, getComputedStyle, setTimeout, MutationObserver */

import { loadSettings } from './settings.js';

const FOCUSABLE = 'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
const DIRS = {
  ArrowLeft: [-1, 0],
  ArrowRight: [1, 0],
  ArrowUp: [0, -1],
  ArrowDown: [0, 1],
};

function isVisible(el) {
  if (!el || el.closest('.hidden')) return false;
  if (getComputedStyle(el).visibility === 'hidden') return false;
  return !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length);
}

function activeContext() {
  const modal = document.getElementById('game-switcher-modal');
  if (modal && !modal.classList.contains('hidden')) return modal;
  return [...document.querySelectorAll('#app-shell .app-screen:not(.hidden)')].find(isVisible) || null;
}

function getFocusable(root) {
  if (!root) return [];
  return [...root.querySelectorAll(FOCUSABLE)].filter(isVisible);
}

function focusEl(el) {
  if (!el) return;
  el.focus({ preventScroll: true });
  el.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
}

function moveFocus(root, dirCode) {
  const list = getFocusable(root);
  if (!list.length) return false;
  const active = document.activeElement;
  if (!list.includes(active)) {
    focusEl(list[0]);
    return true;
  }

  const [dx, dy] = DIRS[dirCode];
  const from = active.getBoundingClientRect();
  const ax = from.left + from.width / 2;
  const ay = from.top + from.height / 2;
  let best = null;
  let bestScore = Infinity;

  for (const el of list) {
    if (el === active) continue;
    const r = el.getBoundingClientRect();
    const vx = r.left + r.width / 2 - ax;
    const vy = r.top + r.height / 2 - ay;
    const primary = vx * dx + vy * dy;
    if (primary <= 4) continue;
    const perp = Math.abs(vx * dy - vy * dx);
    const score = primary + perp * 2.2;
    if (score < bestScore) {
      bestScore = score;
      best = el;
    }
  }

  if (!best) {
    best = (dirCode === 'ArrowRight' || dirCode === 'ArrowDown') ? list[0] : list[list.length - 1];
  }
  focusEl(best);
  return true;
}

function onKeyDown(e) {
  if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
  const root = activeContext();
  if (!root) return;
  const tag = document.activeElement?.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  if (e.code === 'Tab' && root.id === 'game-switcher-modal') {
    const list = getFocusable(root);
    if (list.length) {
      const first = list[0];
      const last = list[list.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        focusEl(last);
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        focusEl(first);
      }
    }
    return;
  }
  if (!DIRS[e.code]) return;
  if (moveFocus(root, e.code)) {
    e.preventDefault();
    e.stopPropagation();
  }
}

function installModalFocus() {
  const modal = document.getElementById('game-switcher-modal');
  if (!modal) return;
  let open = !modal.classList.contains('hidden');
  let restore = null;

  new MutationObserver(() => {
    const now = !modal.classList.contains('hidden');
    if (now && !open) {
      restore = document.activeElement;
      setTimeout(() => focusEl(getFocusable(modal)[0]), 0);
    } else if (!now && open) {
      if (restore && typeof restore.focus === 'function' && document.contains(restore)) {
        restore.focus({ preventScroll: true });
      }
      restore = null;
    }
    open = now;
  }).observe(modal, { attributes: true, attributeFilter: ['class'] });
}

export function installFocusNav() {
  document.addEventListener('keydown', onKeyDown, true);
  installModalFocus();

  let last = new Set();
  const timer = setInterval(() => {
    const root = activeContext();
    if (!root || !loadSettings().gamepad) {
      last.clear();
      return;
    }
    const pad = [...(navigator.getGamepads?.() || [])].find(Boolean);
    if (!pad) {
      last.clear();
      return;
    }

    const pressed = new Set();
    const buttons = pad.buttons || [];
    for (let i = 0; i < buttons.length; i++) {
      const b = buttons[i];
      if (b && (b.pressed || b.value > 0.5)) pressed.add(i);
    }
    const edge = i => pressed.has(i) && !last.has(i);

    if (edge(12)) moveFocus(root, 'ArrowUp');
    if (edge(13)) moveFocus(root, 'ArrowDown');
    if (edge(14)) moveFocus(root, 'ArrowLeft');
    if (edge(15)) moveFocus(root, 'ArrowRight');
    if (edge(0)) {
      const active = document.activeElement;
      if (root.contains(active) && active !== document.body) active.click?.();
      else getFocusable(root)[0]?.click?.();
    }
    if (edge(1) && root.id === 'game-switcher-modal') {
      document.getElementById('btn-close-switcher')?.click();
    }
    last = pressed;
  }, 90);

  return () => {
    document.removeEventListener('keydown', onKeyDown, true);
    clearInterval(timer);
  };
}
