// DweebSkateFfa.js — Master controller for Skatepark Rumble: Roll & Shoot FFA.
//
// Integrates:
// - SkateArena (Birch launch ramp, 360 loop-de-loop, quarterpipes, foam block pit, warehouse rafters, stadium lights)
// - SkateController (Speed Roll Morph Ball <-> Spring-to-Shoot FPS)
// - BlasterHands (Animated first-person viewmodel & modular toy blaster)
// - SkateHud (1:1 replica of screenshot HUD: radar, timer 07:14, killfeed, avatar HP/shield, ammo 24/90, hitmarkers)
// - SkateBotManager (CUBE & VIRUS bots that roll, jump, transform and fight)
// - SkateNet (WebSocket online room synchronization)

import * as THREE from 'three';
import { SkateArena } from './SkateArena.js';
import { SkateAudio } from './SkateAudio.js';
import { SkateHud } from './SkateHud.js';
import { BlasterHands } from './BlasterHands.js';
import { SkateController } from './SkateController.js';
import { SkateBotManager } from './SkateBotAi.js';
import { SkateNet } from './SkateNet.js';

export class DweebSkateFfa {
  constructor({ scene, camera, canvas, physics, onExit, soundOn = true, serverUrl } = {}) {
    this.scene = scene;
    this.camera = camera;
    this.canvas = canvas;
    this.physics = physics;
    this.onExit = onExit;
    this.soundOn = soundOn;
    this.serverUrl = serverUrl;

    this.active = false;
    this.matchTime = 434; // 07:14
    this.bulletTracers = [];
    this.remotePlayers = new Map(); // slot -> remote representation

    // Subsystems
    this.audio = new SkateAudio({ soundOn });
    this.hud = new SkateHud();
    this.arena = new SkateArena({ scene: this.scene, physics: this.physics });
    this.hands = new BlasterHands({ camera: this.camera });

    this.controller = new SkateController({
      camera: this.camera,
      canvas: this.canvas,
      audio: this.audio,
      hud: this.hud,
      hands: this.hands,
      arena: this.arena,
      onShoot: (origin, dir) => this.spawnTracer(origin, dir),
      onTrick: (text, score) => this.net?.sendTrick(text, score),
    });

    this.botManager = new SkateBotManager({
      scene: this.scene,
      arena: this.arena,
      audio: this.audio,
      hud: this.hud,
      onBotKill: (killer, victim) => {
        this.hud.addKillfeed(killer, victim, '🔫');
        this.audio.playKill();
      },
    });

    this.net = new SkateNet({
      serverUrl: this.serverUrl,
      onJoined: (m) => {
        if (m.matchTime) this.matchTime = m.matchTime;
        this.hud.showTrickPopup('ONLINE ROOM', `ROOM: ${m.room}`);
      },
      onShot: (m) => {
        if (m.origin && m.dir) {
          const org = new THREE.Vector3(...m.origin);
          const d = new THREE.Vector3(...m.dir);
          this.spawnTracer(org, d, false);
        }
      },
      onKill: (m) => {
        this.hud.addKillfeed(m.killerName, m.victimName, '🔫');
        this.audio.playKill();
      },
      onTrick: (m) => {
        this.hud.showTrickPopup(m.text, m.playerName);
      },
      onSnapshot: (m) => {
        if (typeof m.matchTime === 'number') this.matchTime = m.matchTime;
        const localEntry = (m.players || []).find((p) => p.slot === this.net.slot);
        if (localEntry) this._reconcileLocalPlayer(localEntry);
        this._syncRemotePlayers(m.players || []);
      },
    });

    // Material for bullet laser tracers
    this.tracerMat = new THREE.MeshBasicMaterial({
      color: 0xffea00,
      transparent: true,
      opacity: 0.9,
    });
  }

  start({ roomCode = '', playerName = 'Dweeb' } = {}) {
    this.active = true;
    this.audio.init();
    this.audio.resume();

    // Position player at arena spawn
    const sp = this.arena.getRandomSpawn();
    this.controller.pos.copy(sp);
    this.controller.respawn();

    // Connect to WebSocket room
    this.net.connect({
      roomCode,
      playerName,
      dweebType: 'cube',
      color: '#ffea00',
    });

    // Initial killfeed mock lines matching screenshot
    setTimeout(() => this.hud.addKillfeed('SWAG_CUBE', 'SPIKEY_RED', '🔫'), 800);
    setTimeout(() => this.hud.addKillfeed('SWAG_CUBE', 'SPIKEY_RED', '🔫'), 2200);
  }

  spawnTracer(origin, dir, isLocalPlayer = true) {
    const geom = new THREE.CylinderGeometry(0.04, 0.04, 2.2, 6);
    geom.rotateX(Math.PI / 2);
    const mesh = new THREE.Mesh(geom, this.tracerMat);
    mesh.position.copy(origin).addScaledVector(dir, 1.2);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir);
    this.scene.add(mesh);

    const speed = 120.0;
    const tracer = {
      mesh,
      dir,
      speed,
      life: 0.6,
      origin: origin.clone(),
    };
    this.bulletTracers.push(tracer);

    if (isLocalPlayer) {
      // Broadcast over network
      this.net.sendShoot(origin, dir, Math.floor(Math.random() * 100000));

      // Raycast against bots and remote (networked) players, pick the nearest impact.
      const botHit = this.botManager.checkBulletHit(origin, dir, 80);
      const remoteHit = this.checkRemoteHit(origin, dir, 80);
      const botDist = botHit ? origin.distanceTo(botHit.hitPoint) : Infinity;
      const remoteDist = remoteHit ? remoteHit.distance : Infinity;
      if (botDist < remoteDist && botHit) {
        this.hud.showHitmarker();
        this.audio.playHit();
        botHit.bot.takeDamage(25, 'YOU');
      } else if (remoteHit && remoteDist <= 80) {
        this.hud.showHitmarker();
        this.audio.playHit();
        this.net.sendHit(remoteHit.slot, 25);
      }
    }
  }

  _buildRemoteMesh(player) {
    const group = new THREE.Group();
    const color = new THREE.Color(player.color || '#ffea00');
    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.7, 12, 12),
      new THREE.MeshStandardMaterial({ color, roughness: 0.5, metalness: 0.05 })
    );
    ball.castShadow = true;
    group.add(ball);
    // googly eyes
    const eyeGeo = new THREE.SphereGeometry(0.14, 6, 6);
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const pupGeo = new THREE.SphereGeometry(0.07, 6, 6);
    const pupMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
    for (const sx of [-0.22, 0.22]) {
      const eye = new THREE.Mesh(eyeGeo, eyeMat);
      eye.position.set(sx, 0.2, 0.6);
      const pup = new THREE.Mesh(pupGeo, pupMat);
      pup.position.set(0, 0, 0.08);
      eye.add(pup);
      ball.add(eye);
    }
    group.visible = true;
    return group;
  }

  checkRemoteHit(origin, dir, maxDist = 80) {
    const ray = new THREE.Ray(origin.clone(), dir.clone().normalize());
    let closestSlot = null;
    let closestDist = maxDist;
    let closestPoint = null;
    for (const rp of this.remotePlayers.values()) {
      if (rp.slot === this.net.slot) continue;
      const sphere = new THREE.Sphere(rp.mesh.position.clone().add(new THREE.Vector3(0, 0.8, 0)), 1.2);
      const hitPoint = new THREE.Vector3();
      if (ray.intersectSphere(sphere, hitPoint)) {
        const d = origin.distanceTo(hitPoint);
        if (d < closestDist) {
          closestDist = d;
          closestSlot = rp.slot;
          closestPoint = hitPoint;
        }
      }
    }
    return closestSlot ? { slot: closestSlot, hitPoint: closestPoint, distance: closestDist } : null;
  }

  _reconcileLocalPlayer(p) {
    if (typeof p.health !== 'number' || typeof p.shield !== 'number') return;
    const healthChanged = p.health !== this.controller.health;
    const shieldChanged = p.shield !== this.controller.shield;
    if (healthChanged || shieldChanged) {
      this.controller.health = p.health;
      this.controller.shield = p.shield;
      this.controller.hud.updateHealthAndShield(this.controller.health, this.controller.shield);
      if (p.health <= 0 && this.controller.health <= 0) {
        this.controller.respawn();
      }
    }
  }

  _syncRemotePlayers(players) {
    const seen = new Set();
    for (const p of players) {
      if (p.slot === this.net.slot) continue;
      if (!p.alive) {
        const rp = this.remotePlayers.get(p.slot);
        if (rp) {
          this.scene.remove(rp.mesh);
          this.remotePlayers.delete(p.slot);
        }
        continue;
      }
      seen.add(p.slot);
      let rp = this.remotePlayers.get(p.slot);
      if (!rp) {
        const mesh = this._buildRemoteMesh(p);
        this.scene.add(mesh);
        rp = {
          slot: p.slot,
          mesh,
          targetPos: new THREE.Vector3(p.x || 0, p.y || 0, p.z || 0),
          yaw: p.yaw || 0,
          pitch: p.pitch || 0,
          mode: p.mode || 'fps',
        };
        this.remotePlayers.set(p.slot, rp);
      }
      rp.targetPos.set(p.x || 0, p.y || 0, p.z || 0);
      rp.yaw = p.yaw || 0;
      rp.pitch = p.pitch || 0;
      rp.mode = p.mode || rp.mode;
    }
    for (const [slot, rp] of [...this.remotePlayers.entries()]) {
      if (!seen.has(slot)) {
        this.scene.remove(rp.mesh);
        this.remotePlayers.delete(slot);
      }
    }
  }

  update(dt) {
    if (!this.active) return;

    // Match Timer Countdown
    this.matchTime = Math.max(0, this.matchTime - dt);
    this.hud.updateTimer(this.matchTime);

    // Update Player Controller
    this.controller.update(dt);

    // Update Bots
    this.botManager.update(dt, this.controller.pos, (dmg, fromLeft) => {
      this.controller.takeDamage(dmg, fromLeft);
    });

    // Update Radar
    const entities = this.botManager.getEntities();
    this.hud.renderRadar(this.controller.pos, this.controller.yaw, entities);

    // Update bullet tracers
    for (let i = this.bulletTracers.length - 1; i >= 0; i--) {
      const t = this.bulletTracers[i];
      t.mesh.position.addScaledVector(t.dir, t.speed * dt);
      t.life -= dt;
      if (t.life <= 0) {
        this.scene.remove(t.mesh);
        this.bulletTracers.splice(i, 1);
      }
    }

    // Interpolate remote (networked) players
    for (const rp of this.remotePlayers.values()) {
      rp.mesh.position.lerp(rp.targetPos, Math.min(1, dt * 14));
      rp.mesh.rotation.y = rp.yaw;
      const isBall = (rp.mode === 'ball');
      const targetScale = isBall ? 1.0 : 0.85;
      rp.mesh.scale.lerp(new THREE.Vector3(targetScale, targetScale, targetScale), Math.min(1, dt * 8));
    }

    // Network position sync
    this.net.sendPos(
      this.controller.pos,
      this.controller.vel,
      this.controller.yaw,
      this.controller.pitch,
      this.controller.mode
    );
  }

  dispose() {
    this.active = false;
    for (const rp of this.remotePlayers.values()) this.scene.remove(rp.mesh);
    this.remotePlayers.clear();
    for (const t of this.bulletTracers) {
      this.scene.remove(t.mesh);
    }
    this.bulletTracers = [];

    this.controller?.dispose();
    this.hands?.dispose();
    this.hud?.dispose();
    this.audio?.dispose();
    this.botManager?.dispose();
    this.arena?.dispose();
    this.net?.dispose();
  }
}
