// SkateArena.js — 3D procedural construction of the Indoor Skatepark & Foam Pit Arena.
//
// Matches the reference image:
// - Birch plywood mega launch ramp with red edge piping
// - 360° wooden loop-de-loop ramp in the center
// - Left & right quarterpipes and vert ramps with metal coping
// - Yellow and red tubular steel grind rails
// - Sunken foam block pit with hundreds of colorful foam cubes
// - Industrial warehouse ceiling with dark steel trusses and roof skylights
// - Stadium floodlight banks mounted on high truss columns
// - Plywood walls and vibrant vertical banners

import * as THREE from 'three';

export class SkateArena {
  constructor({ scene, physics }) {
    this.scene = scene;
    this.physics = physics;
    this.group = new THREE.Group();
    this.group.name = 'SkateArena';
    this.colliders = [];
    this.foamCubes = [];
    this.spawnPoints = [
      new THREE.Vector3(0, 1.5, 30),
      new THREE.Vector3(-25, 2.0, 15),
      new THREE.Vector3(25, 2.0, 15),
      new THREE.Vector3(0, 8.5, -35),  // top of mega ramp
      new THREE.Vector3(-30, 7.5, -20), // left vert deck
      new THREE.Vector3(30, 7.5, -20),  // right vert deck
      new THREE.Vector3(-15, 1.5, -10),
      new THREE.Vector3(15, 1.5, -10),
    ];

    this._buildMaterials();
    this._buildWarehouseShell();
    this._buildMegaRamp();
    this._buildLoopDeLoop();
    this._buildQuarterPipes();
    this._buildGrindRails();
    this._buildFoamPit();
    this._buildLightingAndDetails();

    this.scene.add(this.group);
  }

  _buildMaterials() {
    // Birch plywood for ramps
    this.woodMat = new THREE.MeshStandardMaterial({
      color: 0xd8af79,
      roughness: 0.6,
      metalness: 0.05,
    });

    this.woodDarkMat = new THREE.MeshStandardMaterial({
      color: 0x9c6f47,
      roughness: 0.7,
      metalness: 0.05,
    });

    this.wallPlywoodMat = new THREE.MeshStandardMaterial({
      color: 0xc89e68,
      roughness: 0.8,
      metalness: 0.0,
    });

    this.concreteFloorMat = new THREE.MeshStandardMaterial({
      color: 0x6e7682,
      roughness: 0.75,
      metalness: 0.1,
    });

    this.steelTrussMat = new THREE.MeshStandardMaterial({
      color: 0x333b47,
      roughness: 0.4,
      metalness: 0.7,
    });

    this.redPipeMat = new THREE.MeshStandardMaterial({
      color: 0xdd2c1f,
      roughness: 0.3,
      metalness: 0.2,
    });

    this.yellowPipeMat = new THREE.MeshStandardMaterial({
      color: 0xffca28,
      roughness: 0.3,
      metalness: 0.2,
    });

    this.floodlightEmissiveMat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
    });
  }

  _buildWarehouseShell() {
    const W = 90;
    const L = 120;
    const H = 28;

    // Floor
    const floorGeo = new THREE.PlaneGeometry(W, L);
    const floorMesh = new THREE.Mesh(floorGeo, this.concreteFloorMat);
    floorMesh.rotation.x = -Math.PI / 2;
    floorMesh.receiveShadow = true;
    this.group.add(floorMesh);

    // Floor Rapier physics body
    if (this.physics?.world) {
      const RAPIER = this.physics.RAPIER || window.RAPIER;
      if (RAPIER) {
        const floorBody = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
        const floorCol = RAPIER.ColliderDesc.cuboid(W / 2, 0.5, L / 2)
          .setTranslation(0, -0.5, 0)
          .setFriction(0.4)
          .setRestitution(0.2);
        this.physics.world.createCollider(floorCol, floorBody);
      }
    }

    // Warehouse Walls (Plywood finish)
    const wallGeoZ = new THREE.BoxGeometry(W, H, 1);
    const wallGeoX = new THREE.BoxGeometry(1, H, L);

    // Back wall
    const backWall = new THREE.Mesh(wallGeoZ, this.wallPlywoodMat);
    backWall.position.set(0, H / 2, -L / 2);
    backWall.receiveShadow = true;
    this.group.add(backWall);

    // Front wall
    const frontWall = new THREE.Mesh(wallGeoZ, this.wallPlywoodMat);
    frontWall.position.set(0, H / 2, L / 2);
    frontWall.receiveShadow = true;
    this.group.add(frontWall);

    // Left wall
    const leftWall = new THREE.Mesh(wallGeoX, this.wallPlywoodMat);
    leftWall.position.set(-W / 2, H / 2, 0);
    leftWall.receiveShadow = true;
    this.group.add(leftWall);

    // Right wall
    const rightWall = new THREE.Mesh(wallGeoX, this.wallPlywoodMat);
    rightWall.position.set(W / 2, H / 2, 0);
    rightWall.receiveShadow = true;
    this.group.add(rightWall);

    // Wall physics
    if (this.physics?.world) {
      const RAPIER = this.physics.RAPIER || window.RAPIER;
      if (RAPIER) {
        const wallBody = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
        this.physics.world.createCollider(RAPIER.ColliderDesc.cuboid(W / 2, H / 2, 0.5).setTranslation(0, H / 2, -L / 2), wallBody);
        this.physics.world.createCollider(RAPIER.ColliderDesc.cuboid(W / 2, H / 2, 0.5).setTranslation(0, H / 2, L / 2), wallBody);
        this.physics.world.createCollider(RAPIER.ColliderDesc.cuboid(0.5, H / 2, L / 2).setTranslation(-W / 2, H / 2, 0), wallBody);
        this.physics.world.createCollider(RAPIER.ColliderDesc.cuboid(0.5, H / 2, L / 2).setTranslation(W / 2, H / 2, 0), wallBody);
      }
    }

    // Steel Roof Rafters & Skylights
    const trussGroup = new THREE.Group();
    for (let z = -L / 2 + 10; z < L / 2; z += 15) {
      // Main beam
      const beamGeo = new THREE.BoxGeometry(W, 1.2, 0.8);
      const beamMesh = new THREE.Mesh(beamGeo, this.steelTrussMat);
      beamMesh.position.set(0, H - 2, z);
      trussGroup.add(beamMesh);

      // Angled rafters
      const rafterLeftGeo = new THREE.BoxGeometry(W / 2 + 2, 0.6, 0.6);
      const rafterLeft = new THREE.Mesh(rafterLeftGeo, this.steelTrussMat);
      rafterLeft.position.set(-W / 4, H - 0.5, z);
      rafterLeft.rotation.z = 0.12;
      trussGroup.add(rafterLeft);

      const rafterRight = new THREE.Mesh(rafterLeftGeo, this.steelTrussMat);
      rafterRight.position.set(W / 4, H - 0.5, z);
      rafterRight.rotation.z = -0.12;
      trussGroup.add(rafterRight);
    }
    this.group.add(trussGroup);

    // Decorative wall banners on right side (blue, yellow, red)
    const bannerColors = [0x2196f3, 0xffeb3b, 0xf44336];
    bannerColors.forEach((col, idx) => {
      const bannerGeo = new THREE.PlaneGeometry(3.5, 12);
      const bannerMat = new THREE.MeshStandardMaterial({ color: col, roughness: 0.5 });
      const bannerMesh = new THREE.Mesh(bannerGeo, bannerMat);
      bannerMesh.position.set(W / 2 - 0.2, 14, -20 + idx * 5);
      bannerMesh.rotation.y = -Math.PI / 2;
      this.group.add(bannerMesh);
    });
  }

  _buildMegaRamp() {
    // Central Launch Ramp matching the image
    const rampGroup = new THREE.Group();
    const rampWidth = 14;
    const rampLength = 32;
    const rampHeight = 8;
    const rampZ = -22;

    // Curved wood surface via segments
    const segments = 16;
    const curvePoints = [];
    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      const z = (1 - t) * (rampLength / 2) - (rampLength / 2); // from 0 down to -rampLength
      // Smooth parabolic slope
      const y = Math.pow(t, 1.8) * rampHeight;
      curvePoints.push(new THREE.Vector2(z, y));
    }

    // Extrude ramp shape
    const shape = new THREE.Shape();
    shape.moveTo(curvePoints[0].x, curvePoints[0].y);
    for (let i = 1; i < curvePoints.length; i++) {
      shape.lineTo(curvePoints[i].x, curvePoints[i].y);
    }
    shape.lineTo(curvePoints[curvePoints.length - 1].x, 0);
    shape.lineTo(curvePoints[0].x, 0);
    shape.closePath();

    const extrudeSettings = {
      steps: 1,
      depth: rampWidth,
      bevelEnabled: false,
    };

    const rampGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
    rampGeo.center();
    const rampMesh = new THREE.Mesh(rampGeo, this.woodMat);
    rampMesh.position.set(0, rampHeight / 2, rampZ);
    rampMesh.rotation.y = Math.PI / 2;
    rampMesh.castShadow = true;
    rampMesh.receiveShadow = true;
    rampGroup.add(rampMesh);

    // Red tubular safety edge pipes along both sides
    const pipeGeo = new THREE.CylinderGeometry(0.18, 0.18, rampLength, 12);
    const leftPipe = new THREE.Mesh(pipeGeo, this.redPipeMat);
    leftPipe.rotation.x = 0.25;
    leftPipe.position.set(-rampWidth / 2 - 0.1, rampHeight / 2 + 0.3, rampZ);
    rampGroup.add(leftPipe);

    const rightPipe = new THREE.Mesh(pipeGeo, this.redPipeMat);
    rightPipe.rotation.x = 0.25;
    rightPipe.position.set(rampWidth / 2 + 0.1, rampHeight / 2 + 0.3, rampZ);
    rampGroup.add(rightPipe);

    // Top observation / drop platform
    const platformGeo = new THREE.BoxGeometry(rampWidth + 4, 0.8, 8);
    const platformMesh = new THREE.Mesh(platformGeo, this.woodDarkMat);
    platformMesh.position.set(0, rampHeight - 0.4, rampZ - rampLength / 2 - 4);
    rampGroup.add(platformMesh);

    // Platform support steel pillars
    const pillarGeo = new THREE.BoxGeometry(0.8, rampHeight, 0.8);
    [-rampWidth / 2, rampWidth / 2].forEach(px => {
      [-2, -6].forEach(pz => {
        const pillar = new THREE.Mesh(pillarGeo, this.steelTrussMat);
        pillar.position.set(px, rampHeight / 2, rampZ - rampLength / 2 + pz);
        rampGroup.add(pillar);
      });
    });

    this.group.add(rampGroup);

    // Physics colliders for ramp (inclined planes)
    if (this.physics?.world) {
      const RAPIER = this.physics.RAPIER || window.RAPIER;
      if (RAPIER) {
        const rampBody = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
        // Approximate slope with inclined box
        const slopeCol = RAPIER.ColliderDesc.cuboid(rampWidth / 2, 0.5, rampLength / 2)
          .setTranslation(0, rampHeight / 2, rampZ)
          .setRotation(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), -0.24))
          .setFriction(0.15) // Smooth rolling
          .setRestitution(0.3);
        this.physics.world.createCollider(slopeCol, rampBody);

        // Platform collider
        const platCol = RAPIER.ColliderDesc.cuboid((rampWidth + 4) / 2, 0.4, 4)
          .setTranslation(0, rampHeight - 0.4, rampZ - rampLength / 2 - 4)
          .setFriction(0.3);
        this.physics.world.createCollider(platCol, rampBody);
      }
    }
  }

  _buildLoopDeLoop() {
    // 360° Wooden Loop-de-Loop in the center-back of the skatepark
    const loopGroup = new THREE.Group();
    const R = 7.5; // Radius
    const trackWidth = 5.0;
    const loopZ = -15;
    const loopX = -20;

    // Create 360 loop track geometry
    const segments = 36;
    for (let i = 0; i < segments; i++) {
      const theta1 = (i / segments) * Math.PI * 2;
      const theta2 = ((i + 1) / segments) * Math.PI * 2;
      const midTheta = (theta1 + theta2) / 2;

      // Track segment
      const segLen = (Math.PI * 2 * R) / segments;
      const segGeo = new THREE.BoxGeometry(trackWidth, 0.4, segLen + 0.1);
      const segMesh = new THREE.Mesh(segGeo, this.woodMat);

      const y = R + 0.2 - R * Math.cos(midTheta);
      const z = loopZ + R * Math.sin(midTheta) + (i / segments) * 2.5; // slight spiral offset for clean entry/exit

      segMesh.position.set(loopX, y, z);
      segMesh.rotation.x = midTheta;
      loopGroup.add(segMesh);

      // Support trusses around the exterior
      if (i % 4 === 0) {
        const postH = y;
        if (postH > 1) {
          const postGeo = new THREE.CylinderGeometry(0.2, 0.2, postH, 8);
          const postMesh = new THREE.Mesh(postGeo, this.steelTrussMat);
          postMesh.position.set(loopX - trackWidth / 2 - 0.3, postH / 2, z);
          loopGroup.add(postMesh);

          const postMeshR = postMesh.clone();
          postMeshR.position.x = loopX + trackWidth / 2 + 0.3;
          loopGroup.add(postMeshR);
        }
      }

      // Rapier collider for loop segments
      if (this.physics?.world) {
        const RAPIER = this.physics.RAPIER || window.RAPIER;
        if (RAPIER) {
          const body = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
          const col = RAPIER.ColliderDesc.cuboid(trackWidth / 2, 0.2, (segLen + 0.1) / 2)
            .setTranslation(loopX, y, z)
            .setRotation(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), midTheta))
            .setFriction(0.08) // Super slick for high-speed rolling loops!
            .setRestitution(0.2);
          this.physics.world.createCollider(col, body);
        }
      }
    }

    this.group.add(loopGroup);
  }

  _buildQuarterPipes() {
    // Left & Right Quarterpipes / Halfpipe Vert Ramps
    const qpGroup = new THREE.Group();
    const width = 60;
    const height = 7;
    const depth = 12;

    [-38, 38].forEach(posX => {
      const qpGeo = new THREE.BoxGeometry(depth, 0.5, width);
      const qpMesh = new THREE.Mesh(qpGeo, this.woodMat);
      qpMesh.position.set(posX, height / 2, 0);
      qpMesh.rotation.z = posX > 0 ? 0.35 : -0.35;
      qpMesh.receiveShadow = true;
      qpGroup.add(qpMesh);

      // Metal Coping bar on lip
      const copingGeo = new THREE.CylinderGeometry(0.2, 0.2, width, 12);
      const copingMesh = new THREE.Mesh(copingGeo, this.steelTrussMat);
      copingMesh.rotation.x = Math.PI / 2;
      copingMesh.position.set(posX > 0 ? posX + 4 : posX - 4, height, 0);
      qpGroup.add(copingMesh);

      // Physics
      if (this.physics?.world) {
        const RAPIER = this.physics.RAPIER || window.RAPIER;
        if (RAPIER) {
          const body = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
          const col = RAPIER.ColliderDesc.cuboid(depth / 2, 0.25, width / 2)
            .setTranslation(posX, height / 2, 0)
            .setRotation(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), posX > 0 ? 0.35 : -0.35))
            .setFriction(0.12)
            .setRestitution(0.4);
          this.physics.world.createCollider(col, body);
        }
      }
    });

    this.group.add(qpGroup);
  }

  _buildGrindRails() {
    // Red and Yellow tubular steel grind rails
    const railGroup = new THREE.Group();

    // Long yellow grind rail on the right
    const railLen = 28;
    const railGeo = new THREE.CylinderGeometry(0.15, 0.15, railLen, 12);
    const yellowRail = new THREE.Mesh(railGeo, this.yellowPipeMat);
    yellowRail.rotation.x = Math.PI / 2;
    yellowRail.position.set(16, 1.2, 8);
    railGroup.add(yellowRail);

    // Support legs
    for (let z = -railLen / 2 + 2; z <= railLen / 2; z += 6) {
      const legGeo = new THREE.CylinderGeometry(0.1, 0.1, 1.2, 8);
      const legMesh = new THREE.Mesh(legGeo, this.yellowPipeMat);
      legMesh.position.set(16, 0.6, 8 + z);
      railGroup.add(legMesh);
    }

    // Red rail across center ramp kicker
    const redRail = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 18, 12), this.redPipeMat);
    redRail.rotation.x = 0.25;
    redRail.position.set(-10, 2.5, 0);
    railGroup.add(redRail);

    this.group.add(railGroup);

    // Physics colliders for grinding
    if (this.physics?.world) {
      const RAPIER = this.physics.RAPIER || window.RAPIER;
      if (RAPIER) {
        const body = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
        const railCol1 = RAPIER.ColliderDesc.cuboid(0.2, 0.2, railLen / 2)
          .setTranslation(16, 1.2, 8)
          .setFriction(0.05); // Super slick grind!
        this.physics.world.createCollider(railCol1, body);
      }
    }
  }

  _buildFoamPit() {
    // Sunken Foam Cube Ball Pit directly in front of the central ramp!
    const pitGroup = new THREE.Group();
    const pitW = 16;
    const pitL = 14;
    const pitDepth = 2.0;
    const pitX = 0;
    const pitZ = 12;

    // Pit rim border
    const rimMat = new THREE.MeshStandardMaterial({ color: 0x22262c, roughness: 0.5 });
    const rimGeoH = new THREE.BoxGeometry(pitW + 0.8, 0.4, 0.6);
    const rimGeoV = new THREE.BoxGeometry(0.6, 0.4, pitL + 0.8);

    const rimTop = new THREE.Mesh(rimGeoH, rimMat);
    rimTop.position.set(pitX, 0.2, pitZ - pitL / 2);
    pitGroup.add(rimTop);

    const rimBottom = new THREE.Mesh(rimGeoH, rimMat);
    rimBottom.position.set(pitX, 0.2, pitZ + pitL / 2);
    pitGroup.add(rimBottom);

    const rimLeft = new THREE.Mesh(rimGeoV, rimMat);
    rimLeft.position.set(pitX - pitW / 2, 0.2, pitZ);
    pitGroup.add(rimLeft);

    const rimRight = new THREE.Mesh(rimGeoV, rimMat);
    rimRight.position.set(pitX + pitW / 2, 0.2, pitZ);
    pitGroup.add(rimRight);

    // Colorful Foam Blocks inside pit (cyan, red, yellow, lime green, blue, orange)
    const cubeColors = [
      0x00d2ff, // cyan
      0xff2b4b, // red
      0xffea00, // yellow
      0x00e676, // lime
      0x2979ff, // blue
      0xff9100, // orange
    ];

    const cubeGeo = new THREE.BoxGeometry(0.9, 0.9, 0.9);
    const materials = cubeColors.map(c => new THREE.MeshStandardMaterial({
      color: c,
      roughness: 0.85,
      metalness: 0.0,
    }));

    // Dense grid of foam cubes
    const countX = 9;
    const countZ = 8;
    const layers = 2;

    for (let layer = 0; layer < layers; layer++) {
      for (let ix = 0; ix < countX; ix++) {
        for (let iz = 0; iz < countZ; iz++) {
          const mat = materials[(ix + iz * 2 + layer * 3) % materials.length];
          const mesh = new THREE.Mesh(cubeGeo, mat);
          const jx = (Math.random() - 0.5) * 0.4;
          const jz = (Math.random() - 0.5) * 0.4;
          const jy = (Math.random() - 0.5) * 0.2;

          const cx = pitX - (pitW / 2) + 1.2 + (ix / (countX - 1)) * (pitW - 2.4) + jx;
          const cy = 0.45 + layer * 0.8 + jy;
          const cz = pitZ - (pitL / 2) + 1.2 + (iz / (countZ - 1)) * (pitL - 2.4) + jz;

          mesh.position.set(cx, cy, cz);
          mesh.rotation.set(
            (Math.random() - 0.5) * 0.3,
            (Math.random() - 0.5) * 0.6,
            (Math.random() - 0.5) * 0.3
          );
          mesh.castShadow = true;
          mesh.receiveShadow = true;
          pitGroup.add(mesh);

          this.foamCubes.push({
            mesh,
            basePos: new THREE.Vector3(cx, cy, cz),
            velocity: new THREE.Vector3(),
          });
        }
      }
    }

    this.group.add(pitGroup);

    // Soft bouncy Rapier collider for the foam pit
    if (this.physics?.world) {
      const RAPIER = this.physics.RAPIER || window.RAPIER;
      if (RAPIER) {
        const pitBody = this.physics.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
        const pitCol = RAPIER.ColliderDesc.cuboid(pitW / 2, 0.8, pitL / 2)
          .setTranslation(pitX, 0.4, pitZ)
          .setFriction(0.6)
          .setRestitution(0.65); // Bouncy foam feel!
        this.physics.world.createCollider(pitCol, pitBody);
      }
    }
  }

  _buildLightingAndDetails() {
    // Stadium Floodlight rigs mounted high on industrial trusses
    const lightBanks = [
      new THREE.Vector3(-32, 22, -30),
      new THREE.Vector3(32, 22, -30),
      new THREE.Vector3(-32, 22, 25),
      new THREE.Vector3(32, 22, 25),
    ];

    lightBanks.forEach(pos => {
      // Light housing
      const housingGeo = new THREE.BoxGeometry(6, 3.5, 1.5);
      const housingMesh = new THREE.Mesh(housingGeo, this.steelTrussMat);
      housingMesh.position.copy(pos);
      housingMesh.lookAt(0, 4, 0);
      this.group.add(housingMesh);

      // Glowing LED face
      const faceGeo = new THREE.PlaneGeometry(5.4, 3.0);
      const faceMesh = new THREE.Mesh(faceGeo, this.floodlightEmissiveMat);
      faceMesh.position.set(0, 0, 0.8);
      housingMesh.add(faceMesh);

      // SpotLight
      const spot = new THREE.SpotLight(0xfff7e6, 3.5, 90, Math.PI / 4, 0.4, 1.2);
      spot.position.copy(pos);
      spot.target.position.set(pos.x * 0.3, 0, pos.z * 0.3);
      this.group.add(spot);
      this.group.add(spot.target);
    });

    // Ambient light fill
    const hemi = new THREE.HemisphereLight(0xe8f0ff, 0x54483b, 1.2);
    this.group.add(hemi);
  }

  getRandomSpawn() {
    const idx = Math.floor(Math.random() * this.spawnPoints.length);
    const sp = this.spawnPoints[idx].clone();
    sp.x += (Math.random() - 0.5) * 3;
    sp.z += (Math.random() - 0.5) * 3;
    return sp;
  }

  updateFoam(playerPos, playerSpeed) {
    // Interactive ripple/scatter when player or ball rolls into foam pit
    for (let i = 0; i < this.foamCubes.length; i++) {
      const fc = this.foamCubes[i];
      const dist = fc.mesh.position.distanceTo(playerPos);
      if (dist < 2.5 && playerSpeed > 2.0) {
        const force = (2.5 - dist) * 0.08;
        const pushDir = fc.mesh.position.clone().sub(playerPos).normalize();
        fc.velocity.x += pushDir.x * force;
        fc.velocity.y += Math.abs(pushDir.y) * force * 1.5 + 0.04;
        fc.velocity.z += pushDir.z * force;
      }

      // Spring back to base position
      fc.velocity.y -= 0.015; // gravity
      fc.mesh.position.add(fc.velocity);
      fc.velocity.multiplyScalar(0.88); // drag

      const returnDir = fc.basePos.clone().sub(fc.mesh.position);
      fc.mesh.position.addScaledVector(returnDir, 0.08);
      if (fc.mesh.position.y < fc.basePos.y) fc.mesh.position.y = fc.basePos.y;
    }
  }

  dispose() {
    this.scene.remove(this.group);
  }
}
