// ── Cosmetics ──────────────────────────────────────────────────────
// slot: where it renders. `build` keys map to mesh builders registered
// in src/world/Cosmetics.js (hats) or the FX/trail systems.

export const COSMETICS = [
  { id: 'laurel-wreath', name: 'Golden Laurel Wreath', slot: 'hat',   icon: '👑', desc: 'For the Untouchable',        from: 'untouchable' },
  { id: 'neon-aura',     name: 'Neon Particle Aura',   slot: 'aura',  icon: '✨', desc: 'For the Colosseum Victor',   from: 'colosseum-victor' },
  { id: 'holo-cape',     name: 'Holographic Cape',     slot: 'cape',  icon: '🦸', desc: 'For the Wave 20 Conqueror',  from: 'wave-20' },
  { id: 'rainbow-trail', name: 'Rainbow Trails',       slot: 'trail', icon: '🌈', desc: 'For the Genetic Freak',      from: 'genetic-freak' },
];

const STAMP_BY_ID = new Map(STAMPS.map(s => [s.id, s]));
const COSMETIC_BY_ID = new Map(COSMETICS.map(c => [c.id, c]));

// ── Checksum (FNV-1a, 32-bit) ──────────────────────────────────────

export function checksumOf(obj) {
  const str = JSON.stringify(obj);
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

// ── Storage ────────────────────────────────────────────────────────

function safeStorage() {
  try {
    if (typeof localStorage !== 'undefined') return localStorage;
  } catch { /* private mode / node */ }
  return null;
}

function freshState() {
  return { v: SCHEMA_VERSION, stamps: {}, equipped: {}, stats: {} };
}

function migrate(data) {
  // v1 → v2: v1 had no equipped map and no checksum; keep stamps.
  if (!data || typeof data !== 'object') return freshState();
  const out = freshState();
  if (data.stamps && typeof data.stamps === 'object') {
    for (const [k, ts] of Object.entries(data.stamps)) {
      if (STAMP_BY_ID.has(k)) out.stamps[k] = Number(ts) || Date.now();
    }
  }
  if (data.equipped && typeof data.equipped === 'object') {
    for (const [slot, id] of Object.entries(data.equipped)) {
      const c = COSMETIC_BY_ID.get(id);
      if (c && c.slot === slot) out.equipped[slot] = id;
    }
  }
  if (data.stats && typeof data.stats === 'object') {
    for (const [k, n] of Object.entries(data.stats)) {
      if (typeof n === 'number' && Number.isFinite(n)) out.stats[k] = n;
    }
  }
  return out;
}

function load() {
  const s = safeStorage();
  if (!s) return freshState();
  try {
    const raw = s.getItem(STORE_KEY);
    if (!raw) return freshState();
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object') return freshState();
    // Verify checksum when present (v2). v1 data migrates.
    if (data.v === SCHEMA_VERSION && typeof data.checksum === 'string') {
      const { checksum, ...payload } = data;
      if (checksumOf(payload) !== checksum) return freshState(); // corrupt → reset
      return migrate(data);
    }
    return migrate(data);
  } catch {
    return freshState();
  }
}

function save(state) {
  const s = safeStorage();
  if (!s) return;
  try {
    const payload = { v: state.v, stamps: state.stamps, equipped: state.equipped, stats: state.stats };
    s.setItem(STORE_KEY, JSON.stringify({ ...payload, checksum: checksumOf(payload) }));
  } catch { /* storage full / blocked */ }
}

let state = load();
const listeners = new Set();

function notify(evt) {
  for (const cb of listeners) {
    try { cb(evt); } catch { /* listener bugs never break unlocks */ }
  }
}

// ── Public API ─────────────────────────────────────────────────────

export function reload() { state = load(); }

export function reset() {
  state = freshState();
  save(state);
}

export function onPassportEvent(cb) {
  listeners.add(cb);
  return () => listeners.delete(cb);
}

export function isStamped(id) { return !!state.stamps[id]; }

export function stampCount() { return Object.keys(state.stamps).length; }

export function totalStamps() { return STAMPS.length; }

export function stampsForPage(page) { return STAMPS.filter(s => s.page === page); }

export function statValue(key) { return state.stats[key] || 0; }

export function cosmeticById(id) { return COSMETIC_BY_ID.get(id) || null; }

export function ownedCosmetics() {
  return COSMETICS.filter(c => isStamped(c.from));
}

export function equipped(slot) { return state.equipped[slot] || null; }

/**
 * Unlock a stamp by id. Returns the stamp def on a fresh unlock, null otherwise.
 * Auto-awards the linked cosmetic and notifies listeners.
 */
export function unlock(id) {
  const def = STAMP_BY_ID.get(id);
  if (!def || state.stamps[id]) return null;
  state.stamps[id] = Date.now();
  save(state);
  const evt = { type: 'stamp', stamp: def };
  if (def.reward) {
    const c = COSMETIC_BY_ID.get(def.reward);
    if (c) {
      state.equipped[c.slot] = c.id; // auto-equip new rewards
      save(state);
      evt.cosmetic = c;
    }
  }
  notify(evt);
  return def;
}

/**
 * Add n to a stat counter; unlocks any threshold stamps it trips.
 * Returns the list of newly unlocked stamps.
 */
export function recordStat(key, n = 1) {
  state.stats[key] = (state.stats[key] || 0) + n;
  const fresh = [];
  for (const s of STAMPS) {
    if (s.stat === key && !state.stamps[s.id] && state.stats[key] >= s.at) {
      const def = unlock(s.id);
      if (def) fresh.push(def);
    }
  }
  save(state);
  return fresh;
}

// Event → stat/event mappings so game code calls record() with a semantic
// event name and the passport figures out the rest.
const EVENT_MAP = {
  'ko':               { stat: 'ko' },
  'ringout':          { stat: 'ringout' },
  'balloon-recovery': { stamp: 'balloon-float' },
  'flawless-win':     { stamp: 'untouchable' },
  'harvest':          { stamp: 'first-harvest' },
  'night':            { stat: 'night' },
  'all-structures':   { stamp: 'village-architect' },
  'feast':            { stamp: 'feast-master' },
  'units-led':        { stat: 'units-led' },
  'catapult-hit':     { stamp: 'catapult-trickshot' },
  'phalanx-deflect':  { stat: 'phalanx-deflect' },
  'wave':             { stat: 'wave' },
  'dna-morph':        { stamp: 'mad-scientist' },
  'colosseum-win':    { stamp: 'colosseum-victor' },
  'max-genetics':     { stamp: 'genetic-freak' },
};

/**
 * Record a semantic game event. `data.n` scales stat events.
 * Returns newly unlocked stamps.
 */
export function record(event, data = {}) {
  const m = EVENT_MAP[event];
  if (!m) return [];
  if (m.stat) return recordStat(m.stat, data.n ?? 1);
  if (m.stamp) {
    const def = unlock(m.stamp);
    return def ? [def] : [];
  }
  return [];
}

/** Equip an owned cosmetic. Returns true on success. */
export function equipCosmetic(id) {
  const c = COSMETIC_BY_ID.get(id);
  if (!c || !isStamped(c.from)) return false;
  state.equipped[c.slot] = id;
  save(state);
  notify({ type: 'equip', cosmetic: c });
  return true;
}

/** Unequip a slot. */
export function unequipSlot(slot) {
  if (!state.equipped[slot]) return false;
  delete state.equipped[slot];
  save(state);
  notify({ type: 'unequip', slot });
  return true;
}

/** Snapshot for the UI (plain data, no live refs). */
export function snapshot() {
  return {
    stamps: { ...state.stamps },
    equipped: { ...state.equipped },
    stats: { ...state.stats },
    count: stampCount(),
    total: totalStamps(),
  };
}
