// src/sim/warfareGrid.js — deterministic uniform spatial grid for the 200-unit battle.
//
// The old collision pass compared every unit with every other unit (O(n²)). At 100v100 that is
// ~20k pair checks per tick, 600k per second. This grid buckets units by cell so each unit only
// tests its own cell and the eight neighbours. Cell order and unit order are fixed, so peers still
// produce bit-identical battles.

import { stats } from './warfareUnits.js';

export const GRID_CELL = 6;

const key = (cx, cz) => (cx + 512) * 1024 + (cz + 512);

export class SpatialGrid {
  constructor(cell = GRID_CELL) {
    this.cell = cell;
    this.cells = new Map();
  }

  clear() {
    this.cells.clear();
  }

  /** Bucket every live, non-carried unit. Insertion order follows the units array. */
  build(units) {
    this.clear();
    const c = this.cell;
    for (let i = 0; i < units.length; i++) {
      const u = units[i];
      if (!u.alive || u.carriedBy) continue;
      const k = key(Math.floor(u.x / c), Math.floor(u.z / c));
      let bucket = this.cells.get(k);
      if (!bucket) { bucket = []; this.cells.set(k, bucket); }
      bucket.push(u);
    }
    return this;
  }

  /** Units whose centre lies within `r` of (x,z). Deterministic cell/insertion order. */
  query(x, z, r, out = []) {
    const c = this.cell;
    const r2 = r * r;
    const cx = Math.floor(x / c), cz = Math.floor(z / c);
    const span = Math.max(1, Math.ceil(r / c));
    for (let dz = -span; dz <= span; dz++) {
      for (let dx = -span; dx <= span; dx++) {
        const bucket = this.cells.get(key(cx + dx, cz + dz));
        if (!bucket) continue;
        for (const u of bucket) {
          const ddx = u.x - x, ddz = u.z - z;
          if (ddx * ddx + ddz * ddz <= r2) out.push(u);
        }
      }
    }
    return out;
  }
}

export function buildGrid(units, cell = GRID_CELL) {
  return new SpatialGrid(cell).build(units);
}

/**
 * Grid-accelerated pairwise separation. Heavier units shove lighter ones.
 * Only pairs (i, j) with j > i are resolved, so the result is order-stable.
 */
export function separateUnits(units, grid) {
  const c = grid.cell;
  const cells = grid.cells;
  for (let i = 0; i < units.length; i++) {
    const a = units[i];
    if (!a.alive || a.carriedBy) continue;
    const cx = Math.floor(a.x / c), cz = Math.floor(a.z / c);
    for (let dz = -1; dz <= 1; dz++) {
      for (let dx = -1; dx <= 1; dx++) {
        const bucket = cells.get(key(cx + dx, cz + dz));
        if (!bucket) continue;
        for (const b of bucket) {
          if (b === a || b.id <= a.id) continue;
          if (!b.alive || b.carriedBy) continue;
          const ddx = b.x - a.x, ddz = b.z - a.z;
          const min = a.radius + b.radius;
          const d2 = ddx * ddx + ddz * ddz;
          if (d2 >= min * min) continue;
          const d = Math.sqrt(d2) || 0.001;
          const over = min - d;
          const ma = a.mass || stats(a.type).mass, mb = b.mass || stats(b.type).mass;
          const wa = mb / (ma + mb), wb = ma / (ma + mb);
          const nx = d2 > 0 ? ddx / d : 1, nz = d2 > 0 ? ddz / d : 0;
          a.x -= nx * over * wa; a.z -= nz * over * wa;
          b.x += nx * over * wb; b.z += nz * over * wb;
        }
      }
    }
  }
}
