// BlasterHands.js — First-person animated hands and modular toy blaster.
//
// Matches the reference image:
// - Yellow arms / sleeves with low-poly hands in black fingerless combat gloves
// - Chunky toy blaster: cyan body, orange power cells, purple top sight rail, lime grip, orange hexagonal muzzle
// - Snappy procedural animations: recoil kickback, muzzle flash, walk bobbing, slide tilting
// - Smooth hide / tuck animation when switching to Morph Ball mode

import * as THREE from 'three';

export class BlasterHands {
  constructor({ camera }) {
    this.camera = camera;
    this.group = new THREE.Group();
    this.group.name = 'BlasterHands';

    this.recoil = 0;
    this.recoilVel = 0;
    this.bobTime = 0;
    this.tuckProgress = 0; // 0 = fully raised, 1 = tucked away for ball mode
    this.isTucked = false;

    this._buildMaterials();
    this._buildBlasterModel();
    this._buildHandsAndArms();
    this._buildMuzzleFlash();

    // Default rest position in camera space
    this.basePos = new THREE.Vector3(0.28, -0.32, -0.58);
    this.group.position.copy(this.basePos);
    this.camera.add(this.group);
  }

  _buildMaterials() {
    this.cyanMat = new THREE.MeshStandardMaterial({
      color: 0x00bcd4,
      roughness: 0.3,
      metalness: 0.1,
    });

    this.orangeMat = new THREE.MeshStandardMaterial({
      color: 0xff6d00,
      roughness: 0.35,
      metalness: 0.1,
    });

    this.purpleRailMat = new THREE.MeshStandardMaterial({
      color: 0x6200ea,
      roughness: 0.4,
      metalness: 0.2,
    });

    this.limeGripMat = new THREE.MeshStandardMaterial({
      color: 0x76ff03,
      roughness: 0.5,
      metalness: 0.0,
    });

    this.neonScreenMat = new THREE.MeshBasicMaterial({
      color: 0x18ffff,
    });

    this.darkGrayMat = new THREE.MeshStandardMaterial({
      color: 0x263238,
      roughness: 0.6,
      metalness: 0.3,
    });

    this.yellowArmMat = new THREE.MeshStandardMaterial({
      color: 0xffd600,
      roughness: 0.5,
      metalness: 0.0,
    });

    this.gloveMat = new THREE.MeshStandardMaterial({
      color: 0x212121,
      roughness: 0.7,
      metalness: 0.1,
    });

    this.skinMat = new THREE.MeshStandardMaterial({
      color: 0xffcc80,
      roughness: 0.6,
    });
  }

  _buildBlasterModel() {
    this.blasterGroup = new THREE.Group();

    // Main Cyan Receiver Body
    const bodyGeo = new THREE.BoxGeometry(0.12, 0.16, 0.42);
    const bodyMesh = new THREE.Mesh(bodyGeo, this.cyanMat);
    this.blasterGroup.add(bodyMesh);

    // Purple Top Sight Rail
    const railGeo = new THREE.BoxGeometry(0.08, 0.06, 0.46);
    const railMesh = new THREE.Mesh(railGeo, this.purpleRailMat);
    railMesh.position.set(0, 0.11, 0);
    this.blasterGroup.add(railMesh);

    // Front Sight Ring
    const frontSight = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.05, 0.03), this.purpleRailMat);
    frontSight.position.set(0, 0.15, -0.2);
    this.blasterGroup.add(frontSight);

    // Orange Side Power Cells / Battery Vents
    const cellGeo = new THREE.BoxGeometry(0.04, 0.09, 0.18);
    const leftCell = new THREE.Mesh(cellGeo, this.orangeMat);
    leftCell.position.set(-0.07, 0.01, 0.02);
    this.blasterGroup.add(leftCell);

    const rightCell = new THREE.Mesh(cellGeo, this.orangeMat);
    rightCell.position.set(0.07, 0.01, 0.02);
    this.blasterGroup.add(rightCell);

    // Neon Cyan Side Screen Display
    const screenGeo = new THREE.BoxGeometry(0.01, 0.05, 0.09);
    const screenMesh = new THREE.Mesh(screenGeo, this.neonScreenMat);
    screenMesh.position.set(-0.076, 0.01, 0.02);
    this.blasterGroup.add(screenMesh);

    // Hexagonal Orange Muzzle Tip
    const muzzleGeo = new THREE.CylinderGeometry(0.05, 0.055, 0.08, 6);
    const muzzleMesh = new THREE.Mesh(muzzleGeo, this.orangeMat);
    muzzleMesh.rotation.x = Math.PI / 2;
    muzzleMesh.position.set(0, 0.01, -0.25);
    this.blasterGroup.add(muzzleMesh);

    // Barrel opening hole
    const holeGeo = new THREE.CylinderGeometry(0.028, 0.028, 0.03, 12);
    const holeMesh = new THREE.Mesh(holeGeo, this.darkGrayMat);
    holeMesh.rotation.x = Math.PI / 2;
    holeMesh.position.set(0, 0.01, -0.29);
    this.blasterGroup.add(holeMesh);

    // Lime Green Lower Grip
    const gripGeo = new THREE.BoxGeometry(0.08, 0.16, 0.09);
    const gripMesh = new THREE.Mesh(gripGeo, this.limeGripMat);
    gripMesh.position.set(0, -0.12, 0.08);
    gripMesh.rotation.x = -0.25;
    this.blasterGroup.add(gripMesh);

    // Trigger Guard
    const guardGeo = new THREE.BoxGeometry(0.04, 0.08, 0.08);
    const guardMesh = new THREE.Mesh(guardGeo, this.darkGrayMat);
    guardMesh.position.set(0, -0.07, 0.01);
    this.blasterGroup.add(guardMesh);

    this.group.add(this.blasterGroup);
  }

  _buildHandsAndArms() {
    this.handsGroup = new THREE.Group();

    // Right Arm (Forearm & Hand holding grip)
    const rightForearmGeo = new THREE.BoxGeometry(0.1, 0.12, 0.45);
    const rightForearm = new THREE.Mesh(rightForearmGeo, this.yellowArmMat);
    rightForearm.position.set(0.18, -0.22, 0.22);
    rightForearm.rotation.set(0.3, -0.25, 0.1);
    this.handsGroup.add(rightForearm);

    // Right Glove
    const rightGloveGeo = new THREE.BoxGeometry(0.11, 0.11, 0.14);
    const rightGlove = new THREE.Mesh(rightGloveGeo, this.gloveMat);
    rightGlove.position.set(0.03, -0.11, 0.1);
    rightGlove.rotation.x = -0.25;
    this.handsGroup.add(rightGlove);

    // Left Arm (Stabilizing front of blaster)
    const leftForearmGeo = new THREE.BoxGeometry(0.1, 0.12, 0.48);
    const leftForearm = new THREE.Mesh(leftForearmGeo, this.yellowArmMat);
    leftForearm.position.set(-0.25, -0.24, 0.16);
    leftForearm.rotation.set(0.35, 0.35, -0.15);
    this.handsGroup.add(leftForearm);

    // Left Glove holding underneath front
    const leftGloveGeo = new THREE.BoxGeometry(0.12, 0.1, 0.13);
    const leftGlove = new THREE.Mesh(leftGloveGeo, this.gloveMat);
    leftGlove.position.set(-0.06, -0.09, -0.06);
    leftGlove.rotation.set(0.1, 0.3, -0.2);
    this.handsGroup.add(leftGlove);

    this.group.add(this.handsGroup);
  }

  _buildMuzzleFlash() {
    const flashGroup = new THREE.Group();
    const flashGeo = new THREE.ConeGeometry(0.12, 0.35, 6);
    const flashMat = new THREE.MeshBasicMaterial({
      color: 0xffea00,
      transparent: true,
      opacity: 0.9,
    });
    this.flashMesh = new THREE.Mesh(flashGeo, flashMat);
    this.flashMesh.rotation.x = -Math.PI / 2;
    this.flashMesh.position.set(0, 0.01, -0.46);
    this.flashMesh.visible = false;
    flashGroup.add(this.flashMesh);

    // Small spark star
    const starGeo = new THREE.BoxGeometry(0.24, 0.24, 0.02);
    const starMat = new THREE.MeshBasicMaterial({ color: 0xff9100 });
    this.starMesh = new THREE.Mesh(starGeo, starMat);
    this.starMesh.position.set(0, 0.01, -0.32);
    this.starMesh.visible = false;
    flashGroup.add(this.starMesh);

    this.blasterGroup.add(flashGroup);
  }

  triggerFire() {
    // Punchy snappy recoil
    this.recoilVel = 0.18;
    this.flashMesh.visible = true;
    this.starMesh.visible = true;
    this.starMesh.rotation.z = Math.random() * Math.PI;
    setTimeout(() => {
      this.flashMesh.visible = false;
      this.starMesh.visible = false;
    }, 45);
  }

  setTucked(tucked) {
    this.isTucked = !!tucked;
  }

  update(dt, speed = 0, isGrounded = true, isSliding = false) {
    // Smooth transition between FPS view and Morph-Ball tuck
    const targetTuck = this.isTucked ? 1 : 0;
    this.tuckProgress += (targetTuck - this.tuckProgress) * Math.min(1, dt * 14);

    // Physics recoil spring
    this.recoil += this.recoilVel;
    this.recoilVel -= this.recoil * 35 * dt;
    this.recoilVel *= 0.85;

    // Movement bobbing
    if (speed > 0.5 && isGrounded && !this.isTucked) {
      this.bobTime += dt * Math.min(14, speed * 0.8);
    } else {
      this.bobTime += dt * 1.5; // gentle idle breathing
    }

    const bobX = Math.sin(this.bobTime) * 0.015;
    const bobY = Math.abs(Math.cos(this.bobTime)) * 0.02;

    // Slide tilt when sliding
    const slideRoll = isSliding ? 0.2 : 0;

    // Compose position and rotation
    this.group.position.x = this.basePos.x + bobX;
    this.group.position.y = this.basePos.y - bobY - this.tuckProgress * 0.8; // drop down out of view when tucked
    this.group.position.z = this.basePos.z + this.recoil;

    this.group.rotation.x = this.recoil * 1.2 - this.tuckProgress * 0.6;
    this.group.rotation.z = slideRoll;
    this.group.visible = this.tuckProgress < 0.98;
  }

  dispose() {
    this.camera.remove(this.group);
  }
}
