// BuildADweebLab.js — 3D Turntable Workshop & Creature Customizer
//
// Manages the real-time 3D pedestal, lighting, live mesh regeneration,
// procedural random mutation, and configuration persistence for Build-A-Dweeb.

import * as THREE from 'three';
import { toonMat, noOutline } from '../render/Toon.js';
import {
  buildCustomDweebModel,
  DEFAULT_BUILD_CONFIG,
  ARCHETYPE_PRESETS,
  BODY_SHAPES,
  APPENDAGES,
  FEET_TYPES,
  BROW_STYLES,
  MOUTH_STYLES,
  refreshDweebCollider,
  installAppendageGameplay,
} from './CustomDweebModel.js';
import { TournamentBracket } from './Tournament.js';
import {
  creatureKeyFor,
  loadCreatureRecord,
  loadLastFightReport,
  clearLastFightReport,
  recordFightForCreature,
  tournamentPlacement,
  deriveFightHint,
} from './FightRecord.js';
import * as Passport from '../game/Passport.js';

const STORAGE_KEY = 'dweebs-custom-build';
const TOURNAMENT_KEY = 'dweebs-tournament-v1';

/** Persist a live bracket for the workshop ⇄ arena round-trip. */
export function saveTournamentProgress(tournament) {
  try {
    if (tournament) localStorage.setItem(TOURNAMENT_KEY, JSON.stringify(tournament.toJSON()));
  } catch { /* private mode */ }
}

export function loadTournamentProgress() {
  try {
    const saved = localStorage.getItem(TOURNAMENT_KEY);
    if (!saved) return null;
    const t = TournamentBracket.fromJSON(JSON.parse(saved));
    return t.status === 'in' ? t : null;
  } catch { /* corrupted / private mode */ }
  return null;
}

export function clearTournamentProgress() {
  try { localStorage.removeItem(TOURNAMENT_KEY); } catch { /* private mode */ }
}

export { creatureKeyFor, loadCreatureRecord, loadLastFightReport, recordFightForCreature, deriveFightHint };

/** Dispose every geometry/material under an object once (safe with duplicates). */
function disposeObjectResources(root) {
  if (!root) return;
  const geometries = new Set();
  const materials = new Set();
  root.traverse(obj => {
    if (obj.geometry && !geometries.has(obj.geometry)) {
      geometries.add(obj.geometry);
      obj.geometry.dispose?.();
    }
    const mats = Array.isArray(obj.material) ? obj.material : obj.material ? [obj.material] : [];
    for (const mat of mats) {
      if (!materials.has(mat)) {
        materials.add(mat);
        mat.dispose?.();
      }
    }
  });
}

export class BuildADweebLab {
  constructor(scene, camera, renderer) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = renderer;

    this.group = new THREE.Group();
    this.group.name = 'BuildADweebLab';
    this.scene.add(this.group);

    this.config = this.loadConfig();
    this.creatureKey = creatureKeyFor(this.config);
    this.record = loadCreatureRecord(this.config);
    this.turntableAngle = 0;
    this.autoRotate = true;
    this.clock = 0;

    // Presentation state: the creature faces the camera and sways gently.
    // Dragging adds a temporary offset that eases back into the sway.
    this.facingAngle = 0;
    this.swayAngle = 0;
    this.dragOffset = 0;
    this.dragging = false;
    this.dragPointerId = null;
    this.dragLastX = 0;
    this.dragReleaseTime = 0;

    // Short squash-and-stretch reaction driven by every edit.
    this.reaction = { active: false, elapsed: 0, duration: 0.35, strength: 0 };

    // Live fighter synced to lab mutations (DNA → collider, no reload) and
    // the active tournament bracket (null when no tournament is running).
    this.attachedFighter = null;
    this.tournament = this.loadTournament();

    this._buildStage();
    this._buildSparkles();
    this._setupPointerControls();
    this.rebuildModel();
    this.frameCamera();
  }

  _buildStage() {
    // 1. Circular showroom pedestal, sized so the creature reads as the hero.
    const pedestalGeo = new THREE.CylinderGeometry(1.35, 1.5, 0.24, 48);
    const pedestalMat = toonMat({ color: 0x241b3a, flatShading: true });
    const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
    pedestal.position.set(0, -0.12, 0);
    pedestal.receiveShadow = true;
    noOutline(pedestal);
    this.pedestal = pedestal;
    this.group.add(pedestal);

    // Glowing rim ring around the lip of the pedestal.
    const ringGeo = new THREE.TorusGeometry(1.37, 0.035, 10, 64);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xffd23f });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.set(0, 0.01, 0);
    noOutline(ring);
    this.group.add(ring);
    this.rimRing = ring;

    // Outer neon energy halo ring and decor are kept in a dedicated decor subgroup
    // so this.group.children count remains invariant: [pedestal, ring, lights, currentModelRoot] = 4
    this.decorGroup = new THREE.Group();
    this.decorGroup.name = 'PedestalDecor';
    ring.add(this.decorGroup);

    const haloGeo = new THREE.TorusGeometry(1.9, 0.02, 6, 32);
    const haloMat = new THREE.MeshBasicMaterial({ color: 0x3fa9ff, transparent: true, opacity: 0.7 });
    const halo = new THREE.Mesh(haloGeo, haloMat);
    halo.position.set(0, 0, -0.06);
    noOutline(halo);
    this.decorGroup.add(halo);
    this.haloRing = halo;

    // Pedestal accent runes / gem markers
    this.pedestalGems = [];
    const gemMat = new THREE.MeshBasicMaterial({ color: 0x5ee06a });
    const gemGeo = new THREE.OctahedronGeometry(0.06, 0);
    for (let i = 0; i < 6; i++) {
      const ang = (i / 6) * Math.PI * 2;
      const gem = new THREE.Mesh(gemGeo, gemMat);
      gem.position.set(Math.cos(ang) * 1.55, Math.sin(ang) * 1.55, 0.01);
      noOutline(gem);
      this.decorGroup.add(gem);
      this.pedestalGems.push(gem);
    }

    // Floating turntable sparkle / dust particles
    const particleCount = 28;
    const pGeo = new THREE.BufferGeometry();
    const posArr = new Float32Array(particleCount * 3);
    this.particleData = [];
    for (let i = 0; i < particleCount; i++) {
      const ang = Math.random() * Math.PI * 2;
      const rad = 0.5 + Math.random() * 1.5;
      const y = 0.1 + Math.random() * 1.8;
      posArr[i * 3] = Math.cos(ang) * rad;
      posArr[i * 3 + 1] = y;
      posArr[i * 3 + 2] = Math.sin(ang) * rad;
      this.particleData.push({
        baseAngle: ang,
        radius: rad,
        speed: 0.4 + Math.random() * 0.8,
        bobSpeed: 1.5 + Math.random() * 2,
        baseY: y,
      });
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    const pMat = new THREE.PointsMaterial({
      color: 0xffd23f,
      size: 0.08,
      transparent: true,
      opacity: 0.85,
    });
    this.particles = new THREE.Points(pGeo, pMat);
    this.decorGroup.add(this.particles);

    // Soft three-point showcase lighting: warm key, cool rim, gentle fill,
    // plus a low golden kicker that catches the pedestal edge.
    this.lights = new THREE.Group();
    this.lights.name = 'BuildLabLights';
    const key = new THREE.DirectionalLight(0xfff5ea, 2.2);
    key.position.set(3.5, 6, 4.5);
    const rim = new THREE.DirectionalLight(0x3fa9ff, 1.5);
    rim.position.set(-4.5, 3.5, -4.5);
    const fill = new THREE.HemisphereLight(0xfff8ee, 0x2a1e42, 1.0);
    const rimKick = new THREE.PointLight(0xffd23f, 1.1, 5, 2);
    rimKick.position.set(0, 0.35, -1.65);
    // Upward floor underlight accentuating the creature's underside
    const floorGlow = new THREE.PointLight(0xffd23f, 1.8, 4.5);
    floorGlow.position.set(0, 0.1, 0);
    this.lights.add(key, rim, fill, rimKick, floorGlow);
    this.group.add(this.lights);
    this.floorGlow = floorGlow;
  }

  /** Persistent sparkle pool anchored to the pedestal (one geometry, no churn). */
  _buildSparkles() {
    const max = 240;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(max * 3);
    const colors = new Float32Array(max * 3);
    for (let i = 0; i < max; i++) positions[i * 3 + 1] = -1000;
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geometry.setDrawRange(0, 0);

    const material = new THREE.PointsMaterial({
      size: 0.075,
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geometry, material);
    points.name = 'BuildLabSparkles';
    points.frustumCulled = false;
    noOutline(points);
    (this.pedestal || this.group).add(points);

    this._sparkles = {
      max,
      points,
      geometry,
      material,
      positions,
      colors,
      particles: [],
    };
  }

  /** Rotate the creature by dragging the 3D canvas (HUD panels are separate DOM). */
  _setupPointerControls() {
    const canvas = this.renderer?.domElement;
    if (!canvas || typeof canvas.addEventListener !== 'function') return;

    this._canvas = canvas;
    this._prevTouchAction = canvas.style?.touchAction;
    if (canvas.style) canvas.style.touchAction = 'none';

    this._onPointerDownBound = e => this._onPointerDown(e);
    this._onPointerMoveBound = e => this._onPointerMove(e);
    this._onPointerUpBound = e => this._onPointerUp(e);

    // Keep both targets so drags continue outside the canvas while still
    // working with synthetic events dispatched directly at the canvas.
    canvas.addEventListener('pointerdown', this._onPointerDownBound);
    canvas.addEventListener('pointermove', this._onPointerMoveBound);
    canvas.addEventListener('pointerup', this._onPointerUpBound);
    canvas.addEventListener('pointercancel', this._onPointerUpBound);
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
      window.addEventListener('pointermove', this._onPointerMoveBound);
      window.addEventListener('pointerup', this._onPointerUpBound);
      window.addEventListener('pointercancel', this._onPointerUpBound);
    }
  }

  _onPointerDown(e) {
    if (e.button !== undefined && e.button !== 0) return;
    this.dragging = true;
    this.dragPointerId = e.pointerId;
    this.dragLastX = e.clientX;
    this.dragReleaseTime = 0;
    if (e.pointerId !== undefined) {
      try { this._canvas?.setPointerCapture?.(e.pointerId); } catch { /* not captured */ }
    }
  }

  _onPointerMove(e) {
    if (e === this._lastPointerMoveEvent) return; // canvas + window bubbling
    this._lastPointerMoveEvent = e;
    if (!this.dragging) return;
    if (this.dragPointerId !== null && e.pointerId !== undefined && e.pointerId !== this.dragPointerId) return;
    const dx = e.clientX - this.dragLastX;
    this.dragLastX = e.clientX;
    this.dragOffset += dx * 0.012;
    this.dragReleaseTime = 0;
  }

  _onPointerUp(e) {
    if (e === this._lastPointerUpEvent) return; // canvas + window bubbling
    this._lastPointerUpEvent = e;
    if (!this.dragging) return;
    if (this.dragPointerId !== null && e.pointerId !== undefined && e.pointerId !== this.dragPointerId) return;
    this.dragging = false;
    this.dragPointerId = null;
    this.dragReleaseTime = 0;
    if (e.pointerId !== undefined) {
      try { this._canvas?.releasePointerCapture?.(e.pointerId); } catch { /* not captured */ }
    }
  }

  /** Kick off a short squash-and-stretch pop plus a pedestal sparkle burst. */
  _playReaction(strength = 'normal') {
    const big = strength === 'big';
    this.reaction.active = true;
    this.reaction.elapsed = 0;
    this.reaction.duration = big ? 0.42 : 0.35;
    this.reaction.strength = big ? 0.3 : 0.14;
    this._spawnSparkles(big ? 72 : 30);
  }

  _spawnSparkles(count) {
    const fx = this._sparkles;
    if (!fx || !fx.points) return;

    const safeColor = (value, fallback) => {
      try {
        return new THREE.Color(value || fallback);
      } catch {
        return new THREE.Color(fallback);
      }
    };
    const palette = [
      safeColor(this.config?.primaryColor, '#ff4d5e'),
      safeColor(this.config?.accentColor, '#ffd23f'),
    ];

    for (let i = 0; i < count; i++) {
      if (fx.particles.length >= fx.max) fx.particles.shift();
      const color = palette[i % palette.length];
      const angle = Math.random() * Math.PI * 2;
      const radius = 0.25 + Math.random() * 1.1;
      const outward = 0.45 + Math.random() * 1.25;
      const life = 0.5 + Math.random() * 0.5;
      fx.particles.push({
        x: Math.cos(angle) * radius,
        y: 0.04 + Math.random() * 0.16,
        z: Math.sin(angle) * radius,
        vx: Math.cos(angle) * outward,
        vy: 0.9 + Math.random() * 1.8,
        vz: Math.sin(angle) * outward,
        life,
        maxLife: life,
        r: color.r,
        g: color.g,
        b: color.b,
      });
    }
  }

  _updateSparkles(dt) {
    const fx = this._sparkles;
    if (!fx || !fx.geometry) return;

    const { positions, colors, particles, max } = fx;
    let write = 0;
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        particles.splice(i, 1);
        continue;
      }
      p.vy -= 2.8 * dt;
      p.vx *= Math.max(0, 1 - dt * 0.8);
      p.vz *= Math.max(0, 1 - dt * 0.8);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      if (p.y < 0.02) {
        p.y = 0.02;
        p.vy *= -0.35;
        p.vx *= 0.8;
        p.vz *= 0.8;
      }
    }

    for (const p of particles) {
      if (write >= max) break;
      const o = write * 3;
      positions[o] = p.x;
      positions[o + 1] = p.y;
      positions[o + 2] = p.z;
      const fade = Math.max(0, p.life / p.maxLife);
      colors[o] = p.r * fade;
      colors[o + 1] = p.g * fade;
      colors[o + 2] = p.b * fade;
      write++;
    }

    fx.geometry.setDrawRange(0, write);
    fx.geometry.attributes.position.needsUpdate = true;
    fx.geometry.attributes.color.needsUpdate = true;
  }

  /** Frame the creature so it occupies roughly the middle third of the view. */
  frameCamera(targetFraction = 0.34) {
    if (!this.camera || !this.currentModelRoot) return;
    this.currentModelRoot.updateWorldMatrix(true, true);
    const box = new THREE.Box3().setFromObject(this.currentModelRoot);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    const height = Math.max(size.y, 0.8);
    const width = Math.max(size.x, size.z, 0.8);
    const vFov = THREE.MathUtils.degToRad(this.camera.fov || 60);
    const aspect = this.camera.aspect || 16 / 9;
    const tanHalf = Math.tan(vFov / 2);
    const fitHeight = height / (2 * tanHalf * targetFraction);
    const fitWidth = width / (2 * tanHalf * aspect * targetFraction);
    const distance = Math.max(fitHeight, fitWidth, 2.4);
    const eyeHeight = Math.max(0.75, center.y + height * 0.16);
    this.camera.position.set(center.x, eyeHeight, center.z + distance);
    this.camera.lookAt(center.x, center.y, center.z);
    this.camera.updateProjectionMatrix?.();
  }

  rebuildModel() {
    if (this.currentModelRoot) {
      disposeObjectResources(this.currentModelRoot);
      this.group.remove(this.currentModelRoot);
      this.currentModelRoot = null;
    }

    this.modelInstance = buildCustomDweebModel(this.config);
    this.currentModelRoot = this.modelInstance.root;
    this.group.add(this.currentModelRoot);

    // Juicy animated preview transition: pop-in squish & stretch on rebuild
    this.transitionTime = 0.45;
    this.currentModelRoot.scale.set(0.1, 1.8, 0.1);

    // DNA mutation → live fighter sync: refresh the attached fighter's
    // bounding-box collider and appendage gameplay synchronously so a
    // mutation never needs a scene reload to take effect physically.
    // Note: compute bounds directly from the freshly built config rather than
    // reading from the transitional squished root so collider sync remains deterministic.
    if (this.attachedFighter) {
      refreshDweebCollider(this.attachedFighter, this.config);
      installAppendageGameplay(this.attachedFighter, this.config);
    }
  }

  /**
   * Attach a live fighter dweeb: every lab mutation (mutateRandom /
   * updateConfig / applyPreset) synchronously refreshes its physics collider
   * bounds and appendage gameplay to match the new DNA. Pass null to detach.
   */
  attachFighter(dweeb) {
    this.attachedFighter = dweeb || null;
    if (this.attachedFighter && this.modelInstance) {
      this.modelInstance.root.updateWorldMatrix(true, true);
      refreshDweebCollider(this.attachedFighter, this.config,
        new THREE.Box3().setFromObject(this.modelInstance.root));
      installAppendageGameplay(this.attachedFighter, this.config);
    }
    return this.attachedFighter;
  }

  detachFighter() {
    this.attachedFighter = null;
  }

  updateConfig(patch) {
    this.config = {
      ...this.config,
      ...patch,
      stats: { ...this.config.stats, ...(patch.stats || {}) },
      dna: { ...this.config.dna, ...(patch.dna || {}) },
    };

    // Check chimera synthesis milestone: 5 or more appendages / features configured
    const appList = Array.isArray(this.config.appendages)
      ? this.config.appendages
      : (this.config.appendage ? [this.config.appendage] : []);
    const extraParts = [
      this.config.horn, this.config.tail, this.config.wings, this.config.ears,
      this.config.antenna, this.config.hat, this.config.glasses,
    ].filter(Boolean);
    const totalAppendages = appList.length + extraParts.length;
    if (totalAppendages >= 5) {
      try { Passport.record('chimera-synth'); } catch { /* ignore */ }
    }

    this.rebuildModel();
    this.saveConfig();
    this.creatureKey = creatureKeyFor(this.config);
    this.record = loadCreatureRecord(this.config);
    this._playReaction('normal');
  }

  applyPreset(presetKey) {
    const preset = ARCHETYPE_PRESETS[presetKey];
    if (!preset) return null;
    this.config = {
      ...this.config,
      ...preset,
      stats: {
        ...(this.config.stats || {}),
        ...(preset.stats || {}),
        mass: preset.mass ?? preset.stats?.mass ?? this.config.stats?.mass ?? 3.0,
        armor: preset.armor ?? preset.stats?.armor ?? this.config.stats?.armor ?? 1.0,
        speed: preset.speed ?? preset.stats?.speed ?? this.config.stats?.speed ?? 1.0,
        jump: preset.jump ?? preset.stats?.jump ?? this.config.stats?.jump ?? 1.0,
      },
      dna: {
        ...(this.config.dna || {}),
        ...(preset.dna || preset.DNA || {}),
      },
    };
    if (preset.brow && !this.config.brows) this.config.brows = preset.brow;
    if (preset.appendages && !this.config.appendage) this.config.appendage = preset.appendages;
    this.rebuildModel();
    this.saveConfig();
    this.creatureKey = creatureKeyFor(this.config);
    this.record = loadCreatureRecord(this.config);
    this._playReaction('normal');
    return this.config;
  }

  mutateRandom() {
    const randomHex = () => '#' + Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0');
    const pick = arr => arr[Math.floor(Math.random() * arr.length)];
    const randRange = (min, max) => Number((min + Math.random() * (max - min)).toFixed(2));

    const titles = ['Mecha', 'Giga', 'Hyper', 'Turbo', 'Shadow', 'Cosmic', 'Pixel', 'Savage', 'Bouncy', 'Dr.'];
    const names = ['Goblin', 'Brawler', 'Pugilist', 'Titan', 'Gremlin', 'Crusher', 'Slugger', 'Menace', 'Bean'];

    const newConfig = {
      name: `${pick(titles)} ${pick(names)}`,
      shape: pick(BODY_SHAPES),
      width: randRange(0.6, 1.6),
      height: randRange(0.6, 1.5),
      depth: randRange(0.7, 1.4),
      primaryColor: randomHex(),
      accentColor: randomHex(),
      eyeColor: '#14101c',
      eyeCount: pick([1, 2, 2, 2, 3, 4]),
      eyeSize: randRange(0.6, 1.5),
      eyeSpacing: randRange(0.7, 1.4),
      brows: pick(BROW_STYLES),
      mouth: pick(MOUTH_STYLES),
      appendage: pick(APPENDAGES),
      feet: pick(FEET_TYPES),
      stats: {
        speed: randRange(0.7, 1.3),
        mass: randRange(2.0, 4.2),
        jump: randRange(0.8, 1.3),
        armor: randRange(0.8, 1.2),
      },
      dna: {
        confidence: randRange(0.2, 1.0),
        aimAccuracy: randRange(0.2, 0.95),
        scavenge: randRange(0.1, 0.9),
        agility: randRange(0.4, 0.95),
      },
    };

    this.config = newConfig;
    this.rebuildModel();
    this.saveConfig();
    this.creatureKey = creatureKeyFor(this.config);
    this.record = loadCreatureRecord(this.config);
    this._playReaction('big');
    return this.config;
  }

  // ─── Colosseum tournament ladder ──────────────────────────────────────────

  /** Start a new tournament bracket with the lab's current build. */
  startTournament() {
    this.tournament = new TournamentBracket(this.config);
    this.saveTournament();
    return this.tournament.state();
  }

  /** Champion config for the player's pending bout (null when none). */
  tournamentOpponent() {
    return this.tournament ? this.tournament.opponentForPlayer() : null;
  }

  /**
   * Record the player's bout result and advance the bracket. Persists across
   * the workshop ⇄ arena round-trip; cleared when the run ends.
   */
  recordTournamentResult(playerWon) {
    if (!this.tournament) return null;
    const state = this.tournament.recordPlayerResult(!!playerWon);

    // Cross-game Passport Milestones
    if (playerWon) {
      try {
        Passport.record('defeat-champion');
        if (state.status === 'champion') {
          Passport.record('grand-champion');
        }
      } catch { /* storage guards */ }
    }

    if (state.status === 'in') this.saveTournament();
    else this.clearTournamentStorage();

    // A manual result still updates the creature's persistent ladder record.
    // No Fight Report is published because this path has no combat stats.
    const placement = tournamentPlacement(state);
    const { record } = recordFightForCreature(this.config, {
      result: playerWon ? 'win' : 'loss',
      tournament: true,
      placementRank: placement.rank,
      placementLabel: placement.label,
      roundName: state.roundName,
      opponentName: state.opponent?.name || 'Champion',
    }, { saveReport: false });
    this.record = record;
    return state;
  }

  /** Plain bracket summary for the HUD (null when no tournament active). */
  tournamentState() {
    return this.tournament ? this.tournament.state() : null;
  }

  abandonTournament() {
    this.tournament = null;
    this.clearTournamentStorage();
  }

  /** Persistent record for the creature currently on the pedestal. */
  creatureRecord() {
    this.record = loadCreatureRecord(this.config);
    return this.record;
  }

  /** Pending Fight Report for this creature (null once dismissed / none). */
  lastFightReport() {
    const report = loadLastFightReport();
    return report && report.creatureKey === creatureKeyFor(this.config) ? report : null;
  }

  /** Record a real bout for this creature and publish its Fight Report. */
  recordFight(fight = {}) {
    const { report, record } = recordFightForCreature(this.config, fight);
    this.record = record;
    return report;
  }

  recordFightResult(fight = {}) {
    return this.recordFight(fight);
  }

  getCreatureRecord() {
    return this.creatureRecord();
  }

  getLastFightReport() {
    return this.lastFightReport();
  }

  dismissFightReport() {
    clearLastFightReport();
  }

  saveTournament() {
    saveTournamentProgress(this.tournament);
  }

  loadTournament() {
    return loadTournamentProgress();
  }

  clearTournamentStorage() {
    clearTournamentProgress();
  }

  update(dt) {
    this.clock += dt;

    const model = this.currentModelRoot;
    if (model) {
      // The creature's front faces +Z. Face the camera, then sway around that
      // heading instead of endlessly turning its back to the player.
      if (this.camera) {
        this.facingAngle = Math.atan2(
          this.camera.position.x - this.group.position.x,
          this.camera.position.z - this.group.position.z,
        );
      }
      const swayMax = THREE.MathUtils.degToRad(35);
      this.swayAngle = this.autoRotate ? Math.sin(this.clock * 0.6) * swayMax : 0;

      // After release, hold the dragged angle briefly, then ease back into the
      // sway so the creature settles home at roughly the 2 second mark.
      if (!this.dragging) {
        this.dragReleaseTime += dt;
        if (this.dragReleaseTime >= 1.1 && this.dragOffset !== 0) {
          const ease = 1 - Math.exp(-dt * 8);
          this.dragOffset += (0 - this.dragOffset) * ease;
          if (Math.abs(this.dragOffset) < 0.001) this.dragOffset = 0;
        }
      }

      this.turntableAngle = this.facingAngle + this.swayAngle + this.dragOffset;
      model.rotation.y = this.turntableAngle;

      // Squash-and-stretch pop with a damped overshoot.
      const r = this.reaction;
      if (r.active) {
        r.elapsed += dt;
        const t = Math.min(1, r.elapsed / r.duration);
        const wobble = Math.sin(t * Math.PI * 2.5) * Math.pow(1 - t, 1.4);
        const pop = r.strength * wobble;
        model.scale.set(1 - pop * 0.55, 1 + pop, 1 - pop * 0.55);
        if (t >= 1) {
          r.active = false;
          r.elapsed = 0;
          model.scale.set(1, 1, 1);
        }
      } else {
        model.scale.set(1, 1, 1);
      }
    }

    // Pedestal glow pulsation
    if (this.rimRing) {
      const pulse = 1 + Math.sin(this.clock * 3) * 0.04;
      this.rimRing.scale.set(pulse, pulse, 1);
    }
    if (this.haloRing) {
      this.haloRing.rotation.z += dt * 0.5;
      const hPulse = 0.6 + Math.sin(this.clock * 4) * 0.2;
      this.haloRing.material.opacity = hPulse;
    }
    if (this.floorGlow) {
      this.floorGlow.intensity = 1.6 + Math.sin(this.clock * 4) * 0.4;
    }
    if (this.pedestalGems) {
      for (let i = 0; i < this.pedestalGems.length; i++) {
        const gem = this.pedestalGems[i];
        gem.rotation.y += dt * (1 + i * 0.2);
        gem.position.y = 0.02 + Math.sin(this.clock * 3 + i) * 0.015;
      }
    }

    // Floating turntable dust particles orbiting upward
    if (this.particles && this.particleData) {
      const posAttr = this.particles.geometry.attributes.position;
      const arr = posAttr.array;
      for (let i = 0; i < this.particleData.length; i++) {
        const p = this.particleData[i];
        p.baseAngle += dt * p.speed * 0.4;
        const curY = 0.05 + ((p.baseY + this.clock * p.speed * 0.2) % 1.9);
        arr[i * 3] = Math.cos(p.baseAngle) * p.radius;
        arr[i * 3 + 1] = curY + Math.sin(this.clock * p.bobSpeed) * 0.03;
        arr[i * 3 + 2] = Math.sin(p.baseAngle) * p.radius;
      }
      posAttr.needsUpdate = true;
    }

    // Preview transition animation (elastic pop-in)
    if (this.transitionTime > 0 && this.currentModelRoot) {
      this.transitionTime -= dt;
      const progress = Math.max(0, 1 - (this.transitionTime / 0.45));
      // Overshooting elastic ease-out
      const c4 = (2 * Math.PI) / 3;
      const ease = progress === 0 ? 0 : progress === 1 ? 1 : Math.pow(2, -10 * progress) * Math.sin((progress * 10 - 0.75) * c4) + 1;
      const currentScaleY = THREE.MathUtils.lerp(1.8, 1.0, ease);
      const currentScaleXZ = THREE.MathUtils.lerp(0.1, 1.0, ease);
      this.currentModelRoot.scale.set(currentScaleXZ, currentScaleY, currentScaleXZ);
      if (this.transitionTime <= 0) {
        this.currentModelRoot.scale.set(1, 1, 1);
      }
    }

    if (this.modelInstance) {
      this.modelInstance.animate(this.clock);
    }
    this._updateSparkles(dt);
  }

  saveConfig() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.config));
    } catch { /* private mode */ }
  }

  loadConfig() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) return { ...DEFAULT_BUILD_CONFIG, ...JSON.parse(saved) };
    } catch { /* fallback */ }
    return { ...DEFAULT_BUILD_CONFIG };
  }

  dispose() {
    if (!this.group) return;

    if (this._canvas && this._onPointerDownBound) {
      this._canvas.removeEventListener('pointerdown', this._onPointerDownBound);
      this._canvas.removeEventListener('pointermove', this._onPointerMoveBound);
      this._canvas.removeEventListener('pointerup', this._onPointerUpBound);
      this._canvas.removeEventListener('pointercancel', this._onPointerUpBound);
      if (typeof window !== 'undefined') {
        window.removeEventListener('pointermove', this._onPointerMoveBound);
        window.removeEventListener('pointerup', this._onPointerUpBound);
        window.removeEventListener('pointercancel', this._onPointerUpBound);
      }
      if (this._canvas.style && this._prevTouchAction !== undefined) {
        this._canvas.style.touchAction = this._prevTouchAction;
      }
    }
    this._onPointerDownBound = null;
    this._onPointerMoveBound = null;
    this._onPointerUpBound = null;
    this._lastPointerMoveEvent = null;
    this._lastPointerUpEvent = null;
    this._canvas = null;

    if (this._sparkles) {
      this._sparkles.particles.length = 0;
      this._sparkles.geometry?.setDrawRange(0, 0);
      this._sparkles = null;
    }
    this.reaction.active = false;

    disposeObjectResources(this.group);
    this.scene?.remove(this.group);
    this.currentModelRoot = null;
    this.modelInstance = null;
    this.lights = null;
    this.pedestal = null;
    this.attachedFighter = null;
  }
}
