// SkateAudio.js — Procedural Web Audio for Skatepark Rumble (Roll & Shoot FFA).
//
// Zero external sound asset dependencies. Pure synthesized audio:
// - Blaster laser / toy dart shot
// - Hit marker tick / confirm
// - Morph ball roll rumble & whoosh
// - Transform spring pop
// - Trick score chime (+50 SLIDEOUT!)
// - Kill announcement fanfare
// - Jump & foam pit bounce

export class SkateAudio {
  constructor({ soundOn = true } = {}) {
    this.soundOn = soundOn;
    this.ctx = null;
    this.master = null;
    this.rollSource = null;
    this.rollGain = null;
    this.rollFilter = null;
    this._initialized = false;
  }

  init() {
    if (this._initialized) return;
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      this.ctx = new AudioCtx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.soundOn ? 0.8 : 0;
      this.master.connect(this.ctx.destination);
      this._setupRollLoop();
      this._initialized = true;
    } catch {
      // Audio context might be restricted until user interaction
    }
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
  }

  setSoundOn(on) {
    this.soundOn = !!on;
    if (this.master && this.ctx) {
      this.master.gain.setValueAtTime(this.soundOn ? 0.8 : 0, this.ctx.currentTime);
    }
  }

  _setupRollLoop() {
    if (!this.ctx) return;
    // Low rumble noise loop for rolling
    const bufferSize = this.ctx.sampleRate * 2;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      output[i] = Math.random() * 2 - 1;
    }

    const whiteNoise = this.ctx.createBufferSource();
    whiteNoise.buffer = noiseBuffer;
    whiteNoise.loop = true;

    this.rollFilter = this.ctx.createBiquadFilter();
    this.rollFilter.type = 'lowpass';
    this.rollFilter.frequency.value = 80;

    this.rollGain = this.ctx.createGain();
    this.rollGain.gain.value = 0;

    whiteNoise.connect(this.rollFilter);
    this.rollFilter.connect(this.rollGain);
    this.rollGain.connect(this.master);
    try {
      whiteNoise.start(0);
      this.rollSource = whiteNoise;
    } catch {}
  }

  updateRollSound(speed, inBallMode) {
    if (!this.rollGain || !this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    if (!inBallMode || speed < 0.5) {
      this.rollGain.gain.setTargetAtTime(0, now, 0.05);
      return;
    }
    const normSpeed = Math.min(1, speed / 30);
    const targetGain = 0.05 + normSpeed * 0.25;
    const targetFreq = 100 + normSpeed * 400;
    this.rollGain.gain.setTargetAtTime(targetGain, now, 0.05);
    this.rollFilter.frequency.setTargetAtTime(targetFreq, now, 0.05);
  }

  playShoot() {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(880, now);
    osc.frequency.exponentialRampToValueAtTime(140, now + 0.12);

    gain.gain.setValueAtTime(0.25, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);

    osc.connect(gain);
    gain.connect(this.master);

    osc.start(now);
    osc.stop(now + 0.13);
  }

  playHit() {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(1200, now);
    osc.frequency.setValueAtTime(1800, now + 0.03);

    gain.gain.setValueAtTime(0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

    osc.connect(gain);
    gain.connect(this.master);

    osc.start(now);
    osc.stop(now + 0.09);
  }

  playTransform(toBall) {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    if (toBall) {
      // Pitch drop into compact ball
      osc.frequency.setValueAtTime(600, now);
      osc.frequency.exponentialRampToValueAtTime(180, now + 0.15);
    } else {
      // Spring pop upwards into combat
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.exponentialRampToValueAtTime(820, now + 0.14);
    }

    gain.gain.setValueAtTime(0.28, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);

    osc.connect(gain);
    gain.connect(this.master);

    osc.start(now);
    osc.stop(now + 0.16);
  }

  playTrick(type = 'slide') {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const notes = [523.25, 659.25, 783.99, 1046.5]; // C E G C
    notes.forEach((freq, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const t = now + idx * 0.04;
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0.18, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(t);
      osc.stop(t + 0.19);
    });
  }

  playKill() {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const notes = [440, 554.37, 659.25, 880];
    notes.forEach((freq, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const t = now + idx * 0.06;
      osc.type = 'square';
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0.15, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(t);
      osc.stop(t + 0.26);
    });
  }

  playJump() {
    if (!this.ctx || !this.soundOn) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(180, now);
    osc.frequency.exponentialRampToValueAtTime(450, now + 0.12);

    gain.gain.setValueAtTime(0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);

    osc.connect(gain);
    gain.connect(this.master);

    osc.start(now);
    osc.stop(now + 0.13);
  }

  dispose() {
    if (this.rollGain && this.ctx) {
      this.rollGain.gain.setValueAtTime(0, this.ctx.currentTime);
    }
    if (this.rollSource) {
      try { this.rollSource.stop(); } catch {}
      this.rollSource = null;
    }
  }
}
