// FightRecord.js — Persistent per-creature arena records + last-bout report.
//
// Every value stored here comes from a real match: damage dealt/taken, KOs,
// falls and tournament placement. Nothing is simulated or filled with guesses.

export const CREATURE_RECORD_PREFIX = 'dweebs-creature-record-v1:';
export const LAST_FIGHT_KEY = 'dweebs-last-fight-v1';

const num = value => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

const slug = value => String(value ?? '')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, '-')
  .replace(/[^a-z0-9_-]/g, '');

/** Stable per-creature key. Names are the only identity a custom build carries. */
export function creatureKeyFor(configOrName = {}) {
  const name = typeof configOrName === 'string'
    ? configOrName
    : (configOrName?.name || configOrName?.creatureName || 'Custom Dweeb');
  return slug(name) || 'custom-dweeb';
}

export function creatureRecordKey(configOrName = {}) {
  return `${CREATURE_RECORD_PREFIX}${creatureKeyFor(configOrName)}`;
}

export function emptyCreatureRecord(name = 'Custom Dweeb') {
  return {
    name,
    wins: 0,
    losses: 0,
    matches: 0,
    bestPlacement: null,
    bestPlacementLabel: '',
    totalKos: 0,
    totalDamageDealt: 0,
    totalDamageTaken: 0,
    lastResult: null,
    updatedAt: 0,
  };
}

export function loadCreatureRecord(configOrName = {}) {
  const key = creatureKeyFor(configOrName);
  const name = typeof configOrName === 'string'
    ? configOrName
    : (configOrName?.name || 'Custom Dweeb');
  const base = emptyCreatureRecord(name);
  try {
    const raw = localStorage.getItem(creatureRecordKey(key));
    if (!raw) return base;
    const saved = JSON.parse(raw);
    return {
      ...base,
      ...saved,
      wins: Math.max(0, Math.floor(num(saved.wins))),
      losses: Math.max(0, Math.floor(num(saved.losses))),
      matches: Math.max(0, Math.floor(num(saved.matches ?? (num(saved.wins) + num(saved.losses))))),
      totalKos: Math.max(0, num(saved.totalKos)),
      totalDamageDealt: Math.max(0, num(saved.totalDamageDealt)),
      totalDamageTaken: Math.max(0, num(saved.totalDamageTaken)),
    };
  } catch {
    return base;
  }
}

export function saveCreatureRecord(configOrName, record) {
  try {
    localStorage.setItem(creatureRecordKey(configOrName), JSON.stringify(record));
  } catch { /* private mode / storage full */ }
  return record;
}

export function loadLastFightReport() {
  try {
    const raw = localStorage.getItem(LAST_FIGHT_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function saveLastFightReport(report) {
  try {
    localStorage.setItem(LAST_FIGHT_KEY, JSON.stringify(report));
  } catch { /* private mode / storage full */ }
  return report;
}

export function clearLastFightReport() {
  try { localStorage.removeItem(LAST_FIGHT_KEY); } catch { /* private mode */ }
}

/** Placement rank for the round the player reached (lower is better). */
export function tournamentPlacement(state = {}) {
  const roundIndex = Math.max(0, Math.floor(num(state.roundIndex)));
  if (state.status === 'champion') return { rank: 1, label: 'CHAMPION' };
  if (state.status === 'eliminated') {
    if (roundIndex >= 2) return { rank: 2, label: 'RUNNER-UP' };
    if (roundIndex >= 1) return { rank: 3, label: 'SEMIFINALIST' };
    return { rank: 5, label: 'QUARTERFINALIST' };
  }
  if (roundIndex >= 2) return { rank: 2, label: 'GRAND FINALIST' };
  if (roundIndex >= 1) return { rank: 3, label: 'SEMIFINALIST' };
  return { rank: 5, label: 'QUARTERFINALIST' };
}

/**
 * One concrete, stats-derived tweak hint. Uses the real numbers passed in and
 * falls back to a win/loss observation when both fighters dealt no damage.
 */
export function deriveFightHint(report = {}) {
  const dealt = num(report.damageDealt);
  const taken = num(report.damageTaken);
  const kos = num(report.kos);
  const falls = num(report.falls);
  const won = report.result ? report.result === 'win' : report.won !== false;

  if (taken > 0 && taken > dealt * 1.15) {
    return `You took ${Math.round(taken)} damage vs ${Math.round(dealt)} dealt — add armor or more mass/size so trades hurt less.`;
  }
  if (kos === 0) {
    return `No KOs landed — raise Aim Mastery or mass so your hits can finish the fight.`;
  }
  if (falls > kos) {
    return `${falls} falls vs ${kos} KOs — boost jump and agility to recover back onto the stage.`;
  }
  if (dealt > 0 && dealt >= taken && !won) {
    return `You out-damaged them but still lost — put the extra points into jump/agility to stay on stage.`;
  }
  if (won && taken > dealt * 0.7) {
    return `Close win (${Math.round(taken)} damage taken) — add armor to turn nail-biters into clean wins.`;
  }
  return `Damage is landing (${Math.round(dealt)} dealt, ${kos} KOs) — push mass or armor to close bouts faster.`;
}

function normalizeFight(config, fight = {}) {
  const result = fight.result === 'loss' || fight.won === false ? 'loss' : 'win';
  return {
    ...fight,
    result,
    creatureKey: creatureKeyFor(config),
    creatureName: config?.name || fight.creatureName || 'Custom Dweeb',
    opponentName: fight.opponentName || 'Rival Dweeb',
    damageDealt: Math.max(0, num(fight.damageDealt)),
    damageTaken: Math.max(0, num(fight.damageTaken)),
    kos: Math.max(0, num(fight.kos ?? fight.totalKos)),
    falls: Math.max(0, num(fight.falls ?? fight.totalFalls)),
    timestamp: fight.timestamp || Date.now(),
  };
}

/**
 * Apply a real bout to the creature's persistent record and (unless disabled)
 * publish it as the pending Fight Report for the next workshop visit.
 */
export function recordFightForCreature(config, fight = {}, options = {}) {
  const key = creatureKeyFor(config);
  const record = loadCreatureRecord(config);
  const report = normalizeFight(config, fight);
  const won = report.result === 'win';

  record.name = report.creatureName;
  record.wins += won ? 1 : 0;
  record.losses += won ? 0 : 1;
  record.matches = record.wins + record.losses;
  record.totalKos += report.kos;
  record.totalDamageDealt += report.damageDealt;
  record.totalDamageTaken += report.damageTaken;
  record.lastResult = report.result;
  record.updatedAt = report.timestamp;

  if (fight.placementRank !== null && fight.placementRank !== undefined && Number.isFinite(Number(fight.placementRank))) {
    const rank = Math.max(1, Math.floor(Number(fight.placementRank)));
    if (record.bestPlacement === null || rank < record.bestPlacement) {
      record.bestPlacement = rank;
      record.bestPlacementLabel = fight.placementLabel || report.placementLabel || `#${rank}`;
    }
  }

  saveCreatureRecord(key, record);

  report.creatureKey = key;
  report.hint = report.hint || deriveFightHint(report);
  report.record = { ...record };
  if (options.saveReport !== false) saveLastFightReport(report);

  return { report, record };
}
