// WarfareModels.js — faceted low-poly toy models for Dweeb Warfare.
// Toy-box materials only: coloured plastic, wooden dowels, brass. No voxel blocks.
import * as THREE from 'three';
import { toonMat, noOutline } from '../render/Toon.js';

export const TEAM_COLORS = { blue: 0x3fa9ff, red: 0xff4d5e };

const geo = {};
const mat = {};

function shared() {
  if (geo.body) return;
  geo.body = new THREE.DodecahedronGeometry(0.55, 0);
  geo.sneak = new THREE.OctahedronGeometry(0.5, 0);
  geo.brute = new THREE.IcosahedronGeometry(0.95, 0);
  geo.boss = new THREE.DodecahedronGeometry(1.6, 0);
  geo.eye = new THREE.SphereGeometry(0.13, 6, 4);
  geo.pupil = new THREE.SphereGeometry(0.065, 5, 3);
  geo.disc = new THREE.CylinderGeometry(0.55, 0.55, 0.1, 10);
  geo.tube = new THREE.CylinderGeometry(0.13, 0.17, 1.1, 7);
  geo.bomb = new THREE.IcosahedronGeometry(0.36, 0);
  geo.fuse = new THREE.CylinderGeometry(0.035, 0.035, 0.3, 4);
  geo.spark = new THREE.OctahedronGeometry(0.09, 0);
  geo.band = new THREE.TorusGeometry(0.46, 0.07, 4, 10);
  geo.dowel = new THREE.CylinderGeometry(0.09, 0.09, 1, 6);
  geo.club = new THREE.CylinderGeometry(0.12, 0.26, 1.5, 6);
  geo.gear = new THREE.CylinderGeometry(0.7, 0.7, 0.22, 12);
  geo.tooth = new THREE.ConeGeometry(0.16, 0.36, 4);
  geo.hat = new THREE.ConeGeometry(0.42, 0.9, 6);
  geo.ball = new THREE.IcosahedronGeometry(0.34, 0);
  geo.bubble = new THREE.SphereGeometry(0.5, 8, 6);
  geo.plank = new THREE.BoxGeometry(1.2, 0.16, 0.34);
  geo.jack = new THREE.OctahedronGeometry(0.22, 0);
  geo.barrel = new THREE.CylinderGeometry(0.18, 0.24, 0.9, 7);
  geo.shadow = new THREE.CircleGeometry(0.6, 10);
  geo.ring = new THREE.RingGeometry(0.75, 0.95, 16);
  geo.rallyRing = new THREE.RingGeometry(1.05, 1.34, 24);
  geo.groundRing = new THREE.RingGeometry(0.66, 0.9, 24);
  geo.groundGlow = new THREE.CircleGeometry(0.9, 24);
  mat.blue = toonMat({ color: TEAM_COLORS.blue });
  mat.red = toonMat({ color: TEAM_COLORS.red });
  mat.blueRing = new THREE.MeshBasicMaterial({ color: TEAM_COLORS.blue, transparent: true, opacity: 0.78, side: THREE.DoubleSide, depthWrite: false });
  mat.redRing = new THREE.MeshBasicMaterial({ color: TEAM_COLORS.red, transparent: true, opacity: 0.78, side: THREE.DoubleSide, depthWrite: false });
  mat.blueGlow = new THREE.MeshBasicMaterial({ color: TEAM_COLORS.blue, transparent: true, opacity: 0.2, blending: THREE.AdditiveBlending, depthWrite: false });
  mat.redGlow = new THREE.MeshBasicMaterial({ color: TEAM_COLORS.red, transparent: true, opacity: 0.2, blending: THREE.AdditiveBlending, depthWrite: false });
  mat.flash = new THREE.MeshBasicMaterial({ color: 0xffffff });
  mat.eye = new THREE.MeshBasicMaterial({ color: 0xffffff });
  mat.pupil = new THREE.MeshBasicMaterial({ color: 0x111111 });
  mat.plastic = toonMat({ color: 0xe8eef7 });
  mat.brass = toonMat({ color: 0xd4a73a });
  mat.wood = toonMat({ color: 0xb07a45 });
  mat.darkWood = toonMat({ color: 0x7a4a24 });
  mat.bomb = toonMat({ color: 0x2a2438 });
  mat.spark = new THREE.MeshBasicMaterial({ color: 0xffd23f });
  mat.mask = toonMat({ color: 0x2b2b3a });
  mat.shadow = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.22, depthWrite: false });
  mat.retreat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.85 });
}

export function teamMat(team) { shared(); return mat[team]; }
export function flashMat() { shared(); return mat.flash; }
export function sharedMats() { shared(); return mat; }
export function ringMat(team) { shared(); return mat[team + 'Ring']; }
export function glowMat(team) { shared(); return mat[team + 'Glow']; }

/** Toys read better a bit chunkier than their sim footprint. */
export const UNIT_SCALE_MULT = 1.6;
export const VIEW_SCALE = 1.35 * UNIT_SCALE_MULT;
const SCALE = { shield: 1, rocket: 0.92, stealer: 0.88, kami: 0.85, sneak: 0.85, brute: 1, boss: 1, phalanx: 1.06, catapult: 1.08, wizard: 0.9 };

/**
 * Build one unit. Returns { root, body, gear, spark } where `body` is the mesh whose material
 * flips to white on hit, and `root` is positioned/rotated by the view (faces +x = forward).
 */
export function buildUnit(type, team) {
  shared();
  const root = new THREE.Group();
  const tilt = new THREE.Group();     // knockback lean + waddle live here
  root.add(tilt);
  const bodyGeo = type === 'sneak' ? geo.sneak : type === 'brute' ? geo.brute : type === 'boss' ? geo.boss : geo.body;
  const r = type === 'brute' ? 0.95 : type === 'boss' ? 1.6 : type === 'sneak' ? 0.5 : 0.55;
  const body = new THREE.Mesh(bodyGeo, mat[team]);
  body.position.y = r;
  body.castShadow = true;
  tilt.add(body);

  // googly eyes on the forward (+x) face
  const eyeScale = type === 'boss' ? 2.4 : type === 'brute' ? 1.6 : 1;
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(geo.eye, mat.eye);
    eye.scale.setScalar(eyeScale);
    eye.position.set(r * 0.82, r * 1.25, side * r * 0.32);
    const pupil = new THREE.Mesh(geo.pupil, mat.pupil);
    pupil.position.set(0.1, 0, 0);
    eye.add(pupil);
    tilt.add(eye);
  }

  let gear = null, spark = null;
  if (type === 'shield') {
    gear = new THREE.Group();
    const disc = new THREE.Mesh(geo.disc, mat.plastic);
    disc.rotation.z = Math.PI / 2;
    const boss = new THREE.Mesh(geo.bomb, mat.brass);
    boss.scale.setScalar(0.35);
    boss.position.x = 0.07;
    gear.add(disc, boss);
    gear.position.set(0.72, 0.6, 0);
  } else if (type === 'rocket') {
    gear = new THREE.Mesh(geo.tube, mat.brass);
    gear.rotation.z = -Math.PI / 2.6;
    gear.position.set(0.1, 1.15, 0.32);
  } else if (type === 'stealer') {
    gear = new THREE.Mesh(geo.band, mat.darkWood);
    gear.rotation.x = Math.PI / 2;
    gear.position.y = r * 1.35;
    gear.scale.set(1.05, 1.05, 1);
  } else if (type === 'kami') {
    gear = new THREE.Group();
    const b = new THREE.Mesh(geo.bomb, mat.bomb);
    const f = new THREE.Mesh(geo.fuse, mat.wood);
    f.position.y = 0.42;
    spark = new THREE.Mesh(geo.spark, mat.spark);
    spark.position.y = 0.6;
    noOutline(spark);
    gear.add(b, f, spark);
    gear.position.set(0, 1.35, 0);
  } else if (type === 'sneak') {
    gear = new THREE.Group();
    const m = new THREE.Mesh(geo.band, mat.mask);
    m.rotation.x = Math.PI / 2;
    m.position.y = 0.62;
    m.scale.set(1.05, 1.05, 1.4);
    const knife = new THREE.Mesh(geo.dowel, mat.brass);
    knife.scale.set(0.7, 0.55, 0.7);
    knife.rotation.z = -Math.PI / 2.2;
    knife.position.set(0.55, 0.45, -0.35);
    gear.add(m, knife);
  } else if (type === 'brute') {
    gear = new THREE.Mesh(geo.club, mat.wood);
    gear.rotation.z = -Math.PI / 4;
    gear.position.set(0.7, 1.4, -0.7);
  } else if (type === 'phalanx') {
    gear = new THREE.Group();
    const wall = new THREE.Mesh(geo.disc, mat.plastic);
    wall.scale.set(1.55, 1.75, 1);
    wall.rotation.z = Math.PI / 2;
    wall.position.set(0.82, 0.72, 0);
    const boss = new THREE.Mesh(geo.bomb, mat.brass);
    boss.scale.setScalar(0.3);
    boss.position.set(0.9, 0.72, 0);
    const strap = new THREE.Mesh(geo.dowel, mat.darkWood);
    strap.scale.set(0.6, 1.4, 0.6);
    strap.rotation.z = Math.PI / 2;
    strap.position.set(0.2, 0.9, 0);
    gear.add(wall, boss, strap);
  } else if (type === 'catapult') {
    gear = new THREE.Group();
    const frame = new THREE.Mesh(geo.plank, mat.wood);
    frame.position.set(-0.1, 0.95, 0);
    const arm = new THREE.Mesh(geo.dowel, mat.darkWood);
    arm.scale.set(0.8, 1.5, 0.8);
    arm.rotation.z = -0.9;
    arm.position.set(0.35, 1.25, 0);
    const ball = new THREE.Mesh(geo.ball, teamMat(team));
    ball.position.set(0.78, 1.5, 0);
    gear.add(frame, arm, ball);
    gear.position.y = 0;
  } else if (type === 'wizard') {
    gear = new THREE.Group();
    const hat = new THREE.Mesh(geo.hat, teamMat(team));
    hat.position.y = 1.3;
    const brim = new THREE.Mesh(geo.disc, teamMat(team));
    brim.scale.set(0.9, 0.9, 0.4);
    brim.position.y = 0.92;
    const staff = new THREE.Mesh(geo.dowel, mat.wood);
    staff.scale.set(0.5, 1.35, 0.5);
    staff.position.set(0.55, 0.65, -0.3);
    const bubble = new THREE.Mesh(geo.bubble, new THREE.MeshBasicMaterial({ color: 0x9fe8ff, transparent: true, opacity: 0.45, depthWrite: false }));
    bubble.scale.setScalar(0.45);
    bubble.position.set(0.62, 1.55, -0.3);
    noOutline(bubble);
    gear.add(hat, brim, staff, bubble);
    gear.userData.bubble = bubble;
  } else if (type === 'boss') {
    gear = new THREE.Group();
    const crown = new THREE.Mesh(geo.gear, mat.brass);
    crown.scale.set(1.4, 1, 1.4);
    gear.add(crown);
    for (let i = 0; i < 10; i++) {
      const t = new THREE.Mesh(geo.tooth, mat.brass);
      const a = (i / 10) * Math.PI * 2;
      t.position.set(Math.cos(a) * 0.95, 0.25, Math.sin(a) * 0.95);
      gear.add(t);
    }
    gear.position.y = 3.25;
    const back = new THREE.Mesh(geo.gear, mat.brass);
    back.rotation.z = Math.PI / 2;
    back.position.set(-1.55, 1.7, 0);
    back.name = 'backGear';
    tilt.add(back);
  }
  if (gear) tilt.add(gear);

  const shadow = new THREE.Mesh(geo.shadow, mat.shadow);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.02;
  shadow.scale.setScalar(r / 0.55);
  noOutline(shadow);
  root.add(shadow);

  // Team-readable ground marker: a soft glow disc plus a bright ring under the feet.
  const groundGlow = new THREE.Mesh(geo.groundGlow, mat[team + 'Glow']);
  groundGlow.rotation.x = -Math.PI / 2;
  groundGlow.position.y = 0.03;
  groundGlow.renderOrder = 1;
  noOutline(groundGlow);
  const groundRing = new THREE.Mesh(geo.groundRing, mat[team + 'Ring']);
  groundRing.rotation.x = -Math.PI / 2;
  groundRing.position.y = 0.04;
  groundRing.renderOrder = 2;
  noOutline(groundRing);
  root.add(groundGlow, groundRing);

  root.scale.setScalar((SCALE[type] || 1) * VIEW_SCALE);
  return { root, tilt, body, gear, spark, height: r * 2, groundRing, groundGlow };
}

/** Arcing shell: a little brass rocket with a plastic nose, or a bouncy ball for the catapult. */
export function buildShell(team, kind = 'rocket') {
  shared();
  const g = new THREE.Group();
  if (kind === 'bouncy') {
    const ball = new THREE.Mesh(geo.ball, teamMat(team));
    ball.scale.setScalar(1.15);
    g.add(ball);
    return g;
  }
  const tube = new THREE.Mesh(geo.tube, mat.brass);
  tube.scale.set(0.9, 0.6, 0.9);
  tube.rotation.z = Math.PI / 2;
  const nose = new THREE.Mesh(geo.tooth, mat[team]);
  nose.rotation.z = -Math.PI / 2;
  nose.position.x = 0.42;
  g.add(tube, nose);
  return g;
}

/** Player-built fortification: dowel barricade, caltrop jack pile, or rubber-band turret. */
export function buildStructure(type, team) {
  shared();
  const g = new THREE.Group();
  const color = teamMat(team);
  if (type === 'barricade') {
    for (const [ox, y] of [[-0.45, 0.42], [0.45, 0.42], [0, 1.08]]) {
      const log = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.4, 2.8, 7), mat.wood);
      log.rotation.z = Math.PI / 2;
      log.position.set(0, y, ox);
      log.castShadow = true;
      g.add(log);
    }
    for (const ox of [-0.95, 0.95]) {
      const band = new THREE.Mesh(new THREE.TorusGeometry(0.46, 0.07, 4, 10), mat.brass);
      band.scale.set(1, 1.3, 1);
      band.position.set(ox, 0.72, 0);
      g.add(band);
    }
  } else if (type === 'caltrop') {
    for (let i = 0; i < 5; i++) {
      const j = new THREE.Mesh(geo.jack, i % 2 ? mat.brass : mat.darkWood);
      const a = (i / 5) * Math.PI * 2;
      j.position.set(Math.cos(a) * 0.65, 0.22, Math.sin(a) * 0.65);
      j.rotation.set(a, a * 1.7, 0);
      g.add(j);
    }
    const ring = new THREE.Mesh(geo.ring, new THREE.MeshBasicMaterial({ color: 0xd4a73a, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.03;
    ring.scale.setScalar(1.4);
    noOutline(ring);
    g.add(ring);
  } else if (type === 'turret') {
    const base = new THREE.Mesh(geo.gear, mat.wood);
    base.scale.set(0.8, 1.2, 0.8);
    base.position.y = 0.35;
    const post = new THREE.Mesh(geo.dowel, mat.darkWood);
    post.scale.set(1, 1.2, 1);
    post.position.y = 1.1;
    const head = new THREE.Group();
    const barrel = new THREE.Mesh(geo.barrel, mat.brass);
    barrel.rotation.z = -Math.PI / 2;
    barrel.position.x = 0.45;
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.05, 4, 10), color);
    band.position.set(0.45, 0, 0);
    band.rotation.y = Math.PI / 2;
    head.add(barrel, band);
    head.position.y = 1.85;
    head.name = 'turretHead';
    g.add(base, post, head);
  }
  return g;
}

/** Ground ring used for the rally flag and selection pings. */
export function buildRing(color) {
  shared();
  const m = new THREE.Mesh(geo.rallyRing, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false }));
  m.rotation.x = -Math.PI / 2;
  noOutline(m);
  return m;
}

export function sharedGeo() { shared(); return geo; }
