import * as THREE from 'three';

const WARN_TIME = 1.5;
const MAX_WARN = 1.65;
const FIRE_PAD = 0.06;
const TONE_GAP = 0.85;

export class HazardDirector {
  constructor({ scene, arena, hud, audio, fx }) {
    this.scene = scene;
    this.arena = arena;
    this.hud = hud;
    this.audio = audio;
    this.fx = fx;
    this.group = new THREE.Group();
    this.group.name = 'hazard-telegraphs';
    scene.add(this.group);
    this.warnings = new Map();
    this.time = 0;
    this.toneCd = 0;
    this.lastCallout = { name: '', at: -99 };
  }

  reset() {
    for (const w of this.warnings.values()) this._dispose(w);
    this.warnings.clear();
    this.time = 0;
    this.toneCd = 0;
    this.lastCallout = { name: '', at: -99 };
  }

  warn(spec) {
    if (!spec || !this.arena?.hazardsActive) return null;
    const id = spec.id || spec.name;
    if (!id) return null;
    const existing = this.warnings.get(id);
    if (existing) return existing;

    const base = spec.duration ?? WARN_TIME;
    const duration = Math.max(0.2, Math.min(MAX_WARN, base + (spec.auto === false ? 0 : FIRE_PAD)));
    const w = {
      id,
      spec: { ...spec, duration },
      age: 0,
      inside: new Set(),
      group: null,
      materials: [],
    };
    this._build(w);
    this.warnings.set(id, w);
    if (this.toneCd <= 0) {
      this.toneCd = TONE_GAP;
      this.audio?.playHazardWarn?.();
    }
    return w;
  }

  fire(spec) {
    const id = spec?.id;
    const w = id ? this.warnings.get(id) : null;
    const name = spec?.name || w?.spec?.name;
    this._callout(name);
    if (w) {
      this._awardDodges(w);
      this._dispose(w);
      this.warnings.delete(id);
    }
  }

  hit(dweeb, name, id) {
    if (dweeb) dweeb.lastHazard = { name, time: this.time };
    this.fire({ id, name });
  }

  update(dt, dweebs = []) {
    this.time += dt;
    this.toneCd = Math.max(0, this.toneCd - dt);
    if (this.arena?.hazardsActive) this._predict(dweebs);

    for (const [id, w] of [...this.warnings]) {
      w.age += dt;
      const t = Math.min(1, w.age / w.spec.duration);
      const grow = 0.38 + 0.62 * t;
      const pulse = 0.5 + 0.5 * Math.sin(this.time * 24);
      if (w.spec.shape === 'rect') {
        w.group.scale.set((w.spec.hw || 1) * grow, 1, (w.spec.hd || 1) * grow);
      } else if (w.spec.shape === 'sector') {
        w.group.scale.set(grow, 1, grow);
      } else {
        const r = (w.spec.r || 1) * grow;
        w.group.scale.set(r, 1, r);
      }
      for (const m of w.materials) {
        m.opacity = m.userData.base * (0.62 + 0.38 * pulse) * (0.55 + 0.45 * t);
      }

      for (const d of dweebs) {
        if (!d.active || d.eliminated) continue;
        if (this._contains(w.spec, d.getPosition())) w.inside.add(d);
      }

      if (w.spec.auto !== false && w.age >= w.spec.duration) this.fire({ id, name: w.spec.name });
    }
  }

  _callout(name) {
    if (!name) return;
    if (this.lastCallout.name === name && this.time - this.lastCallout.at < 0.8) return;
    this.lastCallout = { name, at: this.time };
    this.hud?.hazardCallout?.(name);
  }

  _awardDodges(w) {
    for (const d of w.inside) {
      if (!d.active || d.eliminated) continue;
      if (this._contains(w.spec, d.getPosition())) continue;
      this.hud?.popup?.('DODGED!', d.getPosition(), 'small', 0xffd23f);
      if (d.isPlayer) this.audio?.playDodge?.();
    }
  }

  _build(w) {
    const spec = w.spec;
    const g = new THREE.Group();
    const color = spec.color ?? 0xffd23f;
    const fillMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    fillMat.userData.base = 0.22;
    let geo;
    if (spec.shape === 'sector') {
      geo = new THREE.RingGeometry(spec.r0 ?? 11, spec.r1 ?? 16, 20, 1, spec.a0 ?? 0, (spec.a1 ?? Math.PI * 2) - (spec.a0 ?? 0));
    } else if (spec.shape === 'rect' || spec.shape === 'line') {
      geo = new THREE.PlaneGeometry(2, 2);
    } else {
      geo = new THREE.CircleGeometry(1, 32);
    }
    geo.rotateX(-Math.PI / 2);
    const fill = new THREE.Mesh(geo, fillMat);
    fill.renderOrder = 2;
    g.add(fill);
    w.materials.push(fillMat);

    const edgeMat = new THREE.LineBasicMaterial({
      color,
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
    });
    edgeMat.userData.base = 0.9;
    let edge;
    if (spec.shape === 'rect' || spec.shape === 'line') {
      const pts = [
        new THREE.Vector3(-1, 0, -1), new THREE.Vector3(1, 0, -1),
        new THREE.Vector3(1, 0, 1), new THREE.Vector3(-1, 0, 1),
      ];
      edge = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), edgeMat);
      g.scale.set(spec.hw || 1, 1, spec.hd || 1);
    } else if (spec.shape === 'sector') {
      const pts = this._sectorOutline(spec);
      edge = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), edgeMat);
    } else {
      const ring = new THREE.RingGeometry(0.9, 1, 32);
      ring.rotateX(-Math.PI / 2);
      edge = new THREE.Mesh(ring, new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.8,
        depthWrite: false,
        side: THREE.DoubleSide,
      }));
      edge.material.userData.base = 0.8;
      w.materials.push(edge.material);
      g.scale.set(spec.r || 1, 1, spec.r || 1);
    }
    edge.renderOrder = 3;
    g.add(edge);
    g.position.set(spec.x || 0, spec.y ?? 0.04, spec.z || 0);
    g.rotation.y = spec.angle || 0;
    w.group = g;
    this.group.add(g);
  }

  _sectorOutline(spec) {
    const pts = [];
    const r0 = spec.r0 ?? 11;
    const r1 = spec.r1 ?? 16;
    const a0 = spec.a0 ?? 0;
    const a1 = spec.a1 ?? Math.PI * 2;
    for (let i = 0; i <= 12; i++) {
      const a = a0 + (a1 - a0) * (i / 12);
      pts.push(new THREE.Vector3(Math.cos(a) * r1, 0, -Math.sin(a) * r1));
    }
    for (let i = 12; i >= 0; i--) {
      const a = a0 + (a1 - a0) * (i / 12);
      pts.push(new THREE.Vector3(Math.cos(a) * r0, 0, -Math.sin(a) * r0));
    }
    return pts;
  }

  _dispose(w) {
    if (!w.group) return;
    this.group.remove(w.group);
    w.group.traverse(o => {
      o.geometry?.dispose?.();
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) m?.dispose?.();
    });
    w.group = null;
    w.materials = [];
  }

  _contains(spec, p) {
    const dx = p.x - (spec.x || 0);
    const dz = p.z - (spec.z || 0);
    if (spec.shape === 'sector') {
      const r = Math.hypot(dx, dz);
      if (r < (spec.r0 ?? 11) || r > (spec.r1 ?? 16)) return false;
      let a = Math.atan2(-dz, dx);
      if (a < 0) a += Math.PI * 2;
      const a0 = spec.a0 ?? 0;
      const a1 = spec.a1 ?? Math.PI * 2;
      return a >= a0 && a <= a1;
    }
    if (spec.shape === 'rect' || spec.shape === 'line') {
      const ang = spec.angle || 0;
      const c = Math.cos(ang), s = Math.sin(ang);
      const lx = dx * c - dz * s;
      const lz = dx * s + dz * c;
      return Math.abs(lx) <= (spec.hw || 1) && Math.abs(lz) <= (spec.hd || 1);
    }
    return Math.hypot(dx, dz) <= (spec.r || 1);
  }

  _predict(dweebs) {
    const alive = dweebs.filter(d => d.active && !d.eliminated);
    if (!alive.length) return;
    const arena = this.arena;

    for (let i = 0; i < (arena.spinners?.length || 0); i++) {
      const s = arena.spinners[i];
      const omega = s.speed * (arena.suddenDeath ? 1.6 : 1);
      let best = null;
      for (const d of alive) {
        const p = d.getPosition();
        if (p.y > 1.3 || p.y < 0) continue;
        const t = this._spinnerHitT(p, s.angle, omega, s.half);
        if (t != null && t > 0.05 && (!best || t < best)) best = t;
      }
      if (best != null) {
        const angle = s.angle + omega * best;
        this.warn({
          id: `spinner:${i}`,
          name: s.name || 'TURNTABLE OF DOOM',
          shape: 'rect', x: 0, z: 0, hw: s.half, hd: 0.65, angle,
          duration: Math.max(0.25, best), color: 0xff4d5e,
        });
      }
    }

    for (let i = 0; i < (arena.pendulums?.length || 0); i++) {
      const pend = arena.pendulums[i];
      let best = null;
      for (const d of alive) {
        const p = d.getPosition();
        const hit = this._pendulumHit(p, pend);
        if (hit && hit.t > 0.05 && (!best || hit.t < best.t)) best = hit;
      }
      if (best) {
        this.warn({
          id: `pendulum:${i}`,
          name: pend.name || 'WRECKING CUBE',
          shape: 'circle', x: best.x, z: best.z, r: 1.45,
          duration: Math.max(0.25, best.t), color: 0xff9a3c,
        });
      }
    }

    for (let i = 0; i < (arena.megaPinwheels?.length || 0); i++) {
      const pw = arena.megaPinwheels[i];
      let best = null;
      for (const d of alive) {
        const p = d.getPosition();
        if (p.y > 1.2 || p.y < -0.2) continue;
        const v = d.body?.linvel?.() || { x: 0, z: 0 };
        const t = this._timeToCircle(p, v, pw.x, pw.z, pw.radius);
        if (t != null && t > 0.05 && t <= WARN_TIME && (!best || t < best)) best = t;
      }
      if (best != null) {
        this.warn({
          id: `mega:${i}`,
          name: pw.name || 'OBSTACLE PINWHEEL',
          shape: 'circle', x: pw.x, z: pw.z, r: pw.radius,
          duration: Math.max(0.25, best), color: 0xff4d8d,
        });
      }
    }

    for (let i = 0; i < (arena.bumpers?.length || 0); i++) {
      const b = arena.bumpers[i];
      let best = null;
      for (const d of alive) {
        const p = d.getPosition();
        if (p.y > 1.8) continue;
        const v = d.body?.linvel?.() || { x: 0, z: 0 };
        const t = this._timeToCircle(p, v, b.x, b.z, 1.2);
        if (t != null && t > 0.05 && t <= WARN_TIME && (!best || t < best)) best = t;
      }
      if (best != null) {
        this.warn({
          id: `bumper:${i}`,
          name: b.name || 'PINBALL BUMPER',
          shape: 'circle', x: b.x, z: b.z, r: 1.2,
          duration: Math.max(0.25, best), color: b.color ?? 0xffd23f,
        });
      }
    }

    const lava = arena.lava;
    if (lava && !arena.suddenDeath) {
      let best = null, bx = 0, bz = 0;
      for (const d of alive) {
        const p = d.getPosition();
        if (arena.isOverGround?.(p.x, p.z, 0.2)) continue;
        const surface = lava.y + 0.45;
        if (p.y <= surface) continue;
        const v = d.body?.linvel?.() || { x: 0, y: 0, z: 0 };
        const t = this._timeToLava(p, v, surface);
        if (t != null && t > 0.05 && t <= WARN_TIME && (!best || t < best)) {
          best = t;
          bx = p.x;
          bz = p.z;
        }
      }
      if (best != null) {
        this.warn({
          id: 'lava', name: 'RISING LAVA',
          shape: 'circle', x: bx, z: bz, r: 1.2,
          duration: Math.max(0.25, best), color: 0xff6b2c,
        });
      }
    }

    for (let i = 0; i < (arena.contraptions?.length || 0); i++) {
      const c = arena.contraptions[i];
      const id = `contraption:${c.type}:${i}`;
      const name = c.name || this._contraptionName(c.type);
      if (c.type === 'stomper') {
        if (c.state !== 'wait' || c.timer <= 0 || c.timer > WARN_TIME) continue;
        const near = alive.some(d => {
          const p = d.getPosition();
          return Math.hypot(p.x, p.z) < 2.0 && p.y < 1.8;
        });
        if (near) {
          this.warn({ id, name, shape: 'circle', x: 0, z: 0, r: 2.0, duration: c.timer, color: 0xff4d5e });
        }
      } else if (c.type === 'spikedLog') {
        let best = null;
        for (const d of alive) {
          const p = d.getPosition();
          if (p.y >= 2) continue;
          const hit = this._spikedLogHit(p, c);
          if (hit && hit.t > 0.05 && (!best || hit.t < best.t)) best = hit;
        }
        if (best) {
          this.warn({
            id, name, shape: 'rect', x: 0, z: best.z, hw: 4, hd: 0.9,
            duration: Math.max(0.25, best.t), color: 0xff9a3c,
          });
        }
      } else if (c.type === 'wreckingLog') {
        let best = null;
        for (const d of alive) {
          const p = d.getPosition();
          const hit = this._wreckingLogHit(p, c);
          if (hit && hit.t > 0.05 && (!best || hit.t < best.t)) best = hit;
        }
        if (best) {
          this.warn({
            id, name, shape: 'circle', x: best.x, z: best.z, r: 1.6,
            duration: Math.max(0.25, best.t), color: 0xff9a3c,
          });
        }
      } else if (c.type === 'laserBar') {
        let best = null;
        for (const d of alive) {
          const p = d.getPosition();
          const hit = this._laserHit(p, c);
          if (hit && hit.t > 0.05 && (!best || hit.t < best.t)) best = hit;
        }
        if (best) {
          this.warn({
            id, name, shape: 'rect', x: c.x, z: c.z, hw: c.length / 2, hd: 0.8,
            angle: -best.angle, duration: Math.max(0.25, best.t), color: 0xff1053,
          });
        }
      } else if (c.type === 'shredder') {
        const cx = c.side * 2.2, cz = 6.5;
        let best = null;
        for (const d of alive) {
          const p = d.getPosition();
          if (p.y > 1.8) continue;
          const v = d.body?.linvel?.() || { x: 0, z: 0 };
          const t = this._timeToCircle(p, v, cx, cz, 1.5);
          if (t != null && t > 0.05 && t <= WARN_TIME && (!best || t < best)) best = t;
        }
        if (best != null) {
          this.warn({
            id, name, shape: 'circle', x: cx, z: cz, r: 1.5,
            duration: Math.max(0.25, best), color: 0xff4d5e,
          });
        }
      } else if (c.type === 'catapult') {
        let best = null;
        for (const d of alive) {
          const p = d.getPosition();
          if (p.y > 1.0) continue;
          const v = d.body?.linvel?.() || { x: 0, z: 0 };
          const t = this._timeToCircle(p, v, c.x, c.z, 1.4);
          if (t != null && t > 0.05 && t <= WARN_TIME && (!best || t < best)) best = t;
        }
        if (best != null) {
          this.warn({
            id, name, shape: 'circle', x: c.x, z: c.z, r: 1.4,
            duration: Math.max(0.25, best), color: 0xffd23f,
          });
        }
      }
    }
  }

  _spinnerHitT(p, angle, omega, half) {
    for (let t = 0; t <= WARN_TIME + 1e-6; t += 0.04) {
      const a = angle + omega * t;
      const c = Math.cos(a), s = Math.sin(a);
      const lx = p.x * c - p.z * s;
      const lz = p.x * s + p.z * c;
      if (Math.abs(lx) < half && Math.abs(lz) < 0.65) return t;
    }
    return null;
  }

  _pendulumHit(p, pend) {
    for (let t = 0; t <= WARN_TIME + 1e-6; t += 0.04) {
      const phase = pend.phase + pend.speed * t;
      const a = Math.sin(phase) * pend.amp;
      const x = pend.anchor.x;
      const y = pend.anchor.y - Math.cos(a) * pend.cordLength;
      const z = pend.anchor.z + Math.sin(a) * pend.cordLength;
      if (Math.hypot(p.x - x, p.y - y, p.z - z) > 1.45) continue;
      const a2 = Math.sin(phase + 0.03) * pend.amp;
      const z2 = pend.anchor.z + Math.sin(a2) * pend.cordLength;
      const speed = Math.abs(z2 - z) / 0.03;
      if (speed >= 3) return { t, x, z };
    }
    return null;
  }

  _spikedLogHit(p, c) {
    for (let t = 0; t <= WARN_TIME + 1e-6; t += 0.04) {
      const z = Math.sin(c.sweepPhase + 1.2 * t) * 3.5;
      if (Math.abs(p.x) < 4 && Math.abs(p.z - z) < 0.9 && p.y < 2) return { t, z };
    }
    return null;
  }

  _wreckingLogHit(p, c) {
    for (let t = 0; t <= WARN_TIME + 1e-6; t += 0.04) {
      const phase = c.phase + c.speed * t;
      const x = c.baseX;
      const y = 3 + Math.cos(phase) * 1.5;
      const z = Math.sin(phase) * 5;
      if (Math.hypot(p.x - x, p.y - y, p.z - z) < 1.6) return { t, x, z };
    }
    return null;
  }

  _laserHit(p, c) {
    const half = c.length / 2;
    for (let t = 0; t <= WARN_TIME + 1e-6; t += 0.04) {
      const a = c.angle + c.spinSpeed * t;
      const dx = p.x - c.x, dz = p.z - c.z;
      const dirX = Math.cos(a), dirZ = Math.sin(a);
      const proj = Math.max(-half, Math.min(half, dx * dirX + dz * dirZ));
      const cx = c.x + dirX * proj, cz = c.z + dirZ * proj;
      if (Math.hypot(p.x - cx, p.z - cz) < 0.8 && Math.abs(p.y - c.y) < 1.0) return { t, angle: a };
    }
    return null;
  }

  _timeToLava(p, v, surface) {
    const g = 20 * (this.arena?.physicsWorld?.gravityScale || 1);
    let y = p.y, vy = v.y || 0;
    const step = 0.04;
    for (let t = step; t <= WARN_TIME + 1e-6; t += step) {
      vy -= g * step;
      y += vy * step;
      if (y <= surface) return t;
    }
    return null;
  }

  _timeToCircle(p, v, cx, cz, r) {
    const dx = p.x - cx, dz = p.z - cz;
    const c = dx * dx + dz * dz - r * r;
    if (c <= 0) return 0;
    const a = (v.x || 0) * (v.x || 0) + (v.z || 0) * (v.z || 0);
    if (a < 1e-4) return null;
    const b = 2 * (dx * (v.x || 0) + dz * (v.z || 0));
    const disc = b * b - 4 * a * c;
    if (disc < 0) return null;
    const t = (-b - Math.sqrt(disc)) / (2 * a);
    return t >= 0 ? t : null;
  }

  _contraptionName(type) {
    return {
      stomper: 'HYDRAULIC TENDERIZER',
      catapult: 'SUPERSONIC CATAPULT',
      shredder: 'INDUSTRIAL SHREDDER',
      spikedLog: 'SPIKED LOG ROLLER',
      wreckingLog: 'WRECKING LOG',
      laserBar: 'ROTATING LASER GRID',
    }[type] || 'STAGE HAZARD';
  }
}
