// game-switcher.js — live stats + shortcuts for the in-game game switcher.
//
// The modal markup lives in index.html because main.js opens/closes it. This
// module only *reads* localStorage and paints the stat chips, so the switcher
// stays instant even when the shell is hidden behind a running match.

/* global document, localStorage, MutationObserver */

const BRAWLER_KEY = 'dweebs-brawler-stats';
const VILLAGE_KEY = 'dweebs-village-v1';
const BUILDER_KEY = 'dweebs-custom-build';
const WARFARE_KEY = 'dweebs-warfare-best';

function readJson(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function readNumber(key) {
  try { return Number(localStorage.getItem(key)) || 0; } catch { return 0; }
}

/** Snapshot of everything the switcher can honestly show from this device. */
export function readGameStats() {
  const brawler = readJson(BRAWLER_KEY) || {};
  const village = readJson(VILLAGE_KEY);
  const build = readJson(BUILDER_KEY);
  const bestNormal = readNumber(WARFARE_KEY);
  const bestEasy = readNumber('dweebs-warfare-best-easy');
  const bestHard = readNumber('dweebs-warfare-best-hard');
  return {
    brawler: {
      wins: Number(brawler.wins) || 0,
      played: Number(brawler.played) || 0,
    },
    dynasty: {
      name: village?.colony?.name || '',
      citizens: Array.isArray(village?.colony?.citizens) ? village.colony.citizens.length : 0,
      generation: Number(village?.colony?.generation) || 1,
      structures: Array.isArray(village?.structures) ? village.structures.length : 0,
    },
    warfare: {
      best: Math.max(bestNormal, bestEasy, bestHard),
      normal: bestNormal,
      easy: bestEasy,
      hard: bestHard,
    },
    builder: {
      name: typeof build?.name === 'string' ? build.name : '',
    },
  };
}

function statText(stats) {
  const b = stats.brawler;
  const d = stats.dynasty;
  const w = stats.warfare;
  const c = stats.builder;
  return {
    brawler: b.played
      ? `${b.wins} win${b.wins === 1 ? '' : 's'} · ${b.played} match${b.played === 1 ? '' : 'es'}`
      : 'No matches yet — set a record',
    dynasty: d.citizens
      ? `${d.citizens} citizen${d.citizens === 1 ? '' : 's'} · Gen ${d.generation} · ${d.structures} build${d.structures === 1 ? '' : 's'}`
      : 'No colony saved yet',
    warfare: w.best
      ? `Best defense: wave ${w.best} / 20`
      : 'No fort defense yet',
    builder: c.name
      ? `Saved creature: ${c.name}`
      : 'No creature saved yet',
  };
}

function paint(root, text) {
  if (!root) return;
  for (const node of root.querySelectorAll('[data-gs-stat]')) {
    const key = node.dataset.gsStat;
    if (text[key]) node.textContent = text[key];
  }
  for (const node of root.querySelectorAll('[data-mall-stat]')) {
    const key = node.dataset.mallStat;
    if (text[key]) node.textContent = text[key];
  }
}

/** Keep a tiny local brawler record so the switcher has a real high score to show. */
function installResultTracker(onChange) {
  const results = document.getElementById('results-screen');
  if (!results) return;
  let visible = !results.classList.contains('hidden');

  new MutationObserver(() => {
    const now = !results.classList.contains('hidden');
    if (now && !visible) {
      // Build-A-Dweeb hides PLAY AGAIN on its results screen; that is not a
      // player brawler match, so don't count it.
      const replay = document.getElementById('btn-play-again');
      if (replay && !replay.classList.contains('hidden')) {
        const title = (document.getElementById('result-title')?.textContent || '').trim();
        const data = readJson(BRAWLER_KEY) || {};
        data.played = (Number(data.played) || 0) + 1;
        if (/^YOU WIN/i.test(title)) data.wins = (Number(data.wins) || 0) + 1;
        try { localStorage.setItem(BRAWLER_KEY, JSON.stringify(data)); } catch { /* private mode */ }
        onChange();
      }
    }
    visible = now;
  }).observe(results, { attributes: true, attributeFilter: ['class'] });
}

export function initGameSwitcher() {
  const modal = document.getElementById('game-switcher-modal');
  const mall = document.getElementById('app-title');
  const paintAll = () => {
    const text = statText(readGameStats());
    paint(modal, text);
    paint(mall, text);
  };

  paintAll();
  installResultTracker(paintAll);

  if (mall) {
    new MutationObserver(() => {
      if (!mall.classList.contains('hidden')) paintAll();
    }).observe(mall, { attributes: true, attributeFilter: ['class'] });
  }
  if (modal) {
    new MutationObserver(() => {
      if (!modal.classList.contains('hidden')) paintAll();
    }).observe(modal, { attributes: true, attributeFilter: ['class'] });

    // Escape closes; 1–4 launch that card's primary game instantly.
    modal.addEventListener('keydown', e => {
      if (e.code === 'Escape') {
        e.preventDefault();
        document.getElementById('btn-close-switcher')?.click();
        return;
      }
      const digit = /^(?:Digit|Numpad)([1-4])$/.exec(e.code);
      if (digit) {
        const card = modal.querySelectorAll('.gs-card')[Number(digit[1]) - 1];
        const button = card?.querySelector('.switcher-btn');
        if (button) {
          e.preventDefault();
          button.click();
        }
      }
    });
  }
}
