// src/sim/warfareStructures.js — Dweeb Warfare fortifications. Pure data + placement rules.
//
// Between waves the defender spends battle gold on toys that make the fort feel like a fort:
//   barricade — a dowel wall units must chew through
//   caltrop   — scattered jacks that slow and prick anyone crossing
//   turret    — a rubber-band tower that auto-fires at the nearest enemy
//
// Structures live in the deterministic sim (state.structures) so online peers agree on them.

export const MAX_STRUCTURES = 10;

export const STRUCTURE_TYPES = Object.freeze({
  barricade: {
    name: 'Barricade', icon: '🧱', cost: 20, hp: 240, radius: 1.25,
    blurb: 'Dowel wall. Blocks the lane; enemies chew through it.',
  },
  caltrop: {
    name: 'Caltrops', icon: '⚙️', cost: 15, hp: 80, radius: 1.4,
    blurb: 'Scattered jacks. Slows and pricks anyone crossing.',
    dmg: 16, cooldown: 26, slowTicks: 45, charges: 8,
  },
  turret: {
    name: 'Turret', icon: '🔫', cost: 45, hp: 170, radius: 0.9,
    blurb: 'Rubber-band turret. Auto-fires at the nearest enemy.',
    range: 16, dmg: 26, cooldown: 42,
  },
});

export const BUILDABLE = Object.freeze(['barricade', 'caltrop', 'turret']);

export function structureStats(type) {
  const s = STRUCTURE_TYPES[type];
  if (!s) throw new Error(`unknown warfare structure: ${type}`);
  return s;
}

/** Repair price for a structure: proportional to the HP missing, with a small call-out fee. */
export function repairCost(s) {
  const def = structureStats(s.type);
  const missing = Math.max(0, s.maxHp - s.hp) / s.maxHp;
  if (missing <= 0) return 0;
  return Math.max(5, Math.ceil(def.cost * missing * 0.6));
}
