// SkateBotAi.js — Autonomous Dweeb bots in the Skatepark FFA Arena.
//
// Features:
// - Yellow Cube and Red Spiky Virus 3D models with cute googly eyes and mini toy blasters
// - Speed-rolling in ball mode on ramps, flying off launch pads
// - Spring-into-action combat mode when engaging enemies
// - Shooting yellow laser tracers, taking damage, and respawning

import * as THREE from 'three';

const BOT_PRESETS = [
  { name: 'SWAG_CUBE', type: 'cube', color: 0xffea00 },
  { name: 'SPIKEY_RED', type: 'virus', color: 0xff2b4b },
  { name: 'SLIDE_BOI', type: 'cube', color: 0x00e676 },
  { name: 'GLOOP_BLOB', type: 'cube', color: 0x2979ff },
  { name: 'VIRUS_PRIME', type: 'virus', color: 0xff1744 },
  { name: 'BONK_CUBE', type: 'cube', color: 0xff9100 },
];

export class SkateBotManager {
  constructor({ scene, arena, audio, hud, onBotKill }) {
    this.scene = scene;
    this.arena = arena;
    this.audio = audio;
    this.hud = hud;
    this.onBotKill = onBotKill;
    this.bots = [];

    this._spawnBots();
  }

  _spawnBots() {
    BOT_PRESETS.forEach((preset, idx) => {
      const sp = this.arena.spawnPoints[(idx + 1) % this.arena.spawnPoints.length].clone();
      const bot = new SkateBot({
        scene: this.scene,
        arena: this.arena,
        audio: this.audio,
        hud: this.hud,
        preset,
        startPos: sp,
        slot: idx + 10,
        onKill: (killer, victim) => this.onBotKill?.(killer, victim),
      });
      this.bots.push(bot);
    });
  }

  update(dt, playerPos, onPlayerDamaged) {
    for (const bot of this.bots) {
      bot.update(dt, playerPos, this.bots, onPlayerDamaged);
    }
  }

  getEntities() {
    return this.bots.map(b => ({
      x: b.pos.x,
      z: b.pos.z,
      name: b.name,
      isBot: true,
      alive: b.alive,
    }));
  }

  checkBulletHit(origin, dir, maxDist = 80) {
    const ray = new THREE.Ray(origin, dir);
    let closestHit = null;
    let closestDist = maxDist;

    for (const bot of this.bots) {
      if (!bot.alive) continue;
      const sphere = new THREE.Sphere(bot.pos.clone().add(new THREE.Vector3(0, 0.8, 0)), 1.2);
      const hitPoint = new THREE.Vector3();
      if (ray.intersectSphere(sphere, hitPoint)) {
        const d = origin.distanceTo(hitPoint);
        if (d < closestDist) {
          closestDist = d;
          closestHit = { bot, hitPoint };
        }
      }
    }
    return closestHit;
  }

  dispose() {
    for (const bot of this.bots) bot.dispose();
    this.bots = [];
  }
}

class SkateBot {
  constructor({ scene, arena, audio, hud, preset, startPos, slot, onKill }) {
    this.scene = scene;
    this.arena = arena;
    this.audio = audio;
    this.hud = hud;
    this.name = preset.name;
    this.type = preset.type;
    this.color = preset.color;
    this.slot = slot;
    this.onKill = onKill;

    this.pos = startPos.clone();
    this.vel = new THREE.Vector3();
    this.yaw = Math.random() * Math.PI * 2;
    this.mode = 'ball'; // Starts rolling
    this.health = 100;
    this.shield = 100;
    this.alive = true;
    this.lastShootTime = 0;
    this.nextStateChange = 2 + Math.random() * 3;

    this._buildMesh();
  }

  _buildMesh() {
    this.group = new THREE.Group();
    this.group.name = `Bot_${this.name}`;

    // ── Ball Mode Mesh ──
    const ballGeo = new THREE.SphereGeometry(0.7, 14, 14);
    const ballMat = new THREE.MeshStandardMaterial({ color: this.color, roughness: 0.5 });
    this.ballMesh = new THREE.Mesh(ballGeo, ballMat);
    this.ballMesh.castShadow = true;
    this.group.add(this.ballMesh);

    // ── Standing Combat Mesh ──
    this.combatGroup = new THREE.Group();
    if (this.type === 'cube') {
      // Chamfered Cube Dweeb with little feet and hands
      const cubeGeo = new THREE.BoxGeometry(1.2, 1.2, 1.2);
      const cubeMat = new THREE.MeshStandardMaterial({ color: this.color, roughness: 0.4 });
      const cubeMesh = new THREE.Mesh(cubeGeo, cubeMat);
      cubeMesh.position.y = 0.8;
      cubeMesh.castShadow = true;
      this.combatGroup.add(cubeMesh);

      // Cute Eyes
      const eyeGeo = new THREE.SphereGeometry(0.18, 8, 8);
      const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
      const pupMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
      const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
      eyeL.position.set(-0.3, 0.95, 0.6);
      const pupL = new THREE.Mesh(new THREE.SphereGeometry(0.08, 6, 6), pupMat);
      pupL.position.set(0, 0, 0.12);
      eyeL.add(pupL);
      this.combatGroup.add(eyeL);

      const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
      eyeR.position.set(0.3, 0.95, 0.6);
      const pupR = new THREE.Mesh(new THREE.SphereGeometry(0.08, 6, 6), pupMat);
      pupR.position.set(0, 0, 0.12);
      eyeR.add(pupR);
      this.combatGroup.add(eyeR);

      // Mini Blaster
      const gunGeo = new THREE.BoxGeometry(0.18, 0.18, 0.5);
      const gunMat = new THREE.MeshStandardMaterial({ color: 0x00d2ff, roughness: 0.3 });
      const gunMesh = new THREE.Mesh(gunGeo, gunMat);
      gunMesh.position.set(0.65, 0.75, 0.4);
      this.combatGroup.add(gunMesh);
    } else {
      // Red Spiky Virus Dweeb
      const coreGeo = new THREE.SphereGeometry(0.75, 12, 12);
      const coreMat = new THREE.MeshStandardMaterial({ color: this.color, roughness: 0.6 });
      const coreMesh = new THREE.Mesh(coreGeo, coreMat);
      coreMesh.position.y = 0.8;
      this.combatGroup.add(coreMesh);

      // Tentacles / Spikes
      const spikeGeo = new THREE.ConeGeometry(0.14, 0.5, 6);
      const spikeMat = new THREE.MeshStandardMaterial({ color: 0xd50000 });
      for (let s = 0; s < 18; s++) {
        const spike = new THREE.Mesh(spikeGeo, spikeMat);
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI;
        spike.position.set(
          Math.cos(theta) * Math.cos(phi) * 0.75,
          0.8 + Math.sin(phi) * 0.75,
          Math.sin(theta) * Math.cos(phi) * 0.75
        );
        spike.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), spike.position.clone().sub(new THREE.Vector3(0, 0.8, 0)).normalize());
        this.combatGroup.add(spike);
      }

      // Startled Googly Eyes
      const eyeGeo = new THREE.SphereGeometry(0.22, 8, 8);
      const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
      const pupMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
      const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
      eyeL.position.set(-0.3, 0.95, 0.65);
      const pupL = new THREE.Mesh(new THREE.SphereGeometry(0.1, 6, 6), pupMat);
      pupL.position.set(0, 0, 0.16);
      eyeL.add(pupL);
      this.combatGroup.add(eyeL);

      const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
      eyeR.position.set(0.3, 0.95, 0.65);
      const pupR = new THREE.Mesh(new THREE.SphereGeometry(0.1, 6, 6), pupMat);
      pupR.position.set(0, 0, 0.16);
      eyeR.add(pupR);
      this.combatGroup.add(eyeR);
    }

    this.combatGroup.visible = false;
    this.group.add(this.combatGroup);
    this.group.position.copy(this.pos);
    this.scene.add(this.group);
  }

  takeDamage(amount, killerName = 'YOU') {
    if (!this.alive) return;
    if (this.shield > 0) {
      this.shield = Math.max(0, this.shield - amount);
    } else {
      this.health = Math.max(0, this.health - amount);
    }

    // Hit reaction squash
    this.group.scale.set(1.3, 0.7, 1.3);

    if (this.health <= 0) {
      this.alive = false;
      this.group.visible = false;
      this.onKill?.(killerName, this.name);
      setTimeout(() => this.respawn(), 3000);
    }
  }

  respawn() {
    this.pos.copy(this.arena.getRandomSpawn());
    this.vel.set(0, 0, 0);
    this.health = 100;
    this.shield = 100;
    this.alive = true;
    this.group.visible = true;
    this.group.position.copy(this.pos);
  }

  update(dt, playerPos, allBots, onPlayerDamaged) {
    if (!this.alive) return;

    // Reset squash scale
    this.group.scale.lerp(new THREE.Vector3(1, 1, 1), dt * 10);

    // AI Decision Timer
    this.nextStateChange -= dt;
    if (this.nextStateChange <= 0) {
      this.nextStateChange = 2.5 + Math.random() * 4;
      // Toggle between high-speed rolling and standing combat
      const distToPlayer = this.pos.distanceTo(playerPos);
      if (distToPlayer < 24 && Math.random() > 0.35) {
        this.mode = 'combat';
      } else {
        this.mode = 'ball';
      }
    }

    const inBall = (this.mode === 'ball');
    this.ballMesh.visible = inBall;
    this.combatGroup.visible = !inBall;

    // Navigation logic
    const distToPlayer = this.pos.distanceTo(playerPos);
    let targetPos = playerPos;

    if (inBall) {
      // Speed roll towards ramps or around arena
      const steerForce = 28.0;
      const toTarget = targetPos.clone().sub(this.pos).normalize();
      this.vel.x += toTarget.x * steerForce * dt;
      this.vel.z += toTarget.z * steerForce * dt;

      // Ball roll mesh rotation
      this.ballMesh.rotation.x += this.vel.z * dt * 2.5;
      this.ballMesh.rotation.z -= this.vel.x * dt * 2.5;
    } else {
      // Combat mode: aim at player or nearest opponent and shoot
      this.yaw = Math.atan2(playerPos.x - this.pos.x, playerPos.z - this.pos.z);
      this.group.rotation.y = this.yaw;

      // Strafe slowly
      const strafeDir = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
      this.vel.x += strafeDir.x * 10.0 * dt;
      this.vel.z += strafeDir.z * 10.0 * dt;

      // Shoot blaster at player if in range and line of sight
      const now = performance.now() / 1000;
      if (distToPlayer < 35 && now - this.lastShootTime > 0.85 + Math.random() * 0.5) {
        this.lastShootTime = now;
        if (Math.random() > 0.4) {
          onPlayerDamaged?.(18, this.pos.x < playerPos.x);
        }
      }
    }

    // Clamp horizontal speed
    const maxSpeed = inBall ? 30.0 : 12.0;
    const hSpeed = Math.sqrt(this.vel.x * this.vel.x + this.vel.z * this.vel.z);
    if (hSpeed > maxSpeed) {
      const s = maxSpeed / hSpeed;
      this.vel.x *= s;
      this.vel.z *= s;
    }

    // Apply friction & gravity
    this.vel.x *= Math.pow(inBall ? 0.985 : 0.88, dt * 60);
    this.vel.z *= Math.pow(inBall ? 0.985 : 0.88, dt * 60);
    this.vel.y -= 30.0 * dt;

    this.pos.addScaledVector(this.vel, dt);

    // Ground clamp
    if (this.pos.y <= 1.0) {
      this.pos.y = 1.0;
      this.vel.y = 0;
    }

    // Ramp slope clamp
    if (this.pos.x > -7 && this.pos.x < 7 && this.pos.z > -38 && this.pos.z < -6) {
      const t = (-6 - this.pos.z) / 32;
      const rampHeight = Math.pow(t, 1.8) * 8 + 1.0;
      if (this.pos.y <= rampHeight) {
        this.pos.y = rampHeight;
        this.vel.y = 0;
      }
    }

    // Arena boundary clamp
    this.pos.x = Math.max(-42, Math.min(42, this.pos.x));
    this.pos.z = Math.max(-56, Math.min(56, this.pos.z));

    this.group.position.copy(this.pos);
  }

  dispose() {
    this.scene.remove(this.group);
  }
}
