// WarfareBoard.js — the toy battlefield: a bevelled plastic play-mat, wooden dowel fences,
// dowel-bundle barricades and brass-geared forts. No voxel terrain anywhere.
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { toonMat, noOutline } from '../render/Toon.js';
import { FIELD, FORT_X, FORT_RADIUS, BARRICADES } from '../sim/warfareBattle.js';
import { TEAM_COLORS, sharedMats } from './WarfareModels.js';

function seeded(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

/** Procedural grass/dirt play-mat texture: mown stripes, mottling, worn patches and fine noise. */
function makeGroundTexture() {
  if (typeof document === 'undefined') return null;
  const size = 256;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const rng = seeded(0x51ab1e);
  ctx.fillStyle = '#86c95f';
  ctx.fillRect(0, 0, size, size);
  for (let x = 0; x < size; x += 32) {
    ctx.fillStyle = (x / 32) % 2 ? 'rgba(255,255,255,0.055)' : 'rgba(25,70,20,0.05)';
    ctx.fillRect(x, 0, 32, size);
  }
  for (let i = 0; i < 180; i++) {
    const x = rng() * size, y = rng() * size;
    const rx = 4 + rng() * 22, ry = 4 + rng() * 16;
    const tone = rng();
    ctx.fillStyle = tone < 0.4 ? 'rgba(111,176,70,0.22)' : tone < 0.75 ? 'rgba(158,210,112,0.16)' : 'rgba(60,120,48,0.15)';
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, rng() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  for (let i = 0; i < 55; i++) {
    const x = rng() * size, y = rng() * size, r = 1.5 + rng() * 7;
    ctx.fillStyle = `rgba(139,98,58,${0.08 + rng() * 0.12})`;
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * (0.45 + rng() * 0.6), rng() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  for (let i = 0; i < 900; i++) {
    const x = rng() * size, y = rng() * size;
    ctx.fillStyle = rng() < 0.5 ? 'rgba(55,105,40,0.22)' : 'rgba(202,236,160,0.22)';
    ctx.fillRect(x, y, 1 + rng() * 1.5, 1 + rng() * 1.5);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 2.4);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

export function buildBoard() {
  const mats = sharedMats();
  const group = new THREE.Group();
  const W = FIELD.halfX * 2 + 4, H = FIELD.halfZ * 2 + 4;

  // Play-mat: bevelled plastic slab, top face at y = 0
  const slab = new THREE.Mesh(
    new THREE.ExtrudeGeometry(roundedRect(W, H, 4), { depth: 1.4, bevelEnabled: true, bevelThickness: 0.35, bevelSize: 0.5, bevelSegments: 1, curveSegments: 3 }),
    toonMat({ color: 0x8fd16a }),
  );
  slab.rotation.x = -Math.PI / 2;
  slab.position.y = -1.75;
  slab.receiveShadow = true;
  group.add(slab);

  const groundTex = makeGroundTexture();
  if (groundTex) {
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(W, H), toonMat({ map: groundTex }));
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = 0.006;
    ground.receiveShadow = true;
    noOutline(ground);
    group.add(ground);
  }

  const paint = (w, h, color, x, z, opacity = 1) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, depthWrite: false }));
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, 0.02, z);
    noOutline(m);
    group.add(m);
    return m;
  };
  // team zones and a dashed midline, like a printed board game
  paint(12, H - 4, 0xcfe9ff, -FIELD.halfX + 6, 0, 0.34);
  paint(12, H - 4, 0xffd9dd, FIELD.halfX - 6, 0, 0.34);
  for (let z = -FIELD.halfZ + 2; z < FIELD.halfZ - 1; z += 3) paint(0.35, 1.6, 0xfff8ee, 0, z + 0.8, 0.8);
  for (const x of [-14, 14]) paint(0.2, H - 6, 0xfff8ee, x, 0, 0.35);

  // Lane guides: faint team-tinted bands with dashes running from each spawn gate to the
  // opposing fort so the player can read where each side's troops will arrive from.
  const arrowGeo = new THREE.BufferGeometry();
  arrowGeo.setAttribute('position', new THREE.Float32BufferAttribute([
    -0.55, -0.34, 0, 0.62, 0, 0, -0.55, 0.34, 0,
  ], 3));
  for (const team of ['blue', 'red']) {
    const gate = FORT_X - FORT_RADIUS - 2;
    const startX = team === 'blue' ? -gate : gate;
    const endX = -startX;
    const laneZ = team === 'blue' ? -1.8 : 1.8;
    const laneLen = Math.abs(endX - startX);
    paint(laneLen, 2.6, TEAM_COLORS[team], (startX + endX) / 2, laneZ, 0.055);
    const dashGeo = new THREE.PlaneGeometry(1.15, 0.34);
    const dashMat = new THREE.MeshBasicMaterial({ color: TEAM_COLORS[team], transparent: true, opacity: 0.34, depthWrite: false });
    const count = Math.round(laneLen / 2.8);
    const dashes = new THREE.InstancedMesh(dashGeo, dashMat, count);
    const d = new THREE.Object3D();
    for (let i = 0; i < count; i++) {
      const x = startX + ((endX - startX) * (i + 0.5)) / count;
      d.position.set(x, 0.032, laneZ);
      d.rotation.set(-Math.PI / 2, 0, 0);
      d.scale.setScalar(1);
      d.updateMatrix();
      dashes.setMatrixAt(i, d.matrix);
    }
    noOutline(dashes);
    group.add(dashes);

    const arrowCount = Math.max(2, Math.round(laneLen / 15));
    const arrowMat = new THREE.MeshBasicMaterial({ color: TEAM_COLORS[team], transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false });
    const arrows = new THREE.InstancedMesh(arrowGeo, arrowMat, arrowCount);
    const dirFlip = endX < startX ? Math.PI : 0;
    for (let i = 0; i < arrowCount; i++) {
      const x = startX + ((endX - startX) * (i + 0.5)) / arrowCount;
      d.position.set(x, 0.034, laneZ);
      d.rotation.set(-Math.PI / 2, 0, dirFlip);
      d.scale.setScalar(1);
      d.updateMatrix();
      arrows.setMatrixAt(i, d.matrix);
    }
    noOutline(arrows);
    group.add(arrows);
  }

  // Field dressing: instanced rocks, grass tufts, broken fences and craters, kept out of the
  // central traffic lanes and fort approaches so they never block a unit's path.
  const rng = seeded(0xbadf00d);
  const blocked = (x, z, pad) => {
    if (Math.abs(z) < 10.5) return true;
    if (Math.abs(x) > FIELD.halfX - 1 || Math.abs(z) > FIELD.halfZ - 1) return true;
    for (const fx of [-FORT_X, FORT_X]) if (Math.hypot(x - fx, z) < FORT_RADIUS + 2.5 + pad) return true;
    for (const b of BARRICADES) if (Math.hypot(x - b.x, z - b.z) < b.r + 1.6 + pad) return true;
    return false;
  };
  const spots = (n, gap, pad) => {
    const out = [];
    let guard = 0;
    while (out.length < n && guard++ < n * 80) {
      const side = rng() < 0.5 ? -1 : 1;
      const x = (rng() * 2 - 1) * (FIELD.halfX - 1.2);
      const z = side * (10.8 + rng() * (FIELD.halfZ - 12));
      if (blocked(x, z, pad)) continue;
      if (out.some(([px, pz]) => Math.hypot(px - x, pz - z) < gap)) continue;
      out.push([x, z]);
    }
    return out;
  };
  const tmp = new THREE.Object3D();

  const rockSpots = spots(34, 2.3, 1.5);
  const rocks = new THREE.InstancedMesh(
    new THREE.DodecahedronGeometry(0.46, 0),
    toonMat({ color: 0x9aa3a8, flatShading: true }),
    rockSpots.length,
  );
  rockSpots.forEach(([x, z], i) => {
    const s = 0.55 + rng() * 0.85;
    tmp.position.set(x, 0.18 * s, z);
    tmp.rotation.set(rng() * 0.5, rng() * Math.PI * 2, rng() * 0.5);
    tmp.scale.set(s * (0.8 + rng() * 0.5), s * (0.55 + rng() * 0.45), s * (0.8 + rng() * 0.5));
    tmp.updateMatrix();
    rocks.setMatrixAt(i, tmp.matrix);
  });
  rocks.castShadow = true;
  rocks.receiveShadow = true;
  noOutline(rocks);
  group.add(rocks);

  const blade = new THREE.ConeGeometry(0.09, 0.5, 4);
  const tuftGeo = mergeGeometries([
    blade.clone().translate(0, 0.25, 0),
    blade.clone().rotateZ(0.32).translate(0.11, 0.2, 0.04),
    blade.clone().rotateZ(-0.28).translate(-0.1, 0.19, -0.05),
  ]);
  const tuftSpots = spots(72, 1.15, 0.4);
  const tufts = new THREE.InstancedMesh(tuftGeo, toonMat({ color: 0xffffff, flatShading: true }), tuftSpots.length);
  const tint = new THREE.Color();
  tuftSpots.forEach(([x, z], i) => {
    const s = 0.7 + rng() * 0.9;
    tmp.position.set(x, 0, z);
    tmp.rotation.set(0, rng() * Math.PI * 2, 0);
    tmp.scale.set(s, s, s);
    tmp.updateMatrix();
    tufts.setMatrixAt(i, tmp.matrix);
    tint.setHSL(0.24 + rng() * 0.07, 0.4 + rng() * 0.22, 0.3 + rng() * 0.14);
    tufts.setColorAt(i, tint);
  });
  tufts.receiveShadow = true;
  noOutline(tufts);
  group.add(tufts);

  const smallPost = new THREE.CylinderGeometry(0.07, 0.08, 0.85, 5);
  const smallRail = new THREE.BoxGeometry(1.7, 0.12, 0.13);
  const fenceGeo = mergeGeometries([
    smallPost.clone().translate(-0.78, 0.42, 0),
    smallPost.clone().translate(0.78, 0.42, 0),
    smallRail.clone().translate(0, 0.58, 0),
    smallRail.clone().translate(0, 0.3, 0),
  ]);
  const fenceSpots = spots(16, 6.5, 2);
  const fences = new THREE.InstancedMesh(fenceGeo, mats.wood, fenceSpots.length);
  fenceSpots.forEach(([x, z], i) => {
    const s = 0.75 + rng() * 0.5;
    tmp.position.set(x, 0, z);
    tmp.rotation.set(0, rng() * Math.PI * 2, 0);
    tmp.scale.set(s, s, s);
    tmp.updateMatrix();
    fences.setMatrixAt(i, tmp.matrix);
  });
  fences.castShadow = true;
  noOutline(fences);
  group.add(fences);

  const craterSpots = spots(14, 4.5, 2);
  const craterMat = new THREE.MeshBasicMaterial({ color: 0x5b4027, transparent: true, opacity: 0.3, depthWrite: false });
  const rimMat = new THREE.MeshBasicMaterial({ color: 0x7a5a36, transparent: true, opacity: 0.38, side: THREE.DoubleSide, depthWrite: false });
  const craters = new THREE.InstancedMesh(new THREE.CircleGeometry(0.72, 12), craterMat, craterSpots.length);
  const rims = new THREE.InstancedMesh(new THREE.RingGeometry(0.55, 0.82, 14), rimMat, craterSpots.length);
  craterSpots.forEach(([x, z], i) => {
    const s = 0.7 + rng() * 0.8;
    tmp.position.set(x, 0.026, z);
    tmp.rotation.set(-Math.PI / 2, 0, 0);
    tmp.scale.setScalar(s);
    tmp.updateMatrix();
    craters.setMatrixAt(i, tmp.matrix);
    tmp.position.y = 0.028;
    tmp.updateMatrix();
    rims.setMatrixAt(i, tmp.matrix);
  });
  noOutline(craters);
  noOutline(rims);
  group.add(craters, rims);

  // Dowel fence: instanced posts plus long rails
  const postGeo = new THREE.CylinderGeometry(0.16, 0.16, 1.5, 6);
  const posts = [];
  for (let x = -FIELD.halfX - 1; x <= FIELD.halfX + 1; x += 3.5) { posts.push([x, -FIELD.halfZ - 1.2], [x, FIELD.halfZ + 1.2]); }
  for (let z = -FIELD.halfZ + 2; z <= FIELD.halfZ - 2; z += 3.5) { posts.push([-FIELD.halfX - 1.4, z], [FIELD.halfX + 1.4, z]); }
  const inst = new THREE.InstancedMesh(postGeo, mats.wood, posts.length);
  const m4 = new THREE.Matrix4();
  posts.forEach(([x, z], i) => { m4.makeTranslation(x, 0.75, z); inst.setMatrixAt(i, m4); });
  inst.castShadow = true;
  group.add(inst);
  const railGeo = new THREE.CylinderGeometry(0.1, 0.1, 1, 6);
  const rail = (len, x, z, alongX, y) => {
    const r = new THREE.Mesh(railGeo, mats.darkWood);
    r.scale.y = len;
    if (alongX) r.rotation.z = Math.PI / 2; else r.rotation.x = Math.PI / 2;
    r.position.set(x, y, z);
    group.add(r);
  };
  for (const y of [0.55, 1.2]) {
    rail(FIELD.halfX * 2 + 2, 0, -FIELD.halfZ - 1.2, true, y);
    rail(FIELD.halfX * 2 + 2, 0, FIELD.halfZ + 1.2, true, y);
    rail(FIELD.halfZ * 2 - 2, -FIELD.halfX - 1.4, 0, false, y);
    rail(FIELD.halfZ * 2 - 2, FIELD.halfX + 1.4, 0, false, y);
  }

  // Barricades: three stacked dowel logs with brass bands
  const logGeo = new THREE.CylinderGeometry(0.42, 0.42, 3.4, 7);
  const bandGeo = new THREE.TorusGeometry(0.5, 0.08, 4, 10);
  for (const b of BARRICADES) {
    const g = new THREE.Group();
    const spots = [[-0.45, 0.42], [0.45, 0.42], [0, 1.1]];
    for (const [ox, y] of spots) {
      const log = new THREE.Mesh(logGeo, mats.wood);
      log.rotation.x = Math.PI / 2;
      log.position.set(ox, y, 0);
      log.castShadow = true;
      g.add(log);
    }
    for (const oz of [-1.1, 1.1]) {
      const band = new THREE.Mesh(bandGeo, mats.brass);
      band.scale.set(1.6, 1.5, 1);
      band.position.set(0, 0.75, oz);
      g.add(band);
    }
    g.position.set(b.x, 0, b.z);
    group.add(g);
  }

  const forts = { blue: buildFort('blue', -FORT_X), red: buildFort('red', FORT_X) };
  group.add(forts.blue.group, forts.red.group);

  // invisible pick plane for rally clicks
  const pick = new THREE.Mesh(new THREE.PlaneGeometry(W, H), new THREE.MeshBasicMaterial({ visible: false }));
  pick.rotation.x = -Math.PI / 2;
  group.add(pick);

  return { group, pick, forts };
}

function buildFort(team, x) {
  const mats = sharedMats();
  const g = new THREE.Group();
  const color = TEAM_COLORS[team];
  const base = new THREE.Mesh(new THREE.CylinderGeometry(FORT_RADIUS, FORT_RADIUS + 0.3, 1.1, 10), toonMat({ color }));
  base.position.y = 0.55;
  const tower = new THREE.Mesh(new THREE.CylinderGeometry(2.0, 2.3, 3.2, 8), mats.wood);
  tower.position.y = 2.7;
  const gear = new THREE.Mesh(new THREE.CylinderGeometry(2.5, 2.5, 0.35, 14), mats.brass);
  gear.position.y = 4.4;
  const teeth = new THREE.Group();
  for (let i = 0; i < 14; i++) {
    const t = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.6, 4), mats.brass);
    const a = (i / 14) * Math.PI * 2;
    t.position.set(Math.cos(a) * 2.6, 0, Math.sin(a) * 2.6);
    t.rotation.z = Math.cos(a) * Math.PI / 2;
    t.rotation.x = -Math.sin(a) * Math.PI / 2;
    teeth.add(t);
  }
  teeth.position.y = 4.4;
  const roof = new THREE.Mesh(new THREE.ConeGeometry(2.4, 2.2, 8), toonMat({ color }));
  roof.position.y = 5.7;
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 2.2, 5), mats.darkWood);
  pole.position.y = 7.6;
  const flag = new THREE.Mesh(new THREE.ConeGeometry(0.5, 1.3, 3), toonMat({ color }));
  flag.rotation.z = -Math.PI / 2;
  flag.scale.z = 0.2;
  flag.position.set(0.65, 8.2, 0);
  for (const m of [base, tower, gear, roof]) { m.castShadow = true; m.receiveShadow = true; }
  g.add(base, tower, gear, teeth, roof, pole, flag);
  g.position.set(x, 0, 0);
  return { group: g, gear: teeth, flag, x };
}
