// sounds.js — passport audio: synthesized ink-stamp THUMP-CHUNK.
//
// No audio assets: a filtered noise burst (the thump) followed by a short
// woody knock (the chunk), both generated with the Web Audio API.
// Safe to import in node (all functions no-op without AudioContext).

let ctx = null;

function ac() {
  if (ctx) return ctx;
  try {
    const AC = typeof AudioContext !== 'undefined' ? AudioContext
      : (typeof globalThis.webkitAudioContext !== 'undefined' ? globalThis.webkitAudioContext : null);
    if (!AC) return null;
    ctx = new AC();
    return ctx;
  } catch {
    return null;
  }
}

/** The ink stamp: THUMP (low noise burst) + CHUNK (short woody knock). */
export function playStamp() {
  const c = ac();
  if (!c) return;
  try {
    if (c.state === 'suspended') void c.resume();
    const t = c.currentTime;

    // THUMP: band-passed noise burst, ~120ms
    const dur = 0.14;
    const buf = c.createBuffer(1, Math.ceil(c.sampleRate * dur), c.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) {
      d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2);
    }
    const noise = c.createBufferSource();
    noise.buffer = buf;
    const bp = c.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 220;
    bp.Q.value = 0.8;
    const ng = c.createGain();
    ng.gain.setValueAtTime(0.9, t);
    ng.gain.exponentialRampToValueAtTime(0.001, t + dur);
    noise.connect(bp).connect(ng).connect(c.destination);
    noise.start(t);

    // CHUNK: woody knock 90ms later — triangle osc, pitch drop 180→70Hz
    const t2 = t + 0.09;
    const osc = c.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(180, t2);
    osc.frequency.exponentialRampToValueAtTime(70, t2 + 0.08);
    const og = c.createGain();
    og.gain.setValueAtTime(0.7, t2);
    og.gain.exponentialRampToValueAtTime(0.001, t2 + 0.1);
    osc.connect(og).connect(c.destination);
    osc.start(t2);
    osc.stop(t2 + 0.12);
  } catch { /* audio must never break the UI */ }
}

/** Soft page-turn swish. */
export function playPageTurn() {
  const c = ac();
  if (!c) return;
  try {
    if (c.state === 'suspended') void c.resume();
    const t = c.currentTime;
    const dur = 0.22;
    const buf = c.createBuffer(1, Math.ceil(c.sampleRate * dur), c.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) {
      const env = Math.sin((i / d.length) * Math.PI); // swell in the middle
      d[i] = (Math.random() * 2 - 1) * env * 0.5;
    }
    const src = c.createBufferSource();
    src.buffer = buf;
    const hp = c.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.setValueAtTime(1200, t);
    hp.frequency.exponentialRampToValueAtTime(4000, t + dur);
    const g = c.createGain();
    g.gain.setValueAtTime(0.35, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(hp).connect(g).connect(c.destination);
    src.start(t);
  } catch { /* audio must never break the UI */ }
}
