// SkateController.js — Dual-mode controller: Speed Roll (Morph Ball) <-> Spring-to-Shoot (FPS).
//
// Allows smooth high-speed rolling around ramps, quarterpipes, and loop-de-loops in 3rd-person ball mode,
// then instantly springing into 1st-person FPS view with gun ready to fire mid-air or mid-slide!

import * as THREE from 'three';

export class SkateController {
  constructor({ camera, canvas, audio, hud, hands, arena, onShoot, onTrick }) {
    this.camera = camera;
    this.canvas = canvas;
    this.audio = audio;
    this.hud = hud;
    this.hands = hands;
    this.arena = arena;
    this.onShoot = onShoot;
    this.onTrick = onTrick;

    // Movement state
    this.pos = new THREE.Vector3(0, 1.5, 30);
    this.vel = new THREE.Vector3(0, 0, 0);
    this.yaw = 0;
    this.pitch = 0;
    this.roll = 0;

    // Modes: 'fps' or 'ball'
    this.mode = 'fps';
    this.isGrounded = false;
    this.isSliding = false;

    // Character ball mesh for 3rd-person ball mode
    this._buildBallMesh();

    // Stats
    this.health = 100;
    this.shield = 100;
    this.ammo = 24;
    this.maxAmmo = 24;
    this.reserveAmmo = 90;
    this.score = 0;
    this.isReloading = false;
    this.lastFireTime = 0;
    this.fireInterval = 0.14; // rapid toy blaster fire

    // Input state
    this.keys = {};
    this.isPointerLocked = false;
    this.mouseButtonDown = false;
    this.rollButtonDown = false;

    this._bindEvents();
  }

  _buildBallMesh() {
    this.ballGroup = new THREE.Group();
    this.ballGroup.name = 'PlayerBallMesh';

    // Yellow sphere with chamfered cube look and cartoon eyes
    const sphereGeo = new THREE.SphereGeometry(0.7, 16, 16);
    const sphereMat = new THREE.MeshStandardMaterial({
      color: 0xffea00,
      roughness: 0.4,
      metalness: 0.05,
    });
    this.ballMesh = new THREE.Mesh(sphereGeo, sphereMat);
    this.ballMesh.castShadow = true;
    this.ballGroup.add(this.ballMesh);

    // Cute Googly Eyes on ball
    const eyeGeo = new THREE.SphereGeometry(0.16, 8, 8);
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const pupilGeo = new THREE.SphereGeometry(0.08, 8, 8);
    const pupilMat = new THREE.MeshBasicMaterial({ color: 0x111111 });

    const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
    leftEye.position.set(-0.25, 0.2, 0.6);
    const leftPupil = new THREE.Mesh(pupilGeo, pupilMat);
    leftPupil.position.set(0, 0, 0.1);
    leftEye.add(leftPupil);
    this.ballMesh.add(leftEye);

    const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
    rightEye.position.set(0.25, 0.2, 0.6);
    const rightPupil = new THREE.Mesh(pupilGeo, pupilMat);
    rightPupil.position.set(0, 0, 0.1);
    rightEye.add(rightPupil);
    this.ballMesh.add(rightEye);

    this.ballGroup.visible = false;
  }

  _bindEvents() {
    this._onKeyDown = (e) => {
      this.keys[e.code] = true;
      if (e.code === 'ShiftLeft' || e.code === 'KeyC') {
        this.setMode('ball');
      }
      if (e.code === 'KeyR' && !this.isReloading && this.ammo < this.maxAmmo) {
        this.reload();
      }
    };

    this._onKeyUp = (e) => {
      this.keys[e.code] = false;
      if ((e.code === 'ShiftLeft' || e.code === 'KeyC') && !this.rollButtonDown) {
        this.setMode('fps');
      }
    };

    this._onMouseDown = (e) => {
      if (!this.isPointerLocked) {
        this.canvas.requestPointerLock?.();
        return;
      }
      if (e.button === 0) { // Left click
        this.mouseButtonDown = true;
        if (this.mode === 'ball') {
          // Instant spring into action & shoot!
          this.setMode('fps');
        }
        this.tryFire();
      } else if (e.button === 2) { // Right click -> Ball mode
        this.rollButtonDown = true;
        this.setMode('ball');
      }
    };

    this._onMouseUp = (e) => {
      if (e.button === 0) {
        this.mouseButtonDown = false;
      } else if (e.button === 2) {
        this.rollButtonDown = false;
        if (!this.keys['ShiftLeft'] && !this.keys['KeyC']) {
          this.setMode('fps');
        }
      }
    };

    this._onMouseMove = (e) => {
      if (!this.isPointerLocked) return;
      const sens = 0.0022;
      this.yaw -= e.movementX * sens;
      this.pitch -= e.movementY * sens;
      this.pitch = Math.max(-Math.PI / 2.2, Math.min(Math.PI / 2.2, this.pitch));
    };

    this._onPointerLockChange = () => {
      this.isPointerLocked = (document.pointerLockElement === this.canvas);
    };

    this._onContextMenu = (e) => e.preventDefault();

    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp);
    window.addEventListener('mousedown', this._onMouseDown);
    window.addEventListener('mouseup', this._onMouseUp);
    window.addEventListener('mousemove', this._onMouseMove);
    window.addEventListener('contextmenu', this._onContextMenu);
    document.addEventListener('pointerlockchange', this._onPointerLockChange);
  }

  setMode(newMode) {
    if (this.mode === newMode) return;
    this.mode = newMode;
    const isBall = (this.mode === 'ball');
    this.audio.playTransform(isBall);
    this.hud.setMode(isBall);
    this.hands.setTucked(isBall);
    this.ballGroup.visible = isBall;

    if (!isBall) {
      // Spring out of ball mode! If moving fast, trigger slide out trick!
      const speed = Math.sqrt(this.vel.x * this.vel.x + this.vel.z * this.vel.z);
      if (speed > 14) {
        this.isSliding = true;
        this.score += 50;
        this.hud.showTrickPopup('+50', 'SLIDEOUT!');
        this.audio.playTrick('slide');
        this.onTrick?.('+50 SLIDEOUT!', 50);
      }
    }
  }

  reload() {
    if (this.isReloading || this.ammo >= this.maxAmmo) return;
    this.isReloading = true;
    setTimeout(() => {
      const needed = this.maxAmmo - this.ammo;
      const available = Math.min(needed, this.reserveAmmo);
      this.ammo += available;
      this.reserveAmmo -= available;
      this.isReloading = false;
      this.hud.updateAmmo(this.ammo, this.maxAmmo);
    }, 900);
  }

  tryFire() {
    if (this.mode !== 'fps' || this.isReloading) return;
    const now = performance.now() / 1000;
    if (now - this.lastFireTime < this.fireInterval) return;
    if (this.ammo <= 0) {
      this.reload();
      return;
    }

    this.lastFireTime = now;
    this.ammo--;
    this.hud.updateAmmo(this.ammo, this.maxAmmo);
    this.hands.triggerFire();
    this.audio.playShoot();

    // Calculate shoot ray from camera
    const origin = this.camera.position.clone();
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.quaternion);

    this.onShoot?.(origin, dir);

    // If firing while in high-speed slide
    const speed = Math.sqrt(this.vel.x * this.vel.x + this.vel.z * this.vel.z);
    if (speed > 16 && !this.isGrounded) {
      this.score += 75;
      this.hud.showTrickPopup('+75', 'AIR SHOT!');
      this.audio.playTrick('air');
      this.onTrick?.('+75 AIR SHOT!', 75);
    }
  }

  takeDamage(amount, fromLeft = true) {
    if (this.shield > 0) {
      this.shield = Math.max(0, this.shield - amount);
    } else {
      this.health = Math.max(0, this.health - amount);
    }
    this.hud.updateHealthAndShield(this.health, this.shield);
    this.hud.showDamageArc(fromLeft);

    if (this.health <= 0) {
      this.respawn();
    }
  }

  respawn() {
    const sp = this.arena.getRandomSpawn();
    this.pos.copy(sp);
    this.vel.set(0, 0, 0);
    this.health = 100;
    this.shield = 100;
    this.ammo = this.maxAmmo;
    this.hud.updateHealthAndShield(this.health, this.shield);
    this.hud.updateAmmo(this.ammo, this.maxAmmo);
    this.hud.showTrickPopup('RESPAWN', 'GET BACK IN THE FIGHT!');
  }

  update(dt) {
    // Continuous fire if mouse held down in FPS mode
    if (this.mouseButtonDown && this.mode === 'fps') {
      this.tryFire();
    }

    const inBall = (this.mode === 'ball');

    // Movement axes
    let moveForward = 0;
    let moveRight = 0;
    if (this.keys['KeyW']) moveForward += 1;
    if (this.keys['KeyS']) moveForward -= 1;
    if (this.keys['KeyD']) moveRight += 1;
    if (this.keys['KeyA']) moveRight -= 1;

    // Movement direction vector
    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const wishDir = new THREE.Vector3();
    wishDir.addScaledVector(forward, moveForward);
    wishDir.addScaledVector(right, moveRight);
    if (wishDir.lengthSq() > 0.001) wishDir.normalize();

    // Physics parameters (Ball vs FPS)
    const accel = inBall ? 48.0 : 36.0;
    const maxSpeed = inBall ? 36.0 : 16.0;
    const friction = inBall ? 0.985 : 0.88; // ball glides and rolls fast
    const gravity = -32.0;

    // Apply acceleration
    this.vel.x += wishDir.x * accel * dt;
    this.vel.z += wishDir.z * accel * dt;

    // Clamp horizontal speed
    const horizSpeed = Math.sqrt(this.vel.x * this.vel.x + this.vel.z * this.vel.z);
    if (horizSpeed > maxSpeed) {
      const scale = maxSpeed / horizSpeed;
      this.vel.x *= scale;
      this.vel.z *= scale;
    }

    // Apply friction
    this.vel.x *= Math.pow(friction, dt * 60);
    this.vel.z *= Math.pow(friction, dt * 60);

    // Jump
    if (this.keys['Space'] && this.isGrounded) {
      this.vel.y = inBall ? 16.0 : 13.0; // Higher bounce in ball mode
      this.isGrounded = false;
      this.audio.playJump();
    }

    // Apply gravity
    this.vel.y += gravity * dt;

    // Apply velocity to position
    this.pos.x += this.vel.x * dt;
    this.pos.y += this.vel.y * dt;
    this.pos.z += this.vel.z * dt;

    // Ground & Ramp collision resolution
    const groundY = 1.0;
    if (this.pos.y <= groundY) {
      this.pos.y = groundY;
      this.vel.y = 0;
      this.isGrounded = true;
    }

    // Mega ramp slope physics (z between -38 and -6, x between -7 and 7)
    if (this.pos.x > -7 && this.pos.x < 7 && this.pos.z > -38 && this.pos.z < -6) {
      const t = (-6 - this.pos.z) / 32;
      const rampHeight = Math.pow(t, 1.8) * 8 + 1.0;
      if (this.pos.y <= rampHeight) {
        this.pos.y = rampHeight;
        if (this.vel.y < 0) this.vel.y = 0;
        this.isGrounded = true;

        // Downhill gravity roll boost!
        if (inBall) {
          this.vel.z += 22.0 * dt; // gravity speeds up rolling downhill
        }
      }
    }

    // Arena boundary clamp
    this.pos.x = Math.max(-43, Math.min(43, this.pos.x));
    this.pos.z = Math.max(-58, Math.min(58, this.pos.z));

    // Update audio roll rumble
    this.audio.updateRollSound(horizSpeed, inBall);

    // Update foam pit interaction
    this.arena.updateFoam(this.pos, horizSpeed);

    // Camera & Ball representation
    if (inBall) {
      // 3rd-person chase camera behind the rolling sphere
      this.ballGroup.position.copy(this.pos);
      // Roll ball rotation according to velocity
      this.ballMesh.rotation.x += this.vel.z * dt * 2.0;
      this.ballMesh.rotation.z -= this.vel.x * dt * 2.0;

      const camDist = 4.2;
      const camHeight = 2.2;
      const camTarget = this.pos.clone().add(new THREE.Vector3(0, 0.8, 0));
      const camOffset = new THREE.Vector3(
        Math.sin(this.yaw) * Math.cos(this.pitch) * camDist,
        Math.sin(-this.pitch) * camDist + camHeight,
        Math.cos(this.yaw) * Math.cos(this.pitch) * camDist
      );

      this.camera.position.copy(this.pos).add(camOffset);
      this.camera.lookAt(camTarget);
    } else {
      // 1st-person FPS camera inside Dweeb's eye level
      this.camera.position.set(this.pos.x, this.pos.y + 0.65, this.pos.z);
      this.camera.rotation.set(0, 0, 0);
      this.camera.rotation.y = this.yaw;
      this.camera.rotation.x = this.pitch;
    }

    // Update viewmodel hands
    this.hands.update(dt, horizSpeed, this.isGrounded, this.isSliding);
  }

  dispose() {
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('mousedown', this._onMouseDown);
    window.removeEventListener('mouseup', this._onMouseUp);
    window.removeEventListener('mousemove', this._onMouseMove);
    window.removeEventListener('contextmenu', this._onContextMenu);
    document.removeEventListener('pointerlockchange', this._onPointerLockChange);
  }
}
