// StampBook.js — the tactile Arcade Passport overlay.
//
// A skeuomorphic vintage leather notebook: parchment pages, page-turn flip
// animations, ink stamps that slam in with a THUMP-CHUNK. Toggleable from
// anywhere (Esc closes). DOM-only; the logic lives in src/game/Passport.js.

import {
  STAMPS, PAGES, COSMETICS, snapshot, stampsForPage,
  onPassportEvent, equipped, ownedCosmetics,
} from '../../game/Passport.js';
import { playStamp, playPageTurn } from './sounds.js';

const BOOK_ID = 'passport-book';

function el(tag, cls, html) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (html != null) n.innerHTML = html;
  return n;
}

function stampCell(stamp, unlocked) {
  const cell = el('div', 'pp-stamp' + (unlocked ? ' unlocked' : ' locked'));
  const rot = unlocked ? ((stamp.id.length * 37) % 14 - 7) : 0; // deterministic tilt
  cell.innerHTML =
    `<div class="pp-stamp-ink" style="--tilt:${rot}deg">` +
      `<span class="pp-stamp-icon">${unlocked ? stamp.icon : '❔'}</span>` +
      `<span class="pp-stamp-name">${unlocked ? stamp.name : '???'}</span>` +
    `</div>` +
    `<div class="pp-stamp-desc">${unlocked ? stamp.desc : 'Keep playing to reveal'}</div>`;
  cell.title = unlocked ? `${stamp.name} — ${stamp.desc}` : 'Locked stamp';
  return cell;
}

export function createStampBook(opts = {}) {
  let root = document.getElementById(BOOK_ID);
  if (root) return apiFor(root); // singleton

  root = el('div', 'pp-root');
  root.id = BOOK_ID;
  root.setAttribute('role', 'dialog');
  root.setAttribute('aria-label', 'Arcade Passport');

  const state = { page: 'brawl', turning: null };

  root.innerHTML =
    `<div class="pp-scrim"></div>` +
    `<div class="pp-book">` +
      `<div class="pp-cover-edge left"></div>` +
      `<div class="pp-cover-edge right"></div>` +
      `<div class="pp-spine"></div>` +
      `<div class="pp-pages">` +
        `<div class="pp-page left">` +
          `<h2 class="pp-title">Arcade<br>Passport</h2>` +
          `<div class="pp-progress"><div class="pp-progress-fill"></div><span class="pp-progress-text"></span></div>` +
          `<nav class="pp-tabs"></nav>` +
          `<div class="pp-wardrobe-teaser"></div>` +
        `</div>` +
        `<div class="pp-page right"><div class="pp-sheet"><div class="pp-stamp-grid"></div></div></div>` +
      `</div>` +
      `<button class="pp-close" aria-label="Close passport">✕</button>` +
      `<div class="pp-unlock-flash"></div>` +
    `</div>`;

  document.body.appendChild(root);

  const scrim = root.querySelector('.pp-scrim');
  const tabsEl = root.querySelector('.pp-tabs');
  const gridEl = root.querySelector('.pp-stamp-grid');
  const fillEl = root.querySelector('.pp-progress-fill');
  const textEl = root.querySelector('.pp-progress-text');
  const teaserEl = root.querySelector('.pp-wardrobe-teaser');
  const flashEl = root.querySelector('.pp-unlock-flash');
  const sheetEl = root.querySelector('.pp-sheet');

  scrim.addEventListener('click', () => api.close());
  root.querySelector('.pp-close').addEventListener('click', () => api.close());

  function renderTabs() {
    tabsEl.innerHTML = '';
    for (const p of [...PAGES, { id: 'wardrobe', name: 'Wardrobe', icon: '👔', color: '#ffd23f' }]) {
      const b = el('button', 'pp-tab' + (state.page === p.id ? ' active' : ''));
      b.style.setProperty('--tab-color', p.color);
      b.innerHTML = `<span class="pp-tab-icon">${p.icon}</span><span>${p.name}</span>`;
      b.addEventListener('click', () => setPage(p.id));
      tabsEl.appendChild(b);
    }
  }

  function renderGrid() {
    const snap = snapshot();
    gridEl.innerHTML = '';
    if (state.page === 'wardrobe') {
      renderWardrobeInto(gridEl, snap);
      return;
    }
    const page = PAGES.find(p => p.id === state.page);
    const stamps = stampsForPage(state.page);
    const head = el('div', 'pp-page-head');
    head.innerHTML = `<span class="pp-page-icon">${page.icon}</span><h3>${page.name}</h3>`;
    gridEl.appendChild(head);
    for (const s of stamps) gridEl.appendChild(stampCell(s, !!snap.stamps[s.id]));
  }

  function renderProgress() {
    const snap = snapshot();
    const pct = snap.total ? Math.round((snap.count / snap.total) * 100) : 0;
    fillEl.style.width = pct + '%';
    textEl.textContent = `${snap.count} / ${snap.total} stamps`;
    const owned = ownedCosmetics();
    teaserEl.innerHTML = owned.length
      ? `<span class="pp-teaser-icon">👔</span> ${owned.length} cosmetic${owned.length > 1 ? 's' : ''} unlocked — open Wardrobe to equip`
      : `<span class="pp-teaser-icon">🔒</span> Unlock stamps to earn wardrobe cosmetics`;
  }

  function renderWardrobeInto(container, snap) {
    const head = el('div', 'pp-page-head');
    head.innerHTML = `<span class="pp-page-icon">👔</span><h3>Wardrobe</h3>`;
    container.appendChild(head);
    const note = el('div', 'pp-wardrobe-note',
      'Cosmetics apply to your Dweeb across every game mode.');
    container.appendChild(note);
    for (const c of COSMETICS) {
      const owned = !!snap.stamps[c.from];
      const isEq = snap.equipped[c.slot] === c.id;
      const row = el('div', 'pp-cosmetic' + (owned ? '' : ' locked') + (isEq ? ' equipped' : ''));
      row.innerHTML =
        `<span class="pp-cos-icon">${owned ? c.icon : '🔒'}</span>` +
        `<span class="pp-cos-body"><b>${owned ? c.name : '???'}</b><i>${owned ? c.desc : 'Earn the matching stamp'}</i></span>` +
        (owned ? `<button class="pp-cos-btn">${isEq ? 'Unequip' : 'Equip'}</button>` : '');
      const btn = row.querySelector('.pp-cos-btn');
      if (btn) btn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (opts.onEquip) opts.onEquip(c, !isEq);
        renderAll();
      });
      container.appendChild(row);
    }
  }

  function renderAll() {
    renderTabs();
    renderGrid();
    renderProgress();
  }

  function setPage(id) {
    if (id === state.page || state.turning) return;
    state.turning = id;
    playPageTurn();
    sheetEl.classList.add('turning');
    setTimeout(() => {
      state.page = id;
      renderAll();
      sheetEl.classList.remove('turning');
      sheetEl.classList.add('turned-in');
      setTimeout(() => sheetEl.classList.remove('turned-in'), 350);
      state.turning = null;
    }, 180);
  }

  /** Slam-in animation for a fresh unlock. */
  function showUnlock(stamp, cosmetic) {
    renderAll();
    flashEl.innerHTML =
      `<div class="pp-flash-stamp"><span class="pp-flash-icon">${stamp.icon}</span>` +
      `<b>${stamp.name}</b><i>${stamp.desc}</i>` +
      (cosmetic ? `<span class="pp-flash-cos">${cosmetic.icon} ${cosmetic.name} equipped!</span>` : '') +
      `</div>`;
    flashEl.classList.add('show');
    // Stagger the slam slightly so the book is visible first.
    setTimeout(() => {
      flashEl.querySelector('.pp-flash-stamp').classList.add('slam');
      playStamp();
    }, 60);
    setTimeout(() => flashEl.classList.remove('show'), 2600);
  }

  const api = {
    el: root,
    open(page) {
      if (page) state.page = page;
      renderAll();
      root.classList.add('open');
      document.body.classList.add('pp-lock');
    },
    close() {
      root.classList.remove('open');
      document.body.classList.remove('pp-lock');
    },
    toggle(page) {
      if (root.classList.contains('open')) api.close();
      else api.open(page);
    },
    get isOpen() { return root.classList.contains('open'); },
    refresh: renderAll,
    showUnlock,
    setPage,
  };

  function apiFor() { return api; }

  // Live updates: refresh when stamps unlock elsewhere; celebrate fresh ones.
  const unsub = onPassportEvent((evt) => {
    if (evt.type === 'stamp') {
      if (api.isOpen) showUnlock(evt.stamp, evt.cosmetic);
      else renderAll();
    } else {
      renderAll();
    }
  });
  api.destroy = () => { unsub(); root.remove(); };

  document.addEventListener('keydown', (e) => {
    if (!api.isOpen) return;
    if (e.key === 'Escape') api.close();
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      const ids = [...PAGES.map(p => p.id), 'wardrobe'];
      let i = ids.indexOf(state.page);
      i = (i + (e.key === 'ArrowRight' ? 1 : ids.length - 1)) % ids.length;
      setPage(ids[i]);
    }
  });

  renderAll();
  return api;
}

/** One-liner for game code: toggles the singleton book. */
let singleton = null;
export function togglePassport(page) {
  if (!singleton || !document.getElementById(BOOK_ID)) singleton = createStampBook();
  singleton.toggle(page);
  return singleton;
}
export function openPassport(page) {
  if (!singleton || !document.getElementById(BOOK_ID)) singleton = createStampBook();
  singleton.open(page);
  return singleton;
}
