// persistence.js — Automatic save/load of village state (Expedition & Dynasty)
//
// The village (colony population, built structures, gathered resources, vault
// progress, time of day, relics, tech tier, pop cap, ruin puzzle state) is saved
// to localStorage so a session picks up where the last one ended. Storage is
// injected so headless tests can pass a fake.
//
// Save shape (versioned, so old saves can be migrated):
//   v1: { version: 1, savedAt, colony, structures, world }
//   v2: { version: 2, savedAt,
//         colony: { ...v1 fields, techTier?, popCap?, relics? },
//         structures: [ {id,x,y,z,rotation?,stored?,hp?} ],
//         world: { timeOfDay, relics, ruins: [{id,opened,solved,progress,relicCollected}] } }

export const SAVE_KEY = 'dweebs-village-v2';
export const SAVE_VERSION = 2;

function defaultStorage() {
  return typeof globalThis !== 'undefined' ? globalThis.localStorage : undefined;
}

/** Serialize the live village and write it to storage. */
export function saveVillage({ colony, buildingManager, world }, storage = defaultStorage()) {
  if (!storage || typeof storage.setItem !== 'function') {
    return { ok: false, reason: 'no-storage' };
  }
  const data = {
    version: SAVE_VERSION,
    savedAt: new Date().toISOString(),
    colony: colony ? colony.serialize() : null,
    structures: buildingManager
      ? buildingManager.placedStructures.map(s => (typeof s.serialize === 'function' ? s.serialize() : { id: s.id, x: s.pos.x, y: s.pos.y, z: s.pos.z }))
      : [],
    world: world && typeof world.serialize === 'function' ? world.serialize() : null,
  };
  try {
    storage.setItem(SAVE_KEY, JSON.stringify(data));
    return { ok: true, savedAt: data.savedAt };
  } catch (err) {
    return { ok: false, reason: String(err && err.message ? err.message : err) };
  }
}

/** Read the saved village, or null when there is none / it is unusable.
 *  Handles migration from v1 to v2. Never throws on corrupt data. */
export function loadVillage(storage = defaultStorage()) {
  if (!storage || typeof storage.getItem !== 'function') return null;
  let raw;
  try {
    raw = storage.getItem(SAVE_KEY);
    // Also check legacy v1 key for migration
    if (!raw) raw = storage.getItem('dweebs-village-v1');
  } catch {
    return null;
  }
  if (!raw) return null;
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!data || typeof data.version !== 'number') return null;

  // Migration v1 -> v2
  if (data.version === 1) {
    data = migrateV1toV2(data);
  } else if (data.version > SAVE_VERSION) {
    // Future version — don't try to load
    return null;
  }
  // Ensure v2 shape
  data.version = SAVE_VERSION;
  return data;
}

/** Migrate a v1 save to v2 format. */
function migrateV1toV2(v1) {
  const colony = v1.colony || {};
  const world = v1.world || {};
  return {
    version: 2,
    savedAt: v1.savedAt || new Date().toISOString(),
    colony: {
      ...colony,
      techTier: colony.techTier ?? 0,
      populationCap: colony.populationCap ?? 20,
      relics: colony.relics ?? 0,
    },
    structures: (v1.structures || []).map(s => ({
      id: s.id,
      x: s.x ?? 0,
      y: s.y ?? 0,
      z: s.z ?? 0,
      rotation: s.rotation ?? 0,
      stored: s.stored ?? null,
      hp: s.hp ?? null,
    })),
    world: {
      timeOfDay: world.timeOfDay ?? 8,
      relics: world.relics ?? 0,
      ruins: (world.ruinsOpened || []).map(id => ({
        id,
        opened: true,
        solved: false,
        progress: 0,
        relicCollected: false,
      })),
    },
  };
}

/** Remove the saved village. */
export function clearSave(storage = defaultStorage()) {
  if (!storage || typeof storage.removeItem !== 'function') return false;
  try {
    storage.removeItem(SAVE_KEY);
    return true;
  } catch {
    return false;
  }
}

/**
 * Apply a loaded save to a freshly built village.
 * Citizens must already exist on the colony (added from the spawned Dweebs);
 * they are matched to saved citizens by index.
 * Returns a summary of what was restored.
 */
export function applySave(save, { colony, buildingManager, world }) {
  const summary = { citizens: 0, structures: 0, gold: 0 };
  if (!save) return summary;
  if (colony && save.colony) {
    colony.restore(save.colony);
    summary.citizens = colony.citizens.length;
    summary.gold = colony.resources.gold || 0;
  }
  if (buildingManager && Array.isArray(save.structures)) {
    for (const data of save.structures) {
      const s = buildingManager.placeSaved(data, world, colony);
      if (s) summary.structures += 1;
    }
  }
  if (world && save.world && typeof world.restore === 'function') {
    world.restore(save.world);
  }
  return summary;
}

/**
 * Install automatic save hooks:
 *  - Periodic save every 30 seconds (returns timer ID for cancellation)
 *  - pagehide / beforeunload for session end
 * Call once when the adventure mode starts; returns a cleanup function.
 */
export function installAutosave(getVillage, storage = defaultStorage()) {
  if (!storage || typeof storage.setItem !== 'function') {
    return () => {}; // no-op cleanup
  }
  let timerId = null;
  const saveNow = () => {
    try {
      const village = getVillage?.();
      if (village?.colony && village?.buildingManager && village?.world) {
        saveVillage(village, storage);
      }
    } catch {
      // Never throw from autosave
    }
  };

  // Periodic autosave every 30s
  timerId = setInterval(saveNow, 30_000);

  // Page unload hooks
  const onHide = () => saveNow();
  const onUnload = () => saveNow();
  if (typeof globalThis !== 'undefined' && globalThis.addEventListener) {
    globalThis.addEventListener('pagehide', onHide);
    globalThis.addEventListener('beforeunload', onUnload);
  }

  // Return cleanup function
  return () => {
    if (timerId) clearInterval(timerId);
    if (typeof globalThis !== 'undefined' && globalThis.removeEventListener) {
      globalThis.removeEventListener('pagehide', onHide);
      globalThis.removeEventListener('beforeunload', onUnload);
    }
  };
}
