// WarfareView.js — draws a warfare battle state with three.js. Reads the sim, never writes it.
// Interpolates unit positions between 30 Hz sim ticks, swaps team plastic on conversion, and
// turns sim events into juice via WarfareFx.
import * as THREE from 'three';
import { counterMult, bounty as unitBounty } from '../sim/warfareUnits.js';
import { buildBoard } from './WarfareBoard.js';
import { buildUnit, buildShell, buildRing, buildStructure, teamMat, flashMat, ringMat, glowMat, TEAM_COLORS, sharedMats } from './WarfareModels.js';
import { WarfareFx } from './WarfareFx.js';
import { noOutline } from '../render/Toon.js';

const lerp = (a, b, t) => a + (b - a) * t;
const freezeGeo = new THREE.SphereGeometry(0.72, 8, 6);
const freezeMat = new THREE.MeshBasicMaterial({ color: 0x9fe8ff, transparent: true, opacity: 0.28, depthWrite: false });

export class WarfareView {
  constructor(scene, camera, hudRoot = null) {
    this.scene = scene;
    this.camera = camera;
    this.group = new THREE.Group();
    this.group.name = 'warfare';
    scene.add(this.group);
    this.board = buildBoard();
    this.group.add(this.board.group);
    this.dyn = new THREE.Group();
    this.group.add(this.dyn);
    this.fx = new WarfareFx(this.group, camera);
    // Connect HUD gold counter for coin fly-to animation
    if (hudRoot) {
      const goldChip = hudRoot.querySelector('[data-f="coins"]')?.closest('.wf-chip');
      if (goldChip) this.fx.hudGoldEl = goldChip;
    }
    this.entries = new Map();   // unit id → entry
    this.shells = new Map();    // shell obj → mesh
    this.structures = new Map(); // structure id → { m, x, z, team, type }
    this.rally = {};
    for (const team of ['blue', 'red']) {
      const g = new THREE.Group();
      const ring = buildRing(TEAM_COLORS[team]);
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 2.4, 5), sharedMats().brass);
      pole.position.y = 1.2;
      const flag = new THREE.Mesh(new THREE.ConeGeometry(0.4, 1, 3), teamMat(team));
      flag.rotation.z = -Math.PI / 2;
      flag.scale.z = 0.25;
      flag.position.set(0.5, 2.1, 0);
      g.add(ring, pole, flag);
      g.visible = false;
      this.dyn.add(g);
      this.rally[team] = { g, ring, flag };
    }
    this.time = 0;
    this.localTeam = 'blue';
    // Spawn-lane warning system
    this._spawnWarn = {
      arrows: [],      // pooled arrow meshes
      active: false,
      timer: 0,
      duration: 3.0,
      edgeGlow: null,  // DOM element for screen-edge glow
    };
    this._initSpawnWarnPool();
    this._initFortDamage();
  }

  /** Initialize the pool of arrow/chevron meshes for spawn-lane warnings. */
  _initSpawnWarnPool() {
    const { _spawnWarn } = this;
    const arrowGeo = new THREE.ConeGeometry(1.1, 3.2, 4);
    const arrowMat = new THREE.MeshBasicMaterial({
      color: 0xff3333,
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
    });
    // Create 12 arrows (enough for a lane)
    for (let i = 0; i < 12; i++) {
      const arrow = new THREE.Mesh(arrowGeo, arrowMat.clone());
      arrow.rotation.x = -Math.PI / 2; // point along -x (toward blue fort)
      arrow.rotation.z = Math.PI;      // tip points toward negative x
      arrow.visible = false;
      this.dyn.add(arrow);
      _spawnWarn.arrows.push({ mesh: arrow, life: 0, delay: 0 });
    }
    // Create screen-edge glow DOM element
    const glow = document.createElement('div');
    glow.style.cssText = `
      position: fixed;
      top: 0; right: 0; bottom: 0; width: 120px;
      background: linear-gradient(90deg, transparent 0%, rgba(255,51,51,0.35) 100%);
      pointer-events: none;
      z-index: 35;
      opacity: 0;
      transition: opacity 0.15s;
    `;
    document.body.appendChild(glow);
    _spawnWarn.edgeGlow = glow;
  }

  /** Clear all spawn warnings (called on reset and when warning expires). */
  _clearSpawnWarn() {
    const { _spawnWarn } = this;
    _spawnWarn.active = false;
    _spawnWarn.timer = 0;
    for (const a of _spawnWarn.arrows) {
      a.mesh.visible = false;
      a.life = 0;
    }
    if (_spawnWarn.edgeGlow) _spawnWarn.edgeGlow.style.opacity = '0';
  }

  /** Activate spawn-lane warning for ~3s at the enemy spawn edge. */
  _activateSpawnWarn() {
    const { _spawnWarn } = this;
    _spawnWarn.active = true;
    _spawnWarn.timer = _spawnWarn.duration;
    // Position arrows along the spawn lane (red side, z from -15 to 15)
    const spawnX = 31; // enemy spawn x (just in front of red fort at x=36)
    const laneZ = [-14, -9, -4, 1, 6, 11]; // 6 positions across the lane
    for (let i = 0; i < _spawnWarn.arrows.length; i++) {
      const a = _spawnWarn.arrows[i];
      const laneIdx = i % laneZ.length;
      const pair = Math.floor(i / laneZ.length); // 0 or 1 for two rows
      a.mesh.position.set(spawnX - pair * 3, 0.15, laneZ[laneIdx]);
      a.mesh.visible = true;
      a.life = _spawnWarn.duration;
      a.delay = (i * 0.08) % 0.5; // staggered pulse
    }
    // Show edge glow on right side (enemy side)
    if (_spawnWarn.edgeGlow) _spawnWarn.edgeGlow.style.opacity = '0.9';
  }

  /** Update spawn warning animation. */
  _updateSpawnWarn(dt) {
    const { _spawnWarn } = this;
    if (!_spawnWarn.active) return;
    _spawnWarn.timer -= dt;
    const t = this.time;
    for (const a of _spawnWarn.arrows) {
      if (a.life <= 0) { a.mesh.visible = false; continue; }
      a.life -= dt;
      // Pulsing scale and opacity
      const phase = (t * 6 + a.delay) % (Math.PI * 2);
      const pulse = 0.7 + 0.3 * Math.sin(phase);
      a.mesh.scale.setScalar(pulse);
      a.mesh.material.opacity = 0.5 + 0.4 * Math.sin(phase);
      // Gentle forward bob
      a.mesh.position.y = 0.15 + Math.sin(t * 4 + a.delay) * 0.08;
    }
    // Fade edge glow
    if (_spawnWarn.edgeGlow) {
      const pct = Math.max(0, _spawnWarn.timer / _spawnWarn.duration);
      _spawnWarn.edgeGlow.style.opacity = String(0.9 * pct);
    }
    if (_spawnWarn.timer <= 0) this._clearSpawnWarn();
  }

  get pickMesh() { return this.board.pick; }

  reset() {
    // Clear spawn warnings
    this._clearSpawnWarn();
    this._resetFortDamage();
    for (const e of this.entries.values()) this.dyn.remove(e.m.root);
    this.entries.clear();
    for (const m of this.shells.values()) this.dyn.remove(m);
    this.shells.clear();
    for (const s of this.structures.values()) this.dyn.remove(s.m);
    this.structures.clear();
    this.fx.clear();
  }

  /** Call after every sim step: roll interpolation buffers and react to events. */
  afterStep(st) {
    const seen = new Set();
    for (const u of st.units) {
      seen.add(u.id);
      let e = this.entries.get(u.id);
      if (!e) {
        const m = buildUnit(u.type, u.team);
        m.root.position.set(u.x, 0, u.z);
        this.dyn.add(m.root);
        e = { m, px: u.x, pz: u.z, x: u.x, z: u.z, team: u.team, yaw: u.team === 'blue' ? 0 : Math.PI, flash: 0, leanX: 0, leanZ: 0, spawnT: 0, type: u.type, flag: null };
        this.entries.set(u.id, e);
      }
      e.px = e.x; e.pz = e.z;
      e.x = u.x; e.z = u.z;
      e.vx = u.vx; e.vz = u.vz;
      e.carried = !!u.carriedBy;
      e.carrying = !!u.carrying;
      e.retreat = u.state === 'retreat';
      e.freeze = u.freeze || 0;
      e.hpFrac = u.hp / u.maxHp;
      if (e.team !== u.team) {
        e.team = u.team;
        e.m.body.material = teamMat(u.team);
        e.m.groundRing.material = ringMat(u.team);
        e.m.groundGlow.material = glowMat(u.team);
      }
    }
    this._events(st.events);
    for (const [id, e] of this.entries) {
      if (!seen.has(id)) { this.dyn.remove(e.m.root); this.entries.delete(id); }
    }
    // shells
    const live = new Set(st.shells);
    for (const sh of st.shells) {
      if (!this.shells.has(sh)) {
        const m = buildShell(sh.team, sh.kind);
        this.dyn.add(m);
        this.shells.set(sh, m);
      }
    }
    for (const [sh, m] of this.shells) if (!live.has(sh)) { this.dyn.remove(m); this.shells.delete(sh); }
    // player-built fortifications
    const liveStructs = new Set();
    for (const s of st.structures || []) {
      liveStructs.add(s.id);
      let e = this.structures.get(s.id);
      if (!e) {
        const m = buildStructure(s.type, s.team);
        m.position.set(s.x, 0, s.z);
        this.dyn.add(m);
        e = { m, x: s.x, z: s.z, team: s.team, type: s.type, hit: 0 };
        this.structures.set(s.id, e);
      }
      e.hp = s.hp;
      e.maxHp = s.maxHp;
    }
    for (const [id, e] of this.structures) if (!liveStructs.has(id)) { this.dyn.remove(e.m); this.structures.delete(id); }
    for (const team of ['blue', 'red']) {
      const r = st.rally[team];
      const show = team === this.localTeam || st.mode === 'versus';
      this.rally[team].g.visible = show && !!r && !(st.mode === 'defense' && team === 'red');
      if (r) this.rally[team].g.position.set(r.x, 0.05, r.z);
    }
  }

  _events(events) {
    const fx = this.fx;
    for (const ev of events) {
      const e = ev.id ? this.entries.get(ev.id) : null;
      switch (ev.type) {
        case 'hit': {
          if (e) {
            e.flash = 0.1;
            e.leanX += ev.kx * 0.08; e.leanZ += ev.kz * 0.08;
          }
          const mult = counterMult(ev.src, ev.unit);
          fx.number(ev.x, 2.2, ev.z, String(Math.max(1, Math.round(ev.dmg))), mult > 1.05 ? 'crit' : mult < 0.95 ? 'weak' : '');
          break;
        }
        case 'death': {
          if (e) {
            this.entries.delete(ev.id);
            this.dyn.remove(e.m.root);
            const root = e.m.root;
            root.position.set(e.x, 0, e.z);
            e.m.body.material = teamMat(e.team);
            const isBig = ev.unit === 'boss' || ev.unit === 'brute';
            fx.deathPop(root, e.team, ev.kx, ev.kz, isBig);
            if (ev.unit === 'boss') { fx.addShake(1.2); fx.explosion(e.x, e.z, 6, true); }
            // Kill reward: spawn coins flying to HUD when enemy dies (not our own units)
            if (e.team !== this.localTeam) {
              const bounty = unitBounty(ev.unit);
              fx.spawnCoins(e.x, 1.5, e.z, Math.max(2, Math.min(6, Math.round(bounty / 6))));
              // Bigger "crit"-style kill pop
              fx.number(e.x, 2.8, e.z, `+${bounty}`, 'crit');
            }
          }
          break;
        }
        case 'explode': fx.explosion(ev.x, ev.z, ev.r, !!ev.big); break;
        case 'slam': fx.shockwave(ev.x, ev.z, ev.r * 1.3, 0xd4a73a); fx.addShake(ev.unit === 'boss' ? 0.7 : 0.25); fx.puff(ev.x, ev.z); break;
        case 'fire': if (e) { fx.puff(ev.x, ev.z); fx.muzzle(ev.x, ev.z); e.leanX -= (ev.tx - ev.x) * 0.01; e.leanZ -= (ev.tz - ev.z) * 0.01; } break;
        case 'grab': fx.number(ev.x, 2.6, ev.z, 'GRAB!', 'word'); break;
        case 'convert': fx.number(ev.x, 2.8, ev.z, ev.flip ? 'FUSE FLIP!' : 'CONVERTED!', 'word'); fx.shockwave(ev.x, ev.z, 3, TEAM_COLORS[ev.team]); break;
        case 'retreat': fx.number(ev.x, 2.4, ev.z, 'RETREAT!', 'weak'); break;
        case 'fortHit': this._fortHitFeedback(ev.team); break;
        case 'spawn': if (e) e.spawnT = 0.35; break;
        case 'waveStart': this._activateSpawnWarn(); break;
        case 'charge': fx.number(ev.x, 3, ev.z, 'CHARGE!', 'weak'); fx.puff(ev.x, ev.z); if (e) e.leanX -= 1.5; break;
        case 'backstab': fx.number(ev.x, 2.9, ev.z, 'BACKSTAB!', 'crit'); break;
        case 'enrage': fx.shockwave(ev.x, ev.z, 7, 0xff4d5e); fx.addShake(0.8); fx.number(ev.x, 4.5, ev.z, 'ENRAGED!', 'crit'); if (e) e.enraged = true; break;
        case 'rally': this.rally[ev.team].pulse = 0.5; break;
        case 'freeze': {
          fx.shockwave(ev.x, ev.z, ev.r, 0x9fe8ff);
          fx.number(ev.x, 3.2, ev.z, 'FROZEN!', 'crit');
          break;
        }
        case 'bounce': fx.explosion(ev.tx, ev.tz, ev.r, false); break;
        case 'build': {
          const s = this.structures.get(ev.id);
          if (s) s.hit = 0.4;
          fx.shockwave(ev.x, ev.z, 3.2, TEAM_COLORS[ev.team]);
          fx.number(ev.x, 2.4, ev.z, 'BUILT!', 'word');
          break;
        }
        case 'repair': {
          const s = this.structures.get(ev.id);
          if (s) s.hit = 0.35;
          fx.shockwave(ev.x, ev.z, 2.4, 0x5ee06a);
          fx.number(ev.x, 2.4, ev.z, 'REPAIRED!', 'word');
          break;
        }
        case 'structureHit': {
          const s = this.structures.get(ev.id);
          if (s) s.hit = 0.18;
          break;
        }
        case 'structureDown': {
          const s = this.structures.get(ev.id);
          if (s) { this.dyn.remove(s.m); this.structures.delete(ev.id); }
          fx.explosion(ev.x, ev.z, 3.4, true);
          break;
        }
        case 'turretFire': {
          fx.muzzle(ev.x, ev.z);
          fx.number(ev.tx, 2.1, ev.tz, 'PING!', 'weak');
          const s = this.structures.get(ev.id);
          if (s) s.fire = 0.12;
          break;
        }
        case 'caltrop': fx.puff(ev.tx, ev.tz); break;
        case 'smash': {
          const s = this.structures.get(ev.structureId);
          if (s) s.hit = 0.2;
          if (e) { e.leanX += (ev.x - e.x) * 0.02; e.leanZ += (ev.z - e.z) * 0.02; }
          break;
        }
        default: break;
      }
    }
  }

  /** Render-rate update: interpolate, animate and run fx. alpha ∈ [0,1) between ticks. */
  frame(st, alpha, dt) {
    this.time += dt;
    const t = this.time;
    for (const [, e] of this.entries) {
      const root = e.m.root;
      const x = lerp(e.px, e.x, alpha), z = lerp(e.pz, e.z, alpha);
      const sp = Math.hypot(e.vx || 0, e.vz || 0);
      if (sp > 0.3) {
        const want = Math.atan2(-(e.vz || 0), e.vx || 0);
        let d = want - e.yaw;
        while (d > Math.PI) d -= Math.PI * 2;
        while (d < -Math.PI) d += Math.PI * 2;
        e.yaw += d * Math.min(1, dt * 10);
      }
      root.position.set(x, 0, z);
      root.rotation.y = e.yaw;
      // Keep the team ring pinned flat to the play-mat instead of bobbing with the body.
      const gy = (0.045 - root.position.y) / root.scale.y;
      e.m.groundRing.position.y = gy;
      e.m.groundGlow.position.y = gy - 0.006;
      e.m.groundRing.visible = !e.carried;
      e.m.groundGlow.visible = !e.carried;
      const tilt = e.m.tilt;
      if (e.carried) {
        root.position.y = 1.5;
        tilt.rotation.x = Math.sin(t * 14 + e.x) * 0.5;
        tilt.rotation.z = Math.PI * 0.45;
      } else {
        const bob = sp > 0.5 ? Math.abs(Math.sin(t * (8 + sp))) * 0.14 : 0;
        root.position.y = bob;
        e.leanX *= Math.max(0, 1 - dt * 6); e.leanZ *= Math.max(0, 1 - dt * 6);
        tilt.rotation.z = (sp > 0.5 ? Math.sin(t * (8 + sp)) * 0.12 : 0) - e.leanX * 0.5;
        tilt.rotation.x = e.leanZ * 0.5;
      }
      // squash on spawn, flash on hit
      if (e.spawnT > 0) { e.spawnT -= dt; const p = 1 - Math.max(0, e.spawnT) / 0.35; tilt.scale.set(1 + (1 - p) * 0.4, p, 1 + (1 - p) * 0.4); }
      else tilt.scale.set(1, 1, 1);
      if (e.flash > 0) { e.flash -= dt; e.m.body.material = flashMat(); tilt.scale.multiplyScalar(1.12); }
      else if (e.m.body.material !== teamMat(e.team)) e.m.body.material = teamMat(e.team);
      if (e.m.spark) e.m.spark.scale.setScalar(0.7 + Math.abs(Math.sin(t * 30 + e.x)) * 0.8);
      if (e.type === 'wizard' && e.m.gear?.userData.bubble) e.m.gear.userData.bubble.scale.setScalar(0.45 + Math.sin(t * 4) * 0.06);
      // frozen units wear a wobbling soap bubble
      if (e.freeze > 0 && !e.bubble) {
        const b = new THREE.Mesh(freezeGeo, freezeMat);
        b.position.y = 0.75;
        tilt.add(b);
        e.bubble = b;
      } else if (e.freeze <= 0 && e.bubble) { tilt.remove(e.bubble); e.bubble = null; }
      if (e.bubble) e.bubble.scale.setScalar(1 + Math.sin(t * 8 + e.x) * 0.05);
      if (e.type === 'boss') {
        const back = tilt.getObjectByName('backGear');
        if (back) back.rotation.y += dt * (e.enraged ? 9 : 3);
        if (e.enraged) tilt.scale.multiplyScalar(1 + Math.abs(Math.sin(t * 10)) * 0.06);
        if (e.m.gear) e.m.gear.rotation.y += dt * 1.5;
      }
      // retreat flag: a little white plastic flag on a dowel
      if (e.retreat && !e.flag) {
        const f = new THREE.Group();
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.9, 4), sharedMats().wood);
        pole.position.y = 0.45;
        const cloth = new THREE.Mesh(new THREE.PlaneGeometry(0.45, 0.3), sharedMats().retreat);
        cloth.position.set(0.22, 0.75, 0);
        f.add(pole, cloth);
        f.position.set(-0.3, e.m.height + 0.1, 0);
        tilt.add(f);
        e.flag = f;
      } else if (!e.retreat && e.flag) { tilt.remove(e.flag); e.flag = null; }
      if (e.flag) e.flag.rotation.y = Math.sin(t * 9) * 0.4;
    }
    for (const [sh, m] of this.shells) {
      const p = Math.min(1, (sh.t + alpha) / sh.T);
      const dx = sh.x1 - sh.x0, dz = sh.z1 - sh.z0;
      const d = Math.hypot(dx, dz);
      const h = 1.5 + d * 0.22;
      m.position.set(sh.x0 + dx * p, 1 + h * 4 * p * (1 - p), sh.z0 + dz * p);
      const vy = h * 4 * (1 - 2 * p);
      m.rotation.set(0, Math.atan2(-dz, dx), Math.atan2(vy, d || 1));
    }
    for (const team of ['blue', 'red']) {
      const r = this.rally[team];
      r.pulse = Math.max(0, (r.pulse || 0) - dt);
      r.ring.scale.setScalar(1 + Math.sin(t * 4) * 0.08 + r.pulse * 2);
      r.flag.rotation.y = Math.sin(t * 3) * 0.3;
    }
    for (const team of ['blue', 'red']) {
      const f = this.board.forts[team];
      const d = this._fortDamage?.[team];
      f.gear.rotation.y += dt * (team === 'blue' ? 0.6 : -0.6);
      f.hit = Math.max(0, (f.hit || 0) - dt);
      f.group.scale.set(1 + f.hit * 0.25, 1 - f.hit * 0.2, 1 + f.hit * 0.25);
      const fort = st && st.forts[team];
      f.group.visible = !fort || fort.hp > 0 || fort.invulnerable;
      f.flag.rotation.y = Math.sin(t * 2 + (team === 'red' ? 1 : 0)) * 0.4;
      if (d) {
        d.flash = Math.max(0, d.flash - dt);
        d.wobble = Math.max(0, d.wobble - dt * 2.1);
        f.group.rotation.x = d.baseGroupRot.x + Math.sin(t * 33) * d.wobble * 0.1;
        f.group.rotation.z = d.baseGroupRot.z + Math.cos(t * 27) * d.wobble * 0.13;
        for (const rec of d.mats) {
          if (!rec.mat.emissive) continue;
          rec.mat.emissive.setHex(d.flash > 0 ? d.flashColor : rec.emissive);
        }
      }
    }
    for (const [, s] of this.structures) {
      s.hit = Math.max(0, (s.hit || 0) - dt);
      s.fire = Math.max(0, (s.fire || 0) - dt);
      s.m.scale.set(1 + s.hit * 0.18, 1 - s.hit * 0.12, 1 + s.hit * 0.18);
      if (s.type === 'turret') {
        const head = s.m.getObjectByName('turretHead');
        if (head) head.rotation.y = Math.sin(t * 0.8 + s.x) * 0.6;
      } else if (s.type === 'caltrop') {
        s.m.rotation.y += dt * 0.4;
      }
      if (s.fire > 0) s.m.scale.multiplyScalar(1.08);
    }
    this._updateFortDamage(st, dt);
    this._updateSpawnWarn(dt);
    this.fx.update(dt);
  }

  /** Build per-fort damage state: cloned materials, crenellation pieces, cracks and a smoke pool. */
  _initFortDamage() {
    const smokeGeo = new THREE.DodecahedronGeometry(0.55, 0);
    const crackGeo = new THREE.BoxGeometry(0.09, 1, 0.09);
    this._fortDamage = {};
    for (const team of ['blue', 'red']) {
      const f = this.board.forts[team];
      const d = {
        team, stage: 0, mats: [], teeth: [], cracks: null, crackMeshes: [],
        smoke: [], smokeIdx: 0, smokeAcc: 0, flash: 0, flashColor: 0xffffff,
        flashRed: false, wobble: 0, feedbackAt: -999,
        baseGroupRot: { x: f.group.rotation.x, z: f.group.rotation.z },
        flagBase: {
          x: f.flag.position.x, y: f.flag.position.y, z: f.flag.position.z,
          rotY: f.flag.rotation.y, rotZ: f.flag.rotation.z,
          scaleX: f.flag.scale.x, scaleY: f.flag.scale.y, scaleZ: f.flag.scale.z,
        },
      };
      // Clone every fort material so damage tinting never leaks into shared toy materials.
      f.group.traverse(o => {
        if (!o.material) return;
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        const cloned = mats.map(m => m.clone());
        o.material = Array.isArray(o.material) ? cloned : cloned[0];
        for (const m of cloned) {
          d.mats.push({
            mat: m,
            color: m.color ? m.color.clone() : null,
            emissive: m.emissive ? m.emissive.getHex() : 0,
          });
        }
      });
      for (const tooth of f.gear.children) {
        d.teeth.push({
          mesh: tooth, visible: tooth.visible !== false,
          x: tooth.position.x, y: tooth.position.y, z: tooth.position.z,
          rotX: tooth.rotation.x, rotZ: tooth.rotation.z,
        });
      }
      // Jagged crack decals around the tower, revealed stage by stage.
      const cracks = new THREE.Group();
      const crackMat = new THREE.MeshBasicMaterial({ color: 0x241916, transparent: true, opacity: 0.9, depthWrite: false });
      for (let i = 0; i < 6; i++) {
        const m = new THREE.Mesh(crackGeo, crackMat);
        const a = (i / 6) * Math.PI * 2 + (team === 'blue' ? 0.3 : 0.8);
        m.position.set(Math.cos(a) * 2.08, 1.55 + (i % 3) * 1.15, Math.sin(a) * 2.08);
        m.rotation.y = -a;
        m.rotation.z = i % 2 ? 0.5 : -0.45;
        m.scale.y = 0.55 + (i % 3) * 0.45;
        m.visible = false;
        cracks.add(m);
      }
      noOutline(cracks);
      f.group.add(cracks);
      d.cracks = cracks;
      d.crackMeshes = cracks.children.slice();
      // Pooled smoke columns: thicker and faster as the fort drops through each stage.
      for (let i = 0; i < 20; i++) {
        const mat = new THREE.MeshBasicMaterial({ color: 0x413a4a, transparent: true, opacity: 0, depthWrite: false });
        const mesh = new THREE.Mesh(smokeGeo, mat);
        mesh.visible = false;
        noOutline(mesh);
        this.dyn.add(mesh);
        d.smoke.push({ mesh, mat, life: 0, max: 1, vx: 0, vy: 0, vz: 0, scale: 1 });
      }
      this._fortDamage[team] = d;
    }
  }

  /** Apply a damage stage (0 = pristine, 3 = critical) to one fort. */
  _applyFortStage(d, stage) {
    const f = this.board.forts[d.team];
    const dark = [1, 0.82, 0.68, 0.52][stage] ?? 1;
    for (const rec of d.mats) {
      if (rec.color && rec.mat.color) rec.mat.color.copy(rec.color).multiplyScalar(dark);
      if (rec.mat.emissive) rec.mat.emissive.setHex(rec.emissive);
    }
    const crackCount = [0, 2, 4, 6][stage] ?? 0;
    d.crackMeshes.forEach((m, i) => { m.visible = i < crackCount; });
    for (let i = 0; i < d.teeth.length; i++) {
      const p = d.teeth[i];
      p.mesh.visible = p.visible;
      p.mesh.position.set(p.x, p.y, p.z);
      p.mesh.rotation.x = p.rotX;
      p.mesh.rotation.z = p.rotZ;
      if (stage === 0) continue;
      const missing = stage === 1 ? (i % 7 === 0) : stage === 2 ? (i % 5 === 0 || i % 7 === 0) : (i % 3 === 0);
      if (missing) { p.mesh.visible = false; continue; }
      const tilt = stage === 1 ? 0.14 : stage === 2 ? 0.3 : 0.52;
      p.mesh.rotation.z += (i % 2 ? 1 : -1) * tilt;
      p.mesh.rotation.x += (i % 3 ? 0.6 : -0.4) * tilt;
      if (stage >= 2 && i % 4 === 0) p.mesh.position.y = p.y - 0.16;
    }
    const fb = d.flagBase;
    const droop = [0, 0.22, 0.55, 0.95][stage] ?? 0;
    const lower = [0, 0.18, 0.55, 1.05][stage] ?? 0;
    const torn = [1, 0.9, 0.7, 0.5][stage] ?? 1;
    f.flag.position.set(fb.x, fb.y - lower, fb.z);
    f.flag.rotation.z = fb.rotZ - droop;
    f.flag.scale.set(fb.scaleX * torn, fb.scaleY, fb.scaleZ);
    if (stage === 0) {
      d.smokeAcc = 0;
      for (const p of d.smoke) { p.life = 0; p.mesh.visible = false; p.mat.opacity = 0; }
    }
  }

  /** Stage crossing: debris chunks pop off with a puff and a shake. */
  _fortStageBreak(d, stage) {
    const f = this.board.forts[d.team];
    const fz = f.z ?? 0;
    this.fx.armor(f.x, fz, d.team, 4 + stage * 2);
    this.fx.puff(f.x - 1.6, fz - 1.1);
    this.fx.puff(f.x + 1.3, fz + 1.2);
    this.fx.puff(f.x, fz + 0.2);
    this.fx.addShake(0.35 + stage * 0.15);
  }

  _emitFortSmoke(d) {
    const f = this.board.forts[d.team];
    const p = d.smoke[d.smokeIdx];
    d.smokeIdx = (d.smokeIdx + 1) % d.smoke.length;
    const a = Math.random() * Math.PI * 2;
    const r = Math.random() * 1.9;
    p.mesh.position.set(f.x + Math.cos(a) * r, 2.1 + Math.random() * 2.9, Math.sin(a) * r);
    p.mesh.scale.setScalar(0.7 + d.stage * 0.35);
    p.mesh.visible = true;
    p.life = p.max = 1.35 + Math.random() * 0.8;
    p.vx = (Math.random() - 0.5) * 0.7;
    p.vz = (Math.random() - 0.5) * 0.7;
    p.vy = 1.1 + d.stage * 0.4 + Math.random() * 0.6;
    p.scale = 0.85 + d.stage * 0.5 + Math.random() * 0.35;
    p.mat.opacity = 0.42 + d.stage * 0.05;
  }

  /** Per-frame stage evaluation, smoke emission and puff animation. */
  _updateFortDamage(st, dt) {
    if (!this._fortDamage) return;
    for (const team of ['blue', 'red']) {
      const d = this._fortDamage[team];
      const fort = st?.forts?.[team];
      const frac = fort && fort.maxHp ? Math.max(0, fort.hp / fort.maxHp) : 1;
      const stage = frac <= 0.25 ? 3 : frac <= 0.5 ? 2 : frac <= 0.75 ? 1 : 0;
      if (stage !== d.stage) {
        const prev = d.stage;
        d.stage = stage;
        this._applyFortStage(d, stage);
        if (stage > prev) this._fortStageBreak(d, stage);
      }
      if (d.stage > 0 && fort && fort.hp > 0) {
        const interval = d.stage >= 3 ? 0.08 : d.stage === 2 ? 0.14 : 0.22;
        d.smokeAcc += dt;
        let guard = 0;
        while (d.smokeAcc >= interval && guard++ < 8) {
          d.smokeAcc -= interval;
          this._emitFortSmoke(d);
        }
      } else {
        d.smokeAcc = 0;
      }
      for (const p of d.smoke) {
        if (p.life <= 0) continue;
        p.life -= dt;
        if (p.life <= 0) { p.mesh.visible = false; p.mat.opacity = 0; continue; }
        const age = 1 - p.life / p.max;
        p.mesh.position.x += p.vx * dt;
        p.mesh.position.y += p.vy * dt;
        p.mesh.position.z += p.vz * dt;
        p.mesh.scale.setScalar(p.scale * (0.55 + age * 1.9));
        p.mat.opacity = (0.42 + d.stage * 0.05) * (1 - age);
      }
    }
  }

  /** Brief white/red flash + wobble, rate-limited so a big wave cannot strobe. */
  _fortHitFeedback(team) {
    const d = this._fortDamage?.[team];
    if (!d) return;
    if (this.time - d.feedbackAt < 0.12) return;
    d.feedbackAt = this.time;
    d.flash = 0.14;
    d.flashRed = !d.flashRed;
    d.flashColor = d.flashRed ? 0xff4d5e : 0xffffff;
    d.wobble = Math.min(0.55, d.wobble + 0.3);
    const f = this.board.forts[team];
    f.hit = Math.max(f.hit || 0, 0.18);
    if (team === this.localTeam) this.fx.addShake(0.1);
  }

  _resetFortDamage() {
    if (!this._fortDamage) return;
    for (const team of ['blue', 'red']) {
      const d = this._fortDamage[team];
      const f = this.board.forts[team];
      d.stage = 0;
      d.flash = 0;
      d.flashRed = false;
      d.wobble = 0;
      d.feedbackAt = -999;
      d.smokeAcc = 0;
      d.smokeIdx = 0;
      this._applyFortStage(d, 0);
      f.group.rotation.x = d.baseGroupRot.x;
      f.group.rotation.z = d.baseGroupRot.z;
      f.hit = 0;
      f.flag.rotation.y = d.flagBase.rotY;
      for (const p of d.smoke) { p.life = 0; p.mesh.visible = false; p.mat.opacity = 0; }
    }
  }

  dispose() {
    this.reset();
    this.fx.dispose();
    // Clean up spawn warning edge glow
    if (this._spawnWarn?.edgeGlow) {
      this._spawnWarn.edgeGlow.remove();
      this._spawnWarn.edgeGlow = null;
    }
    this.scene.remove(this.group);
  }
}
